/**************************************************************************
 * 0001_init.sql
 *************************************************************************/

-- 526 Detroit St. — household chores + expenses
-- Core idea, taken straight from the paper chart on the fridge:
-- every chore owns a fixed rotation of roommates (AB -> BK -> TT -> NA) and a
-- monotonically increasing turn counter. Turn N belongs to
-- members[N % members.length]. Completing a turn materializes turn N+1.
-- Scheduled chores (Floors, weekly Trash) get a due date; on-demand chores
-- (Dishes per load, Trash when full) are just a numbered queue, like the
-- 16 numbered rows on the sheet.

create extension if not exists "pgcrypto";

-- ---------------------------------------------------------------- households

create table if not exists households (
  id          uuid primary key default gen_random_uuid(),
  name        text        not null,
  address     text,
  timezone    text        not null default 'America/Detroit',
  created_at  timestamptz not null default now()
);

create table if not exists profiles (
  id            uuid primary key references auth.users(id) on delete cascade,
  household_id  uuid        references households(id) on delete set null,
  full_name     text        not null,
  initials      text        not null,           -- 'AB', 'NA', 'TT', 'BK'
  email         text,
  color         text        not null default '#64748b',
  avatar_url    text,
  is_admin      boolean     not null default false,
  -- notification preferences
  notify_push   boolean     not null default true,
  notify_email  boolean     not null default false,
  quiet_from    smallint    not null default 22, -- local hour, inclusive
  quiet_to      smallint    not null default 8,  -- local hour, exclusive
  created_at    timestamptz not null default now()
);

create index if not exists profiles_household_id_idx on profiles (household_id);

-- ------------------------------------------------------------------- chores

do $$ begin
  create type chore_cadence as enum ('scheduled', 'on_demand');
exception when duplicate_object then null;
end $$;
do $$ begin
  create type turn_status as enum ('pending', 'done', 'skipped', 'missed');
exception when duplicate_object then null;
end $$;

create table if not exists chores (
  id             uuid primary key default gen_random_uuid(),
  household_id   uuid not null references households(id) on delete cascade,
  name           text not null,
  emoji          text not null default '🧹',
  description    text,
  cadence        chore_cadence not null,

  -- scheduled cadence: "every `interval_weeks` weeks, on these weekdays"
  -- 0 = Sunday .. 6 = Saturday.  Floors = {0,5}; Microwave = {6} every 2 wks.
  days_of_week   smallint[] not null default '{}',
  interval_weeks smallint   not null default 1,
  anchor_date    date       not null default current_date,
  due_hour       smallint   not null default 20,  -- local hour the turn is "due"

  -- on-demand cadence: how many turns to keep visible in the queue
  queue_depth    smallint   not null default 4,

  -- how far ahead scheduled turns are materialized
  lookahead_days smallint   not null default 21,

  sort_order     smallint   not null default 0,
  is_active      boolean    not null default true,
  created_at     timestamptz not null default now()
);

create index if not exists chores_household_id_is_active_idx on chores (household_id, is_active);

-- The rotation order for a chore. `position` is 0-based and defines the cycle.
create table if not exists chore_rotation (
  chore_id    uuid     not null references chores(id) on delete cascade,
  profile_id  uuid     not null references profiles(id) on delete cascade,
  position    smallint not null,
  primary key (chore_id, profile_id),
  unique (chore_id, position) deferrable initially deferred
);

-- One row = one box on the paper chart.
create table if not exists chore_turns (
  id            uuid primary key default gen_random_uuid(),
  chore_id      uuid     not null references chores(id) on delete cascade,
  household_id  uuid     not null references households(id) on delete cascade,
  turn_number   integer  not null,            -- monotonic, 0-based
  assignee_id   uuid     not null references profiles(id) on delete cascade,
  status        turn_status not null default 'pending',
  due_at        timestamptz,                  -- null for on-demand turns
  completed_at  timestamptz,
  completed_by  uuid     references profiles(id) on delete set null,
  note          text,
  created_at    timestamptz not null default now(),
  unique (chore_id, turn_number)
);

create index if not exists chore_turns_household_id_status_due_at_idx on chore_turns (household_id, status, due_at);
create index if not exists chore_turns_chore_id_status_turn_number_idx on chore_turns (chore_id, status, turn_number);
create index if not exists chore_turns_assignee_id_status_idx on chore_turns (assignee_id, status);

-- Swap a turn with another roommate. Requires the other person to accept.
create table if not exists chore_swaps (
  id            uuid primary key default gen_random_uuid(),
  turn_id       uuid not null references chore_turns(id) on delete cascade,
  requested_by  uuid not null references profiles(id) on delete cascade,
  requested_to  uuid not null references profiles(id) on delete cascade,
  status        text not null default 'pending'
                  check (status in ('pending','accepted','declined','cancelled')),
  message       text,
  created_at    timestamptz not null default now(),
  resolved_at   timestamptz
);

create index if not exists chore_swaps_requested_to_status_idx on chore_swaps (requested_to, status);

-- ----------------------------------------------------------------- expenses

do $$ begin
  create type split_kind as enum ('equal', 'exact', 'shares', 'percent');
exception when duplicate_object then null;
end $$;

create table if not exists expenses (
  id            uuid primary key default gen_random_uuid(),
  household_id  uuid not null references households(id) on delete cascade,
  description   text not null,
  amount_cents  bigint not null check (amount_cents > 0),
  currency      char(3) not null default 'USD',
  category      text not null default 'general',
  paid_by       uuid not null references profiles(id) on delete restrict,
  spent_on      date not null default current_date,
  split_kind    split_kind not null default 'equal',
  receipt_url   text,
  note          text,
  created_by    uuid references profiles(id) on delete set null,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),
  deleted_at    timestamptz
);

create index if not exists expenses_household_id_spent_on_desc_idx on expenses (household_id, spent_on desc) where deleted_at is null;

-- Who owes what on a given expense. owed_cents across an expense must sum to
-- amount_cents; enforced in the app + a deferred trigger below.
create table if not exists expense_splits (
  expense_id  uuid   not null references expenses(id) on delete cascade,
  profile_id  uuid   not null references profiles(id) on delete cascade,
  owed_cents  bigint not null check (owed_cents >= 0),
  weight      numeric(10,4),   -- shares or percent, kept for re-editing
  primary key (expense_id, profile_id)
);

-- A real transfer of money between two roommates (Venmo, cash, etc).
create table if not exists settlements (
  id            uuid primary key default gen_random_uuid(),
  household_id  uuid not null references households(id) on delete cascade,
  from_profile  uuid not null references profiles(id) on delete restrict,
  to_profile    uuid not null references profiles(id) on delete restrict,
  amount_cents  bigint not null check (amount_cents > 0),
  settled_on    date not null default current_date,
  method        text not null default 'venmo',
  note          text,
  created_by    uuid references profiles(id) on delete set null,
  created_at    timestamptz not null default now(),
  check (from_profile <> to_profile)
);

create index if not exists settlements_household_id_settled_on_desc_idx on settlements (household_id, settled_on desc);

-- ------------------------------------------------------- devices & activity

create table if not exists push_subscriptions (
  id          uuid primary key default gen_random_uuid(),
  profile_id  uuid not null references profiles(id) on delete cascade,
  endpoint    text not null unique,
  p256dh      text not null,
  auth        text not null,
  user_agent  text,
  created_at  timestamptz not null default now(),
  last_used_at timestamptz
);

create index if not exists push_subscriptions_profile_id_idx on push_subscriptions (profile_id);

-- The iPad on the wall. Authenticates with a bearer token instead of a user.
create table if not exists kiosk_devices (
  id            uuid primary key default gen_random_uuid(),
  household_id  uuid not null references households(id) on delete cascade,
  name          text not null,
  token_hash    text not null unique,
  last_seen_at  timestamptz,
  created_at    timestamptz not null default now()
);

create table if not exists activity_log (
  id            bigserial primary key,
  household_id  uuid not null references households(id) on delete cascade,
  actor_id      uuid references profiles(id) on delete set null,
  verb          text not null,          -- 'completed_chore', 'added_expense', ...
  summary       text not null,          -- pre-rendered, for the kiosk feed
  metadata      jsonb not null default '{}',
  created_at    timestamptz not null default now()
);

create index if not exists activity_log_household_id_created_at_desc_idx on activity_log (household_id, created_at desc);

-- ------------------------------------------------------------------- views

-- Net position per roommate. Positive => the household owes them money.
create or replace view v_balances with (security_invoker = true) as
with paid as (
  select e.household_id, e.paid_by as profile_id, sum(e.amount_cents) as cents
  from expenses e where e.deleted_at is null
  group by 1, 2
),
owed as (
  select e.household_id, s.profile_id, sum(s.owed_cents) as cents
  from expense_splits s
  join expenses e on e.id = s.expense_id and e.deleted_at is null
  group by 1, 2
),
sent as (
  select household_id, from_profile as profile_id, sum(amount_cents) as cents
  from settlements group by 1, 2
),
received as (
  select household_id, to_profile as profile_id, sum(amount_cents) as cents
  from settlements group by 1, 2
)
select
  p.household_id,
  p.id as profile_id,
  coalesce(paid.cents, 0)
    - coalesce(owed.cents, 0)
    + coalesce(sent.cents, 0)
    - coalesce(received.cents, 0) as net_cents
from profiles p
left join paid     on paid.profile_id     = p.id and paid.household_id     = p.household_id
left join owed     on owed.profile_id     = p.id and owed.household_id     = p.household_id
left join sent     on sent.profile_id     = p.id and sent.household_id     = p.household_id
left join received on received.profile_id = p.id and received.household_id = p.household_id
where p.household_id is not null;

-- Running tally of completed turns per person per chore — the digital version
-- of counting crossed-out initials on the sheet.
create or replace view v_chore_stats with (security_invoker = true) as
select
  t.household_id,
  t.chore_id,
  t.assignee_id as profile_id,
  count(*) filter (where t.status = 'done')    as done_count,
  count(*) filter (where t.status = 'missed')  as missed_count,
  max(t.completed_at)                          as last_done_at
from chore_turns t
group by 1, 2, 3;


/**************************************************************************
 * 0002_logic.sql
 *************************************************************************/

-- Rotation engine + row level security.

-- --------------------------------------------------------------- helpers

-- SECURITY DEFINER so RLS policies can call it without recursing into
-- the profiles policy that is itself being evaluated.
create or replace function current_household_id()
returns uuid
language sql
stable
security definer
set search_path = public
as $$
  select household_id from profiles where id = auth.uid();
$$;

create or replace function is_household_member(target uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select target is not null and target = (
    select household_id from profiles where id = auth.uid()
  );
$$;

-- New auth user -> profile. Metadata is set at invite time.
create or replace function handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  insert into profiles (id, email, full_name, initials, household_id)
  values (
    new.id,
    new.email,
    coalesce(new.raw_user_meta_data ->> 'full_name', split_part(new.email, '@', 1)),
    coalesce(new.raw_user_meta_data ->> 'initials', upper(left(coalesce(new.raw_user_meta_data ->> 'full_name', new.email), 2))),
    (new.raw_user_meta_data ->> 'household_id')::uuid
  )
  on conflict (id) do update
    set email = excluded.email;
  return new;
end;
$$;

drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function handle_new_user();

-- ------------------------------------------------------- rotation engine

-- Who owns turn N of a chore?
create or replace function rotation_assignee(p_chore uuid, p_turn integer)
returns uuid
language plpgsql
stable
as $$
declare
  n int;
  who uuid;
begin
  select count(*) into n from chore_rotation where chore_rotation.chore_id = p_chore;
  if n = 0 then
    return null;
  end if;
  select profile_id into who
  from chore_rotation
  where chore_rotation.chore_id = p_chore
    and chore_rotation.position = (p_turn % n)
  limit 1;
  return who;
end;
$$;

-- Append the next turn in the cycle. Returns the new turn, or null if the
-- chore has no rotation configured.
create or replace function append_turn(p_chore uuid, p_due timestamptz default null)
returns chore_turns
language plpgsql
security definer
set search_path = public
as $$
declare
  next_no  int;
  who      uuid;
  hh       uuid;
  new_turn chore_turns;
begin
  select household_id into hh from chores where id = p_chore;
  select coalesce(max(turn_number), -1) + 1 into next_no
    from chore_turns where chore_id = p_chore;

  who := rotation_assignee(p_chore, next_no);
  if who is null then
    return null;
  end if;

  insert into chore_turns (chore_id, household_id, turn_number, assignee_id, due_at)
  values (p_chore, hh, next_no, who, p_due)
  returning * into new_turn;

  return new_turn;
end;
$$;

-- Keep `queue_depth` pending turns available for an on-demand chore, so the
-- kiosk can always show "up next" the way the numbered rows on the sheet do.
create or replace function top_up_queue(p_chore uuid)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  want    int;
  have    int;
  made    int := 0;
begin
  select queue_depth into want from chores where id = p_chore and cadence = 'on_demand';
  if want is null then
    return 0;
  end if;

  select count(*) into have
    from chore_turns where chore_id = p_chore and status = 'pending';

  while have + made < want loop
    perform append_turn(p_chore, null);
    made := made + 1;
  end loop;

  return made;
end;
$$;

-- Materialize scheduled turns out to the chore's lookahead window.
-- A week is "on" when its offset from the anchor week is a multiple of
-- interval_weeks -- that is how "biweekly on weekends" stays in phase.
create or replace function materialize_schedule(p_chore uuid)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  c        chores%rowtype;
  tz       text;
  cursor_d date;
  last_d   date;
  horizon  date;
  made     int := 0;
  wk_off   int;
  anchor_w date;
begin
  select * into c from chores where id = p_chore and cadence = 'scheduled' and is_active;
  if not found or array_length(c.days_of_week, 1) is null then
    return 0;
  end if;

  select timezone into tz from households where id = c.household_id;
  horizon  := (now() at time zone tz)::date + c.lookahead_days;
  anchor_w := date_trunc('week', c.anchor_date)::date;   -- Monday-based

  -- resume after the furthest turn we already created
  select max((due_at at time zone tz)::date) into last_d
    from chore_turns where chore_id = p_chore;

  cursor_d := greatest(
    coalesce(last_d + 1, c.anchor_date),
    (now() at time zone tz)::date
  );

  while cursor_d <= horizon loop
    wk_off := ((date_trunc('week', cursor_d)::date - anchor_w) / 7)::int;
    if (extract(dow from cursor_d)::smallint = any (c.days_of_week))
       and (wk_off % greatest(c.interval_weeks, 1) = 0) then
      perform append_turn(
        p_chore,
        ((cursor_d + make_interval(hours => c.due_hour)) at time zone tz)
      );
      made := made + 1;
    end if;
    cursor_d := cursor_d + 1;
  end loop;

  return made;
end;
$$;

-- Complete a turn and immediately open the next one, so there is never a
-- moment where nobody is "up".
create or replace function complete_turn(p_turn uuid, p_note text default null)
returns chore_turns
language plpgsql
security definer
set search_path = public
as $$
declare
  t   chore_turns%rowtype;
  c   chores%rowtype;
  me  uuid := auth.uid();
begin
  select * into t from chore_turns where id = p_turn for update;
  if not found then
    raise exception 'turn not found';
  end if;
  if not is_household_member(t.household_id) then
    raise exception 'not your household';
  end if;
  if t.status = 'done' then
    return t;
  end if;

  update chore_turns
     set status = 'done', completed_at = now(), completed_by = coalesce(me, t.assignee_id), note = p_note
   where id = p_turn
  returning * into t;

  select * into c from chores where id = t.chore_id;

  if c.cadence = 'on_demand' then
    perform top_up_queue(t.chore_id);
  else
    perform materialize_schedule(t.chore_id);
  end if;

  insert into activity_log (household_id, actor_id, verb, summary, metadata)
  select t.household_id, coalesce(me, t.assignee_id), 'completed_chore',
         p.full_name || ' did ' || c.name,
         jsonb_build_object('chore_id', c.id, 'turn_id', t.id, 'emoji', c.emoji)
  from profiles p where p.id = coalesce(me, t.assignee_id);

  return t;
end;
$$;

-- Called by the "dishwasher is full" / "trash is full" buttons: nothing to
-- create (the queue is already primed) but it timestamps the request and
-- pings whoever is up.
create or replace function flag_on_demand(p_chore uuid)
returns chore_turns
language plpgsql
security definer
set search_path = public
as $$
declare
  t chore_turns%rowtype;
  c chores%rowtype;
begin
  select * into c from chores where id = p_chore;
  if not is_household_member(c.household_id) then
    raise exception 'not your household';
  end if;

  perform top_up_queue(p_chore);

  select * into t from chore_turns
   where chore_id = p_chore and status = 'pending'
   order by turn_number limit 1;

  update chore_turns set due_at = now() where id = t.id and due_at is null;

  insert into activity_log (household_id, actor_id, verb, summary, metadata)
  select c.household_id, auth.uid(), 'flagged_chore',
         c.name || ' needs doing',
         jsonb_build_object('chore_id', c.id, 'turn_id', t.id, 'emoji', c.emoji);

  return t;
end;
$$;

-- Accepting a swap just reassigns the turn; the rotation itself is untouched,
-- so the cycle stays in order for everyone after.
create or replace function accept_swap(p_swap uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  s chore_swaps%rowtype;
begin
  select * into s from chore_swaps where id = p_swap for update;
  if not found or s.status <> 'pending' then
    raise exception 'swap not open';
  end if;
  if s.requested_to <> auth.uid() then
    raise exception 'not your swap to accept';
  end if;

  update chore_turns set assignee_id = s.requested_to where id = s.turn_id;
  update chore_swaps set status = 'accepted', resolved_at = now() where id = p_swap;
end;
$$;

-- ------------------------------------------------------------------- RLS

alter table households        enable row level security;
alter table profiles          enable row level security;
alter table chores            enable row level security;
alter table chore_rotation    enable row level security;
alter table chore_turns       enable row level security;
alter table chore_swaps       enable row level security;
alter table expenses          enable row level security;
alter table expense_splits    enable row level security;
alter table settlements       enable row level security;
alter table push_subscriptions enable row level security;
alter table kiosk_devices     enable row level security;
alter table activity_log      enable row level security;

drop policy if exists hh_read on households;
create policy hh_read on households for select
  using (id = current_household_id());

drop policy if exists pr_read on profiles;
create policy pr_read on profiles for select
  using (household_id = current_household_id() or id = auth.uid());
drop policy if exists pr_write on profiles;
create policy pr_write on profiles for update
  using (id = auth.uid()) with check (id = auth.uid());

drop policy if exists ch_all on chores;
create policy ch_all on chores for all
  using (is_household_member(household_id))
  with check (is_household_member(household_id));

drop policy if exists rot_all on chore_rotation;
create policy rot_all on chore_rotation for all
  using (exists (select 1 from chores c where c.id = chore_id and is_household_member(c.household_id)))
  with check (exists (select 1 from chores c where c.id = chore_id and is_household_member(c.household_id)));

drop policy if exists turn_all on chore_turns;
create policy turn_all on chore_turns for all
  using (is_household_member(household_id))
  with check (is_household_member(household_id));

drop policy if exists swap_all on chore_swaps;
create policy swap_all on chore_swaps for all
  using (exists (select 1 from chore_turns t where t.id = turn_id and is_household_member(t.household_id)))
  with check (exists (select 1 from chore_turns t where t.id = turn_id and is_household_member(t.household_id)));

drop policy if exists exp_all on expenses;
create policy exp_all on expenses for all
  using (is_household_member(household_id))
  with check (is_household_member(household_id));

drop policy if exists split_all on expense_splits;
create policy split_all on expense_splits for all
  using (exists (select 1 from expenses e where e.id = expense_id and is_household_member(e.household_id)))
  with check (exists (select 1 from expenses e where e.id = expense_id and is_household_member(e.household_id)));

drop policy if exists settle_all on settlements;
create policy settle_all on settlements for all
  using (is_household_member(household_id))
  with check (is_household_member(household_id));

drop policy if exists push_own on push_subscriptions;
create policy push_own on push_subscriptions for all
  using (profile_id = auth.uid()) with check (profile_id = auth.uid());

drop policy if exists kiosk_read on kiosk_devices;
create policy kiosk_read on kiosk_devices for select
  using (is_household_member(household_id));

drop policy if exists act_read on activity_log;
create policy act_read on activity_log for select
  using (is_household_member(household_id));
drop policy if exists act_insert on activity_log;
create policy act_insert on activity_log for insert
  with check (is_household_member(household_id));

-- Views are created with security_invoker = true in 0001 so they honour the
-- caller's RLS rather than the view owner's.


/**************************************************************************
 * 0003_invites_and_oauth.sql
 *************************************************************************/

-- Run this on a database that already has 0001 and 0002.
--
-- Two changes:
--   1. Re-state security_invoker on the views in the exact form Supabase's
--      linter recognizes. `= on` and `= true` behave identically in Postgres,
--      but reloptions stores the literal token and the linter matches on
--      'true', so `on` gets reported as SECURITY DEFINER.
--   2. Decouple "who belongs to this household" from *how* they sign in, so
--      Google, magic link, or anything else all land in the right place.

alter view v_balances    set (security_invoker = true);
alter view v_chore_stats set (security_invoker = true);

-- ----------------------------------------------------------------- invites

-- The roster, keyed by email. Whoever first signs in with an invited address
-- gets that identity — name, initials, color, household — regardless of which
-- provider they used. Without this, a Google sign-in creates a profile with no
-- household and the app can only show "you're not in a household yet".
create table if not exists household_invites (
  email         text primary key,
  household_id  uuid not null references households(id) on delete cascade,
  full_name     text not null,
  initials      text not null,
  color         text not null default '#64748b',
  is_admin      boolean not null default false,
  created_at    timestamptz not null default now()
);

create index if not exists household_invites_household_idx
  on household_invites (household_id);

alter table household_invites enable row level security;

drop policy if exists inv_read on household_invites;
create policy inv_read on household_invites for select
  using (is_household_member(household_id));

-- ------------------------------------------------------------ new user hook

create or replace function handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  inv       household_invites%rowtype;
  meta      jsonb := coalesce(new.raw_user_meta_data, '{}'::jsonb);
  resolved  text;
begin
  -- Emails are case-insensitive in practice; invites should be too.
  select * into inv
  from household_invites
  where lower(household_invites.email) = lower(new.email);

  -- Google sends 'full_name' and/or 'name'; magic-link users have whatever the
  -- seed script set; fall back to the local part of the address.
  resolved := coalesce(
    inv.full_name,
    nullif(meta ->> 'full_name', ''),
    nullif(meta ->> 'name', ''),
    split_part(new.email, '@', 1)
  );

  insert into profiles (
    id, email, full_name, initials, household_id, color, avatar_url, is_admin
  )
  values (
    new.id,
    new.email,
    resolved,
    coalesce(inv.initials, nullif(meta ->> 'initials', ''), upper(left(resolved, 2))),
    coalesce(inv.household_id, (nullif(meta ->> 'household_id', ''))::uuid),
    coalesce(inv.color, '#64748b'),
    coalesce(nullif(meta ->> 'avatar_url', ''), nullif(meta ->> 'picture', '')),
    coalesce(inv.is_admin, false)
  )
  on conflict (id) do update set
    email      = excluded.email,
    -- Never clobber an established profile: a second identity linking to the
    -- same user (magic link, then Google) must not reset their household.
    full_name  = coalesce(profiles.full_name, excluded.full_name),
    avatar_url = coalesce(excluded.avatar_url, profiles.avatar_url),
    household_id = coalesce(profiles.household_id, excluded.household_id);

  return new;
end;
$$;

drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function handle_new_user();

-- Backfill invites for anyone already seeded, so the roster is complete even
-- if the household was set up before this migration existed.
-- Guarded by NOT EXISTS rather than ON CONFLICT: 0004 drops the email primary
-- key, so by the time this file is re-applied there is no unique constraint on
-- email for a conflict target to reference.
insert into household_invites (email, household_id, full_name, initials, color, is_admin)
select p.email, p.household_id, p.full_name, p.initials, p.color, p.is_admin
from profiles p
where p.email is not null
  and p.household_id is not null
  and not exists (
    select 1 from household_invites hi
    where lower(hi.email) = lower(p.email)
  );


/**************************************************************************
 * 0004_multi_household.sql
 *************************************************************************/

-- Turns Domestic from "one hardcoded house" into something any household can
-- deploy and run themselves.
--
--   * invites become shareable codes, not just pre-registered emails
--   * households are created in-app by whoever signs up first
--   * joining a household appends you to every rotation, mid-cycle, safely
--   * the kiosk is bound to a household by device record, not an env var
--   * closes a privilege escalation in the profiles update policy

/* ------------------------------------------------------------------ helpers */

create or replace function is_household_admin()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select coalesce((select is_admin from profiles where id = auth.uid()), false);
$$;

-- Crockford-ish alphabet: no I, L, O, U, 0 or 1, because these get read aloud
-- and typed on an iPad.
create or replace function generate_invite_code()
returns text
language plpgsql
volatile
as $$
declare
  alphabet text := '23456789ABCDEFGHJKMNPQRSTVWXYZ';
  candidate text;
  i int;
begin
  loop
    candidate := '';
    for i in 1..8 loop
      candidate := candidate || substr(alphabet, 1 + floor(random() * length(alphabet))::int, 1);
      if i = 4 then candidate := candidate || '-'; end if;
    end loop;
    exit when not exists (select 1 from household_invites where code = candidate);
  end loop;
  return candidate;
end;
$$;

/* ------------------------------------------------------------- invite table */

-- 0003 keyed invites by email. Re-shape to a row-per-invite with a shareable
-- code; email becomes an optional restriction rather than the identity.
alter table household_invites
  add column if not exists id uuid not null default gen_random_uuid(),
  add column if not exists code text,
  add column if not exists created_by uuid references profiles(id) on delete set null,
  add column if not exists expires_at timestamptz,
  add column if not exists max_uses integer not null default 1,
  add column if not exists used_count integer not null default 0,
  add column if not exists revoked_at timestamptz;

update household_invites set code = generate_invite_code() where code is null;

do $$
begin
  if exists (
    select 1 from pg_constraint
    where conname = 'household_invites_pkey' and conrelid = 'household_invites'::regclass
  ) then
    alter table household_invites drop constraint household_invites_pkey;
  end if;
end $$;

-- In 0003 email was the primary key and full_name/initials were required. All
-- three are optional now: email restricts an invite to one address, and the
-- name fields are prefill hints on a link anyone can accept. These run after
-- the primary key is gone — you cannot drop NOT NULL from a PK column.
alter table household_invites alter column email     drop not null;
alter table household_invites alter column full_name drop not null;
alter table household_invites alter column initials  drop not null;

-- Default it too, so a hand-written insert (or the 0003 backfill) still gets a
-- usable code instead of failing the not-null.
alter table household_invites alter column code set default generate_invite_code();
alter table household_invites alter column code set not null;
alter table household_invites add primary key (id);

create unique index if not exists household_invites_code_key on household_invites (code);
create index if not exists household_invites_email_idx on household_invites (lower(email));

/* ------------------------------------------------------- rotation membership */

-- Pending turns are re-derived from the current rotation. Completed turns are
-- history and are never touched — otherwise adding a roommate would rewrite
-- who did the dishes last Tuesday.
create or replace function resync_pending_turns(p_chore uuid)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare touched int := 0;
begin
  with fixed as (
    update chore_turns t
       set assignee_id = rotation_assignee(t.chore_id, t.turn_number)
     where t.chore_id = p_chore
       and t.status = 'pending'
       and t.assignee_id is distinct from rotation_assignee(t.chore_id, t.turn_number)
    returning 1
  )
  select count(*) into touched from fixed;
  return touched;
end;
$$;

-- Appends someone to the end of every active rotation in the household.
create or replace function add_to_rotations(p_profile uuid, p_household uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare c record;
begin
  for c in select id from chores where household_id = p_household and is_active loop
    if not exists (
      select 1 from chore_rotation
      where chore_id = c.id and profile_id = p_profile
    ) then
      insert into chore_rotation (chore_id, profile_id, position)
      select c.id, p_profile,
             coalesce(max(position), -1) + 1
      from chore_rotation where chore_id = c.id;

      perform resync_pending_turns(c.id);
    end if;
  end loop;
end;
$$;

-- Removing someone must close the gap in `position`, or `turn % n` starts
-- pointing at a hole and assignments go null.
create or replace function remove_from_rotations(p_profile uuid, p_household uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare c record;
begin
  for c in select id from chores where household_id = p_household loop
    delete from chore_rotation where chore_id = c.id and profile_id = p_profile;

    with renumbered as (
      select profile_id, row_number() over (order by position) - 1 as new_position
      from chore_rotation where chore_id = c.id
    )
    update chore_rotation r
       set position = renumbered.new_position
      from renumbered
     where r.chore_id = c.id and r.profile_id = renumbered.profile_id;

    perform resync_pending_turns(c.id);
  end loop;
end;
$$;

/* --------------------------------------------------------- create household */

create or replace function create_household(
  p_name      text,
  p_address   text default null,
  p_timezone  text default 'America/Detroit',
  p_full_name text default null,
  p_initials  text default null
)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  me       uuid := auth.uid();
  new_id   uuid;
  chore_id uuid;
  existing uuid;
begin
  if me is null then
    raise exception 'not signed in';
  end if;

  select household_id into existing from profiles where id = me;
  if existing is not null then
    raise exception 'you are already in a household';
  end if;

  insert into households (name, address, timezone)
  values (trim(p_name), nullif(trim(coalesce(p_address, '')), ''), p_timezone)
  returning id into new_id;

  update profiles
     set household_id = new_id,
         is_admin     = true,
         full_name    = coalesce(nullif(trim(coalesce(p_full_name, '')), ''), full_name),
         initials     = coalesce(nullif(upper(trim(coalesce(p_initials, ''))), ''), initials)
   where id = me;

  -- A starter set. Every field is editable afterwards; the point is that a new
  -- household has something on the board instead of an empty screen.
  for chore_id in
    insert into chores (household_id, name, emoji, description, cadence,
                        days_of_week, interval_weeks, due_hour, queue_depth, sort_order)
    values
      (new_id, 'Floors', '🧹', 'Sweep and mop the common areas', 'scheduled', '{0,5}', 1, 20, 4, 1),
      (new_id, 'Microwave', '🍲', 'Wipe out the microwave', 'scheduled', '{6}', 2, 20, 4, 2),
      (new_id, 'Trash to curb', '🗑️', 'Bins out the night before pickup', 'scheduled', '{0}', 1, 19, 4, 3),
      (new_id, 'Dishes', '🍽️', 'Run and unload a load', 'on_demand', '{}', 1, 20, 4, 4),
      (new_id, 'Trash when full', '🚮', 'Swap the kitchen bag', 'on_demand', '{}', 1, 20, 4, 5)
    returning id
  loop
    insert into chore_rotation (chore_id, profile_id, position) values (chore_id, me, 0);
  end loop;

  -- Fill the board so the first screen isn't empty.
  for chore_id in select id from chores where household_id = new_id loop
    if (select cadence from chores where id = chore_id) = 'scheduled' then
      perform materialize_schedule(chore_id);
    else
      perform top_up_queue(chore_id);
    end if;
  end loop;

  insert into activity_log (household_id, actor_id, verb, summary)
  values (new_id, me, 'created_household',
          (select full_name from profiles where id = me) || ' started the house');

  return new_id;
end;
$$;

/* ---------------------------------------------------------------- invites */

create or replace function create_invite(
  p_email      text default null,
  p_full_name  text default null,
  p_initials   text default null,
  p_color      text default '#64748b',
  p_expires_in interval default interval '14 days',
  p_max_uses   integer default 1
)
returns household_invites
language plpgsql
security definer
set search_path = public
as $$
declare
  me   uuid := auth.uid();
  hh   uuid;
  row_out household_invites;
begin
  select household_id into hh from profiles where id = me;
  if hh is null then raise exception 'you are not in a household'; end if;
  if not is_household_admin() then raise exception 'only an admin can invite people'; end if;

  insert into household_invites (
    household_id, code, email, full_name, initials, color,
    created_by, expires_at, max_uses
  )
  values (
    hh, generate_invite_code(), nullif(lower(trim(coalesce(p_email, ''))), ''),
    nullif(trim(coalesce(p_full_name, '')), ''),
    nullif(upper(trim(coalesce(p_initials, ''))), ''),
    coalesce(p_color, '#64748b'),
    me,
    case when p_expires_in is null then null else now() + p_expires_in end,
    greatest(coalesce(p_max_uses, 1), 1)
  )
  returning * into row_out;

  return row_out;
end;
$$;

create or replace function revoke_invite(p_invite uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare hh uuid;
begin
  if not is_household_admin() then raise exception 'only an admin can revoke invites'; end if;
  select household_id into hh from profiles where id = auth.uid();

  update household_invites
     set revoked_at = now()
   where id = p_invite and household_id = hh and revoked_at is null;
end;
$$;

-- What a signed-in user sees before accepting, so the join screen can say
-- which house they are about to join without leaking anything else.
create or replace function peek_invite(p_code text)
returns table (household_name text, full_name text, initials text, valid boolean, reason text)
language plpgsql
security definer
set search_path = public
as $$
declare
  inv household_invites%rowtype;
  my_email text;
begin
  select * into inv from household_invites
   where upper(code) = upper(trim(p_code));

  if not found then
    return query select null::text, null::text, null::text, false, 'That code does not exist.';
    return;
  end if;

  select email into my_email from profiles where id = auth.uid();

  if inv.revoked_at is not null then
    return query select null::text, null::text, null::text, false, 'That invite was revoked.';
  elsif inv.expires_at is not null and inv.expires_at < now() then
    return query select null::text, null::text, null::text, false, 'That invite has expired.';
  elsif inv.used_count >= inv.max_uses then
    return query select null::text, null::text, null::text, false, 'That invite has already been used.';
  elsif inv.email is not null and lower(inv.email) is distinct from lower(coalesce(my_email, '')) then
    return query select null::text, null::text, null::text, false,
                        'That invite was issued to a different email address.';
  else
    return query
      select h.name, inv.full_name, inv.initials, true, null::text
      from households h where h.id = inv.household_id;
  end if;
end;
$$;

create or replace function redeem_invite(
  p_code      text,
  p_full_name text default null,
  p_initials  text default null
)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  me       uuid := auth.uid();
  inv      household_invites%rowtype;
  my_email text;
  existing uuid;
  resolved_name text;
begin
  if me is null then raise exception 'not signed in'; end if;

  select household_id, email into existing, my_email from profiles where id = me;
  if existing is not null then raise exception 'you are already in a household'; end if;

  -- Lock the row: two people redeeming a single-use code at the same moment
  -- must not both get in.
  select * into inv from household_invites
   where upper(code) = upper(trim(p_code))
   for update;

  if not found then raise exception 'That code does not exist.'; end if;
  if inv.revoked_at is not null then raise exception 'That invite was revoked.'; end if;
  if inv.expires_at is not null and inv.expires_at < now() then
    raise exception 'That invite has expired.';
  end if;
  if inv.used_count >= inv.max_uses then
    raise exception 'That invite has already been used.';
  end if;
  if inv.email is not null and lower(inv.email) is distinct from lower(coalesce(my_email, '')) then
    raise exception 'That invite was issued to a different email address.';
  end if;

  resolved_name := coalesce(
    nullif(trim(coalesce(p_full_name, '')), ''),
    inv.full_name,
    (select full_name from profiles where id = me)
  );

  update profiles
     set household_id = inv.household_id,
         full_name    = resolved_name,
         initials     = coalesce(
                          nullif(upper(trim(coalesce(p_initials, ''))), ''),
                          inv.initials,
                          upper(left(resolved_name, 2))
                        ),
         color        = coalesce(inv.color, color),
         is_admin     = coalesce(inv.is_admin, false)
   where id = me;

  update household_invites set used_count = used_count + 1 where id = inv.id;

  perform add_to_rotations(me, inv.household_id);

  insert into activity_log (household_id, actor_id, verb, summary)
  values (inv.household_id, me, 'joined_household', resolved_name || ' joined the house');

  return inv.household_id;
end;
$$;

-- Admins can remove someone; the rotation closes up behind them.
create or replace function remove_member(p_profile uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare hh uuid;
begin
  if not is_household_admin() then raise exception 'only an admin can remove someone'; end if;
  if p_profile = auth.uid() then raise exception 'you cannot remove yourself'; end if;

  select household_id into hh from profiles where id = auth.uid();
  if not exists (select 1 from profiles where id = p_profile and household_id = hh) then
    raise exception 'that person is not in your household';
  end if;

  perform remove_from_rotations(p_profile, hh);
  update profiles set household_id = null, is_admin = false where id = p_profile;
end;
$$;

create or replace function set_member_admin(p_profile uuid, p_is_admin boolean)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare hh uuid;
begin
  if not is_household_admin() then raise exception 'only an admin can change roles'; end if;
  select household_id into hh from profiles where id = auth.uid();

  update profiles set is_admin = p_is_admin
   where id = p_profile and household_id = hh;

  if not exists (select 1 from profiles where household_id = hh and is_admin) then
    raise exception 'a household needs at least one admin';
  end if;
end;
$$;

/* ------------------------------------------------------------ kiosk devices */

alter table kiosk_devices
  add column if not exists created_by uuid references profiles(id) on delete set null;

-- Pairing code is shown once at creation; only its hash is stored.
create or replace function create_kiosk_device(p_name text)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  hh   uuid;
  code text;
begin
  if not is_household_admin() then raise exception 'only an admin can pair a kiosk'; end if;
  select household_id into hh from profiles where id = auth.uid();
  if hh is null then raise exception 'you are not in a household'; end if;

  code := encode(gen_random_bytes(24), 'base64');
  code := replace(replace(replace(code, '+', '-'), '/', '_'), '=', '');

  insert into kiosk_devices (household_id, name, token_hash, created_by)
  values (hh, coalesce(nullif(trim(p_name), ''), 'Kiosk'),
          encode(digest(code, 'sha256'), 'hex'), auth.uid());

  return code;
end;
$$;

-- Called by the pairing route with the service role; resolves a raw token to
-- the household it belongs to. Constant-time-ish: we look up by hash, never
-- compare secrets in application code.
create or replace function resolve_kiosk_token(p_token text)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare hh uuid;
begin
  update kiosk_devices
     set last_seen_at = now()
   where token_hash = encode(digest(p_token, 'sha256'), 'hex')
  returning household_id into hh;

  return hh;
end;
$$;

/* --------------------------------------------------------------------- RLS */

drop policy if exists inv_read on household_invites;
create policy inv_read on household_invites for select
  using (is_household_member(household_id));

drop policy if exists kiosk_read on kiosk_devices;
create policy kiosk_read on kiosk_devices for select
  using (is_household_member(household_id));

-- Membership and role changes go through the SECURITY DEFINER functions above.
-- Without this, `pr_write` lets anyone set their own household_id to another
-- household's uuid and read that entire house — harmless with one household,
-- a full data breach with two.
do $$
declare r text;
begin
  foreach r in array array['authenticated', 'domestic_app'] loop
    if exists (select 1 from pg_roles where rolname = r) then
      execute format('revoke update on profiles from %I', r);
      execute format(
        'grant update (full_name, initials, color, avatar_url, notify_push,
                       notify_email, quiet_from, quiet_to) on profiles to %I', r);
      execute format('grant execute on all functions in schema public to %I', r);
    end if;
  end loop;
end $$;


/**************************************************************************
 * 0005_modules.sql
 *************************************************************************/

-- Every house runs differently. A household turns components on and off
-- instead of inheriting whatever 526 Detroit St. happens to do.
--
-- The registry itself lives in TypeScript (src/lib/modules.ts) — this table
-- only records which keys a household has enabled and any per-module settings,
-- so adding a module is a code change, not a migration.

create table if not exists household_modules (
  household_id uuid    not null references households(id) on delete cascade,
  module       text    not null,
  enabled      boolean not null default true,
  settings     jsonb   not null default '{}',
  updated_at   timestamptz not null default now(),
  updated_by   uuid references profiles(id) on delete set null,
  primary key (household_id, module)
);

alter table household_modules enable row level security;

drop policy if exists mod_read on household_modules;
create policy mod_read on household_modules for select
  using (is_household_member(household_id));

-- Writes go through set_module() so the admin check lives in one place.
create or replace function set_module(
  p_module   text,
  p_enabled  boolean,
  p_settings jsonb default null
)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare hh uuid;
begin
  if not is_household_admin() then
    raise exception 'only an admin can change what this household uses';
  end if;

  select household_id into hh from profiles where id = auth.uid();
  if hh is null then raise exception 'you are not in a household'; end if;

  insert into household_modules (household_id, module, enabled, settings, updated_by)
  values (hh, p_module, p_enabled, coalesce(p_settings, '{}'::jsonb), auth.uid())
  on conflict (household_id, module) do update
    set enabled    = excluded.enabled,
        settings   = coalesce(p_settings, household_modules.settings),
        updated_at = now(),
        updated_by = auth.uid();
end;
$$;

-- A household with no row for a module falls back to this. Keeping the default
-- in one function means an existing household picks up a newly shipped module
-- without a backfill.
create or replace function default_modules()
returns text[]
language sql
immutable
as $$
  select array['chores', 'expenses', 'kiosk'];
$$;

create or replace function enabled_modules(p_household uuid)
returns text[]
language sql
stable
security definer
set search_path = public
as $$
  select coalesce(
    array_agg(m.module order by m.module) filter (where m.enabled),
    '{}'::text[]
  ) || (
    -- defaults that have never been explicitly toggled
    select coalesce(array_agg(d order by d), '{}'::text[])
    from unnest(default_modules()) d
    where not exists (
      select 1 from household_modules x
      where x.household_id = p_household and x.module = d
    )
  )
  from household_modules m
  where m.household_id = p_household;
$$;

-- New households start with the defaults written explicitly, so the admin
-- screen shows real toggles rather than implied state.
--
-- `create or replace` cannot add a parameter, even a defaulted one — it creates
-- an overload, and every existing 5-argument call then fails as ambiguous. Drop
-- the 0004 signature first.
drop function if exists create_household(text, text, text, text, text);

-- `or replace` so this file can be applied twice without erroring; the drop
-- above removes the 0004 five-argument signature, not this one.
create or replace function create_household(
  p_name      text,
  p_address   text default null,
  p_timezone  text default 'America/Detroit',
  p_full_name text default null,
  p_initials  text default null,
  p_modules   text[] default null
)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  me       uuid := auth.uid();
  new_id   uuid;
  chore_id uuid;
  existing uuid;
  wanted   text[] := coalesce(p_modules, default_modules());
begin
  if me is null then
    raise exception 'not signed in';
  end if;

  select household_id into existing from profiles where id = me;
  if existing is not null then
    raise exception 'you are already in a household';
  end if;

  insert into households (name, address, timezone)
  values (trim(p_name), nullif(trim(coalesce(p_address, '')), ''), p_timezone)
  returning id into new_id;

  update profiles
     set household_id = new_id,
         is_admin     = true,
         full_name    = coalesce(nullif(trim(coalesce(p_full_name, '')), ''), full_name),
         initials     = coalesce(nullif(upper(trim(coalesce(p_initials, ''))), ''), initials)
   where id = me;

  insert into household_modules (household_id, module, enabled, updated_by)
  select new_id, d, d = any (wanted), me
  from unnest(default_modules()) d;

  -- Anything asked for that is not a default (a module shipped later) still
  -- gets recorded.
  insert into household_modules (household_id, module, enabled, updated_by)
  select new_id, w, true, me
  from unnest(wanted) w
  where not (w = any (default_modules()))
  on conflict do nothing;

  -- Starter chores only if this house actually does chores here.
  if 'chores' = any (wanted) then
    for chore_id in
      insert into chores (household_id, name, emoji, description, cadence,
                          days_of_week, interval_weeks, due_hour, queue_depth, sort_order)
      values
        (new_id, 'Floors', '🧹', 'Sweep and mop the common areas', 'scheduled', '{0,5}', 1, 20, 4, 1),
        (new_id, 'Microwave', '🍲', 'Wipe out the microwave', 'scheduled', '{6}', 2, 20, 4, 2),
        (new_id, 'Trash to curb', '🗑️', 'Bins out the night before pickup', 'scheduled', '{0}', 1, 19, 4, 3),
        (new_id, 'Dishes', '🍽️', 'Run and unload a load', 'on_demand', '{}', 1, 20, 4, 4),
        (new_id, 'Trash when full', '🚮', 'Swap the kitchen bag', 'on_demand', '{}', 1, 20, 4, 5)
      returning id
    loop
      insert into chore_rotation (chore_id, profile_id, position) values (chore_id, me, 0);
    end loop;

    for chore_id in select id from chores where household_id = new_id loop
      if (select cadence from chores where id = chore_id) = 'scheduled' then
        perform materialize_schedule(chore_id);
      else
        perform top_up_queue(chore_id);
      end if;
    end loop;
  end if;

  insert into activity_log (household_id, actor_id, verb, summary)
  values (new_id, me, 'created_household',
          (select full_name from profiles where id = me) || ' started the house');

  return new_id;
end;
$$;

-- Backfill: households that predate this table keep everything they had.
insert into household_modules (household_id, module, enabled)
select h.id, d, true
from households h, unnest(default_modules()) d
on conflict do nothing;


/**************************************************************************
 * 0006_devices.sql
 *************************************************************************/

-- The Home Assistant bridge had the same single-household assumption the kiosk
-- did: one shared token in an env var, resolved against "whichever household
-- exists". Both are really the same thing — a non-human device bound to one
-- house — so they share one registry and one token mechanism.

alter table kiosk_devices
  add column if not exists kind text not null default 'kiosk';

do $$
begin
  alter table kiosk_devices
    add constraint kiosk_devices_kind_check
    check (kind in ('kiosk', 'home_assistant'));
exception when duplicate_object then null;
end $$;

create or replace function create_device(p_name text, p_kind text default 'kiosk')
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  hh   uuid;
  code text;
begin
  if not is_household_admin() then raise exception 'only an admin can add a device'; end if;
  if p_kind not in ('kiosk', 'home_assistant') then
    raise exception 'unknown device kind %', p_kind;
  end if;

  select household_id into hh from profiles where id = auth.uid();
  if hh is null then raise exception 'you are not in a household'; end if;

  -- 24 bytes of CSPRNG, url-safe. Returned once; only the hash is kept.
  code := replace(replace(replace(encode(gen_random_bytes(24), 'base64'), '+', '-'), '/', '_'), '=', '');

  insert into kiosk_devices (household_id, name, kind, token_hash, created_by)
  values (hh, coalesce(nullif(trim(p_name), ''), 'Device'), p_kind,
          encode(digest(code, 'sha256'), 'hex'), auth.uid());

  return code;
end;
$$;

create or replace function resolve_device_token(p_token text, p_kind text default null)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare hh uuid;
begin
  update kiosk_devices
     set last_seen_at = now()
   where token_hash = encode(digest(p_token, 'sha256'), 'hex')
     and (p_kind is null or kind = p_kind)
  returning household_id into hh;

  return hh;
end;
$$;

-- Kept as thin wrappers so existing callers keep working.
create or replace function create_kiosk_device(p_name text)
returns text
language sql
security definer
set search_path = public
as $$ select create_device(p_name, 'kiosk'); $$;

create or replace function resolve_kiosk_token(p_token text)
returns uuid
language sql
security definer
set search_path = public
as $$ select resolve_device_token(p_token, 'kiosk'); $$;


/**************************************************************************
 * 0007_intro.sql
 *************************************************************************/

-- Tracks whether someone has seen the "how this works" walkthrough. On the
-- profile rather than localStorage so it follows them across devices — you
-- should not get the tour again just because you opened it on the iPad.

alter table profiles
  add column if not exists intro_seen_at timestamptz;

-- 0004 revoked blanket UPDATE on profiles and re-granted it column by column,
-- so a new user-writable column has to be added to that grant explicitly.
do $$
declare r text;
begin
  foreach r in array array['authenticated', 'domestic_app'] loop
    if exists (select 1 from pg_roles where rolname = r) then
      execute format('grant update (intro_seen_at) on profiles to %I', r);
    end if;
  end loop;
end $$;


/**************************************************************************
 * 0008_pgcrypto_schema.sql
 *************************************************************************/

-- pgcrypto does not live in `public` on Supabase.
--
-- Supabase pre-installs pgcrypto into the `extensions` schema, so 0001's
-- `create extension if not exists "pgcrypto"` is a no-op there and never moves
-- it into `public`. Stock Postgres has no such schema, so the same statement
-- installs it into `public` — which is why the device functions worked in the
-- test container and in local dev, and failed in production with
-- `function gen_random_bytes(integer) does not exist`.
--
-- Both device functions are `security definer` with `set search_path = public`,
-- which is what pins them to a schema that may not hold pgcrypto. Adding
-- `extensions` covers both layouts: Postgres silently ignores a schema in
-- search_path that does not exist, so this stays correct on stock Postgres.
--
-- Keep `extensions` on the search_path of any future security-definer function
-- that calls digest(), gen_random_bytes(), crypt(), or hmac().

-- Guarantee pgcrypto exists somewhere first. If it is already installed this
-- leaves it exactly where it is (in `public` on stock Postgres, `extensions` on
-- Supabase); if it is not installed at all, put it in `extensions`. Together
-- with the search_path below, all three layouts resolve.
do $$
begin
  if not exists (select 1 from pg_extension where extname = 'pgcrypto') then
    create schema if not exists extensions;
    create extension pgcrypto with schema extensions;
  end if;
end $$;

create or replace function create_device(p_name text, p_kind text default 'kiosk')
returns text
language plpgsql
security definer
set search_path = public, extensions
as $$
declare
  hh   uuid;
  code text;
begin
  if not is_household_admin() then raise exception 'only an admin can add a device'; end if;
  if p_kind not in ('kiosk', 'home_assistant') then
    raise exception 'unknown device kind %', p_kind;
  end if;

  select household_id into hh from profiles where id = auth.uid();
  if hh is null then raise exception 'you are not in a household'; end if;

  -- 24 bytes of CSPRNG, url-safe. Returned once; only the hash is kept.
  code := replace(replace(replace(encode(gen_random_bytes(24), 'base64'), '+', '-'), '/', '_'), '=', '');

  insert into kiosk_devices (household_id, name, kind, token_hash, created_by)
  values (hh, coalesce(nullif(trim(p_name), ''), 'Device'), p_kind,
          encode(digest(code, 'sha256'), 'hex'), auth.uid());

  return code;
end;
$$;

create or replace function resolve_device_token(p_token text, p_kind text default null)
returns uuid
language plpgsql
security definer
set search_path = public, extensions
as $$
declare hh uuid;
begin
  update kiosk_devices
     set last_seen_at = now()
   where token_hash = encode(digest(p_token, 'sha256'), 'hex')
     and (p_kind is null or kind = p_kind)
  returning household_id into hh;

  return hh;
end;
$$;


/**************************************************************************
 * 0009_chore_admin.sql
 *************************************************************************/

-- Chores were seed-only: create_household() inserts a starter set and nothing
-- since then has let an admin add, edit, or retire one. This gives admins the
-- same "add/remove" power over chores that already exists for people
-- (household_invites, remove_member) and devices (kiosk_devices).
--
-- Precedent: household_invites and kiosk_devices carry only a SELECT policy —
-- writes are impossible except through a SECURITY DEFINER function that checks
-- is_household_admin() internally. `chores`/`chore_rotation` currently allow
-- any member to write directly (`ch_all`/`rot_all`), but nothing in the app
-- ever does — every client reference is a `.select(...)`. Tightening both
-- tables to the same read-only-plus-RPC shape closes that gap and gives chore
-- management the same admin boundary as everything else in this tier.

/* ------------------------------------------------------------------ create */

create or replace function create_chore(
  p_name           text,
  p_cadence        chore_cadence,
  p_emoji          text default '🧹',
  p_description    text default null,
  p_days_of_week   smallint[] default '{}',
  p_interval_weeks smallint default 1,
  p_due_hour       smallint default 20,
  p_queue_depth    smallint default 4,
  p_lookahead_days smallint default 21,
  p_profile_ids    uuid[] default '{}'
)
returns chores
language plpgsql
security definer
set search_path = public
as $$
declare
  hh        uuid;
  next_sort smallint;
  new_chore chores%rowtype;
begin
  if not is_household_admin() then raise exception 'only an admin can add a chore'; end if;
  select household_id into hh from profiles where id = auth.uid();
  if hh is null then raise exception 'you are not in a household'; end if;
  if coalesce(trim(p_name), '') = '' then raise exception 'give it a name'; end if;

  select coalesce(max(sort_order), 0) + 1 into next_sort from chores where household_id = hh;

  insert into chores (
    household_id, name, emoji, description, cadence,
    days_of_week, interval_weeks, due_hour, queue_depth, lookahead_days, sort_order
  )
  values (
    hh, trim(p_name), coalesce(nullif(trim(p_emoji), ''), '🧹'),
    nullif(trim(coalesce(p_description, '')), ''), p_cadence,
    coalesce(p_days_of_week, '{}'), greatest(coalesce(p_interval_weeks, 1), 1),
    coalesce(p_due_hour, 20), greatest(coalesce(p_queue_depth, 4), 1),
    greatest(coalesce(p_lookahead_days, 21), 1), next_sort
  )
  returning * into new_chore;

  if p_profile_ids is not null and array_length(p_profile_ids, 1) is not null then
    insert into chore_rotation (chore_id, profile_id, position)
    select new_chore.id, t.pid, t.ord - 1
    from unnest(p_profile_ids) with ordinality as t(pid, ord)
    where exists (select 1 from profiles where id = t.pid and household_id = hh);
  end if;

  if new_chore.cadence = 'scheduled' then
    perform materialize_schedule(new_chore.id);
  else
    perform top_up_queue(new_chore.id);
  end if;

  insert into activity_log (household_id, actor_id, verb, summary, metadata)
  values (hh, auth.uid(), 'created_chore', new_chore.name || ' was added to the board',
          jsonb_build_object('chore_id', new_chore.id, 'emoji', new_chore.emoji));

  return new_chore;
end;
$$;

/* -------------------------------------------------------------------- edit */

-- Cadence-affecting fields only touch `pending` turns — done/skipped/missed
-- rows are history and are never rewritten, same rule as resync_pending_turns.
create or replace function update_chore(
  p_chore          uuid,
  p_name           text default null,
  p_emoji          text default null,
  p_description    text default null,
  p_cadence        chore_cadence default null,
  p_days_of_week   smallint[] default null,
  p_interval_weeks smallint default null,
  p_due_hour       smallint default null,
  p_queue_depth    smallint default null,
  p_lookahead_days smallint default null,
  p_sort_order     smallint default null
)
returns chores
language plpgsql
security definer
set search_path = public
as $$
declare
  hh              uuid;
  before          chores%rowtype;
  after           chores%rowtype;
  cadence_changed boolean;
begin
  if not is_household_admin() then raise exception 'only an admin can edit a chore'; end if;
  select household_id into hh from profiles where id = auth.uid();

  select * into before from chores where id = p_chore and household_id = hh;
  if not found then raise exception 'that chore is not in your household'; end if;

  update chores set
    name           = coalesce(nullif(trim(p_name), ''), name),
    emoji          = coalesce(nullif(trim(p_emoji), ''), emoji),
    description    = case when p_description is not null
                          then nullif(trim(p_description), '') else description end,
    cadence        = coalesce(p_cadence, cadence),
    days_of_week   = coalesce(p_days_of_week, days_of_week),
    interval_weeks = coalesce(p_interval_weeks, interval_weeks),
    due_hour       = coalesce(p_due_hour, due_hour),
    queue_depth    = coalesce(p_queue_depth, queue_depth),
    lookahead_days = coalesce(p_lookahead_days, lookahead_days),
    sort_order     = coalesce(p_sort_order, sort_order)
  where id = p_chore
  returning * into after;

  cadence_changed :=
    after.cadence        is distinct from before.cadence or
    after.days_of_week   is distinct from before.days_of_week or
    after.interval_weeks is distinct from before.interval_weeks or
    after.due_hour       is distinct from before.due_hour or
    after.queue_depth    is distinct from before.queue_depth;

  if cadence_changed then
    delete from chore_turns where chore_id = p_chore and status = 'pending';
    if after.cadence = 'scheduled' then
      perform materialize_schedule(p_chore);
    else
      perform top_up_queue(p_chore);
    end if;
  end if;

  return after;
end;
$$;

/* ------------------------------------------------------------ active state */

-- One toggle covers both directions: deactivating hides a chore from the
-- board without touching its history (chore_turns still references it);
-- reactivating just needs the queue/schedule filled back in.
create or replace function set_chore_active(p_chore uuid, p_active boolean)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  hh     uuid;
  chore  chores%rowtype;
begin
  if not is_household_admin() then raise exception 'only an admin can do that'; end if;
  select household_id into hh from profiles where id = auth.uid();

  update chores set is_active = p_active
   where id = p_chore and household_id = hh
  returning * into chore;
  if not found then raise exception 'that chore is not in your household'; end if;

  if p_active then
    if chore.cadence = 'scheduled' then
      perform materialize_schedule(p_chore);
    else
      perform top_up_queue(p_chore);
    end if;
  end if;
end;
$$;

/* --------------------------------------------------------------- rotation */

-- Replaces a chore's entire roster in one call — add, remove, and reorder are
-- all just "submit the new ordered list", so the UI needs one primitive
-- instead of three. Positions come straight from the submitted array's order
-- (via `with ordinality`), which is simpler than deriving them from existing
-- row order the way remove_from_rotations does for a single deletion.
create or replace function set_chore_rotation(p_chore uuid, p_profile_ids uuid[])
returns void
language plpgsql
security definer
set search_path = public
as $$
declare hh uuid;
begin
  if not is_household_admin() then raise exception 'only an admin can edit a chore roster'; end if;
  select household_id into hh from profiles where id = auth.uid();
  if not exists (select 1 from chores where id = p_chore and household_id = hh) then
    raise exception 'that chore is not in your household';
  end if;
  if exists (
    select 1 from unnest(coalesce(p_profile_ids, '{}')) pid
    where not exists (select 1 from profiles where id = pid and household_id = hh)
  ) then
    raise exception 'everyone on the rotation must be in your household';
  end if;

  delete from chore_rotation where chore_id = p_chore;

  insert into chore_rotation (chore_id, profile_id, position)
  select p_chore, t.pid, t.ord - 1
  from unnest(coalesce(p_profile_ids, '{}')) with ordinality as t(pid, ord);

  perform resync_pending_turns(p_chore);
end;
$$;

/* --------------------------------------------------------------------- RLS */

drop policy if exists ch_all on chores;
drop policy if exists ch_read on chores;
create policy ch_read on chores for select
  using (is_household_member(household_id));

drop policy if exists rot_all on chore_rotation;
drop policy if exists rot_read on chore_rotation;
create policy rot_read on chore_rotation for select
  using (exists (select 1 from chores c where c.id = chore_id and is_household_member(c.household_id)));


/**************************************************************************
 * 0010_recurring_expenses.sql
 *************************************************************************/

-- Rent, subscriptions, and other bills that repeat on a schedule and should
-- just show up in the ledger without anyone remembering to add them.
--
-- Splits are computed once, in TypeScript, using the same splitEqual /
-- splitByWeight helpers addExpense already uses for one-off expenses — the
-- resulting owed_cents (and weight, kept for re-editing exactly like
-- expense_splits.weight) are stored per participant. Posting a due occurrence
-- is then a pure copy, not a re-derivation, so there is no separate plpgsql
-- port of the splitting math to keep in sync with money.ts.
--
-- Management (create/edit/pause) follows the household_invites /
-- kiosk_devices / chores shape: the tables carry only a SELECT policy, and
-- every write goes through a SECURITY DEFINER function that checks
-- is_household_admin(). A recurring expense is standing configuration that
-- re-fires forever with no per-occurrence confirmation, unlike a one-off
-- expense that is reviewed once at creation — that risk profile matches the
-- admin-gated tier, not the member-writable tier expenses/settlements sit in.
--
-- Posting itself (post_due_recurring_expenses) is different in kind: it runs
-- with no user session, invoked by cron via the admin client exactly like
-- materialize_schedule/top_up_queue, must be all-or-nothing per occurrence,
-- and must be safe to call twice a day — the "atomic, cron-invoked" category
-- CLAUDE.md calls out for plpgsql, same as its chores counterparts.

create table if not exists recurring_expenses (
  id               uuid primary key default gen_random_uuid(),
  household_id     uuid not null references households(id) on delete cascade,
  description      text not null,
  amount_cents     bigint not null check (amount_cents > 0),
  currency         char(3) not null default 'USD',
  category         text not null default 'general',
  paid_by          uuid not null references profiles(id) on delete restrict,
  split_kind       split_kind not null default 'equal',

  -- Two cadence families, each with a multiplier: weekly x1 = weekly, x2 =
  -- biweekly; monthly x1 = monthly, x3 = quarterly. day_of_month is clamped to
  -- the last day of short months when posting.
  cadence          text not null check (cadence in ('weekly', 'monthly')),
  interval_weeks   smallint not null default 1 check (interval_weeks > 0),
  interval_months  smallint not null default 1 check (interval_months > 0),
  day_of_month     smallint check (day_of_month between 1 and 31),
  check (cadence = 'weekly' or day_of_month is not null),

  next_run_on      date not null default current_date,
  is_active        boolean not null default true,
  created_by       uuid references profiles(id) on delete set null,
  created_at       timestamptz not null default now()
);

create index if not exists recurring_expenses_household_id_is_active_idx
  on recurring_expenses (household_id, is_active);

create table if not exists recurring_expense_participants (
  recurring_expense_id uuid   not null references recurring_expenses(id) on delete cascade,
  profile_id            uuid   not null references profiles(id) on delete cascade,
  owed_cents            bigint not null check (owed_cents >= 0),
  weight                numeric(10,4),
  primary key (recurring_expense_id, profile_id)
);

/* --------------------------------------------------------------- management */

create or replace function create_recurring_expense(
  p_description     text,
  p_amount_cents    bigint,
  p_paid_by         uuid,
  p_split_kind      split_kind,
  p_cadence         text,
  p_participants    jsonb,  -- [{"profile_id": uuid, "owed_cents": int, "weight": numeric|null}, ...]
  p_category        text default 'general',
  p_interval_weeks  smallint default 1,
  p_interval_months smallint default 1,
  p_day_of_month    smallint default null,
  p_start_on        date default current_date
)
returns recurring_expenses
language plpgsql
security definer
set search_path = public
as $$
declare
  hh      uuid;
  total   bigint;
  row_out recurring_expenses%rowtype;
begin
  if not is_household_admin() then raise exception 'only an admin can add a recurring expense'; end if;
  select household_id into hh from profiles where id = auth.uid();
  if hh is null then raise exception 'you are not in a household'; end if;

  if p_cadence not in ('weekly', 'monthly') then raise exception 'unknown cadence %', p_cadence; end if;
  if p_cadence = 'monthly' and p_day_of_month is null then
    raise exception 'a monthly recurring expense needs a day of the month';
  end if;
  if not exists (select 1 from profiles where id = p_paid_by and household_id = hh) then
    raise exception 'the payer must be in your household';
  end if;
  if jsonb_array_length(coalesce(p_participants, '[]'::jsonb)) = 0 then
    raise exception 'split it with someone';
  end if;
  if exists (
    select 1 from jsonb_to_recordset(p_participants) as x(profile_id uuid, owed_cents bigint, weight numeric)
    where not exists (select 1 from profiles where id = x.profile_id and household_id = hh)
  ) then
    raise exception 'everyone in the split must be in your household';
  end if;

  select sum(x.owed_cents) into total
  from jsonb_to_recordset(p_participants) as x(profile_id uuid, owed_cents bigint, weight numeric);
  if total is distinct from p_amount_cents then
    raise exception 'splits must add up to the total';
  end if;

  insert into recurring_expenses (
    household_id, description, amount_cents, category, paid_by, split_kind,
    cadence, interval_weeks, interval_months, day_of_month, next_run_on, created_by
  )
  values (
    hh, trim(p_description), p_amount_cents, coalesce(p_category, 'general'), p_paid_by, p_split_kind,
    p_cadence, greatest(coalesce(p_interval_weeks, 1), 1), greatest(coalesce(p_interval_months, 1), 1),
    p_day_of_month, coalesce(p_start_on, current_date), auth.uid()
  )
  returning * into row_out;

  insert into recurring_expense_participants (recurring_expense_id, profile_id, owed_cents, weight)
  select row_out.id, x.profile_id, x.owed_cents, x.weight
  from jsonb_to_recordset(p_participants) as x(profile_id uuid, owed_cents bigint, weight numeric);

  insert into activity_log (household_id, actor_id, verb, summary, metadata)
  values (hh, auth.uid(), 'created_recurring_expense',
          row_out.description || ' will repeat ' || row_out.cadence,
          jsonb_build_object('recurring_expense_id', row_out.id));

  return row_out;
end;
$$;

create or replace function update_recurring_expense(
  p_id              uuid,
  p_description     text default null,
  p_amount_cents    bigint default null,
  p_paid_by         uuid default null,
  p_split_kind      split_kind default null,
  p_category        text default null,
  p_cadence         text default null,
  p_interval_weeks  smallint default null,
  p_interval_months smallint default null,
  p_day_of_month    smallint default null,
  p_participants    jsonb default null
)
returns recurring_expenses
language plpgsql
security definer
set search_path = public
as $$
declare
  hh         uuid;
  before     recurring_expenses%rowtype;
  row_out    recurring_expenses%rowtype;
  total      bigint;
  new_amount bigint;
begin
  if not is_household_admin() then raise exception 'only an admin can edit a recurring expense'; end if;
  select household_id into hh from profiles where id = auth.uid();

  select * into before from recurring_expenses where id = p_id and household_id = hh;
  if not found then raise exception 'that recurring expense is not in your household'; end if;

  if p_cadence is not null and p_cadence not in ('weekly', 'monthly') then
    raise exception 'unknown cadence %', p_cadence;
  end if;
  if coalesce(p_cadence, before.cadence) = 'monthly'
     and coalesce(p_day_of_month, before.day_of_month) is null then
    raise exception 'a monthly recurring expense needs a day of the month';
  end if;
  if p_paid_by is not null and not exists (select 1 from profiles where id = p_paid_by and household_id = hh) then
    raise exception 'the payer must be in your household';
  end if;

  new_amount := coalesce(p_amount_cents, before.amount_cents);

  if p_participants is not null then
    if exists (
      select 1 from jsonb_to_recordset(p_participants) as x(profile_id uuid, owed_cents bigint, weight numeric)
      where not exists (select 1 from profiles where id = x.profile_id and household_id = hh)
    ) then
      raise exception 'everyone in the split must be in your household';
    end if;
    select sum(x.owed_cents) into total
    from jsonb_to_recordset(p_participants) as x(profile_id uuid, owed_cents bigint, weight numeric);
    if total is distinct from new_amount then
      raise exception 'splits must add up to the total';
    end if;
  end if;

  update recurring_expenses set
    description     = coalesce(nullif(trim(p_description), ''), description),
    amount_cents    = new_amount,
    paid_by         = coalesce(p_paid_by, paid_by),
    split_kind      = coalesce(p_split_kind, split_kind),
    category        = coalesce(p_category, category),
    cadence         = coalesce(p_cadence, cadence),
    interval_weeks  = coalesce(p_interval_weeks, interval_weeks),
    interval_months = coalesce(p_interval_months, interval_months),
    day_of_month    = coalesce(p_day_of_month, day_of_month)
  where id = p_id
  returning * into row_out;

  if p_participants is not null then
    delete from recurring_expense_participants where recurring_expense_id = p_id;
    insert into recurring_expense_participants (recurring_expense_id, profile_id, owed_cents, weight)
    select p_id, x.profile_id, x.owed_cents, x.weight
    from jsonb_to_recordset(p_participants) as x(profile_id uuid, owed_cents bigint, weight numeric);
  end if;

  return row_out;
end;
$$;

create or replace function set_recurring_expense_active(p_id uuid, p_active boolean)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare hh uuid;
begin
  if not is_household_admin() then raise exception 'only an admin can do that'; end if;
  select household_id into hh from profiles where id = auth.uid();
  update recurring_expenses set is_active = p_active where id = p_id and household_id = hh;
  if not found then raise exception 'that recurring expense is not in your household'; end if;
end;
$$;

/* ------------------------------------------------------------------ posting */

-- Catches up on any missed cycles (server downtime, a skipped cron run) one
-- occurrence at a time, capped so a bug can never spin this into a runaway
-- loop. Idempotent across the twice-daily cron: next_run_on is advanced past
-- `today` inside the same statement that inserts the expense, so a second run
-- later that day sees next_run_on > today and does nothing for that row.
create or replace function post_due_recurring_expenses()
returns setof expenses
language plpgsql
security definer
set search_path = public
as $$
declare
  r           recurring_expenses%rowtype;
  tz          text;
  today       date;
  new_expense expenses%rowtype;
  next_date   date;
  guard       int;
begin
  for r in select * from recurring_expenses where is_active for update loop
    select timezone into tz from households where id = r.household_id;
    today := (now() at time zone coalesce(tz, 'America/Detroit'))::date;
    guard := 0;

    while r.next_run_on <= today and guard < 24 loop
      insert into expenses (
        household_id, description, amount_cents, currency, category,
        paid_by, spent_on, split_kind, created_by, note
      )
      values (
        r.household_id, r.description, r.amount_cents, r.currency, r.category,
        r.paid_by, r.next_run_on, r.split_kind, r.created_by, 'Recurring'
      )
      returning * into new_expense;

      insert into expense_splits (expense_id, profile_id, owed_cents, weight)
      select new_expense.id, p.profile_id, p.owed_cents, p.weight
      from recurring_expense_participants p
      where p.recurring_expense_id = r.id;

      insert into activity_log (household_id, actor_id, verb, summary, metadata)
      values (r.household_id, r.created_by, 'added_expense',
              r.description || ' — ' || to_char(r.amount_cents / 100.0, 'FM$999999990.00') || ' (recurring)',
              jsonb_build_object('expense_id', new_expense.id, 'recurring_expense_id', r.id));

      if r.cadence = 'weekly' then
        next_date := r.next_run_on + (r.interval_weeks * 7);
      else
        next_date := (date_trunc('month', r.next_run_on) + (r.interval_months || ' months')::interval)::date;
        next_date := next_date + (
          least(r.day_of_month, extract(day from (next_date + interval '1 month - 1 day'))::int) - 1
        );
      end if;
      r.next_run_on := next_date;
      update recurring_expenses set next_run_on = next_date where id = r.id;

      return next new_expense;
      guard := guard + 1;
    end loop;
  end loop;
  return;
end;
$$;

/* --------------------------------------------------------------------- RLS */

alter table recurring_expenses enable row level security;
alter table recurring_expense_participants enable row level security;

drop policy if exists rec_exp_read on recurring_expenses;
create policy rec_exp_read on recurring_expenses for select
  using (is_household_member(household_id));

drop policy if exists rec_part_read on recurring_expense_participants;
create policy rec_part_read on recurring_expense_participants for select
  using (exists (
    select 1 from recurring_expenses r
    where r.id = recurring_expense_id and is_household_member(r.household_id)
  ));


/**************************************************************************
 * 0011_ai_config.sql
 *************************************************************************/

-- Receipt scanning was wired to a single global ANTHROPIC_API_KEY env var,
-- picked up implicitly by `new Anthropic()`. That does not fit "any household
-- can deploy and run themselves" — each deployed house should be able to pick
-- its own provider (Anthropic or Gemini) and supply its own key.
--
-- An API key is a bearer credential, not a UI preference, so it does not live
-- in household_modules.settings — that column is readable by any member via
-- the existing mod_read policy. household_ai_config instead carries RLS with
-- *zero* policies: RLS enabled and no policy of any kind denies every row to
-- every client role, including this household's own admin browsing the app —
-- only a SECURITY DEFINER function (or the service role, which bypasses RLS
-- entirely) can read or write it. The key is additionally encrypted with
-- pgcrypto, already installed for this project (0008) — RLS stops the app's
-- normal query paths, encryption is the second layer that protects a Postgres
-- dump, backup, or read replica from leaking a raw vendor API key.
--
-- The encryption secret is passed as an argument on every call, not stored as
-- a Postgres GUC, so it stays inside this app's existing "secrets live in
-- .env" convention rather than adding a second secret-management surface.

create table if not exists household_ai_config (
  household_id  uuid primary key references households(id) on delete cascade,
  provider      text not null check (provider in ('anthropic', 'gemini')),
  api_key_enc   bytea not null,
  updated_at    timestamptz not null default now(),
  updated_by    uuid references profiles(id) on delete set null
);

alter table household_ai_config enable row level security;
-- Deliberately no policy at all — see comment above.

create or replace function set_ai_config(p_provider text, p_api_key text, p_secret text)
returns void
language plpgsql
security definer
set search_path = public, extensions
as $$
declare hh uuid;
begin
  if not is_household_admin() then raise exception 'only an admin can change this'; end if;
  if p_provider not in ('anthropic', 'gemini') then raise exception 'unknown provider %', p_provider; end if;
  if coalesce(trim(p_api_key), '') = '' then raise exception 'enter an API key'; end if;

  select household_id into hh from profiles where id = auth.uid();
  if hh is null then raise exception 'you are not in a household'; end if;

  insert into household_ai_config (household_id, provider, api_key_enc, updated_by)
  values (hh, p_provider, pgp_sym_encrypt(p_api_key, p_secret), auth.uid())
  on conflict (household_id) do update
    set provider    = excluded.provider,
        api_key_enc = excluded.api_key_enc,
        updated_at  = now(),
        updated_by  = auth.uid();
end;
$$;

create or replace function clear_ai_config()
returns void
language plpgsql
security definer
set search_path = public
as $$
declare hh uuid;
begin
  if not is_household_admin() then raise exception 'only an admin can change this'; end if;
  select household_id into hh from profiles where id = auth.uid();
  delete from household_ai_config where household_id = hh;
end;
$$;

-- Enough for the admin settings screen to render "Anthropic — configured";
-- never returns the key, so this is safe to call from anywhere a signed-in
-- member can reach, not just admins.
create or replace function get_ai_config_summary()
returns table(provider text, updated_at timestamptz)
language sql
stable
security definer
set search_path = public
as $$
  select c.provider, c.updated_at
  from household_ai_config c
  join profiles p on p.household_id = c.household_id
  where p.id = auth.uid();
$$;

-- Used only from server-side code (the receipt route), never a client
-- component — the decrypted key must never appear in a response body.
create or replace function get_ai_credentials(p_secret text)
returns table(provider text, api_key text)
language plpgsql
stable
security definer
set search_path = public, extensions
as $$
declare hh uuid;
begin
  select household_id into hh from profiles where id = auth.uid();
  if hh is null then return; end if;
  return query
    select c.provider, pgp_sym_decrypt(c.api_key_enc, p_secret)
    from household_ai_config c
    where c.household_id = hh;
end;
$$;


/**************************************************************************
 * 0012_kiosk_interactivity.sql
 *************************************************************************/

-- Kiosk interactivity: tap-to-act on the wall display, an admin-gated toggle
-- letting any member complete anyone's chore, a household weather location,
-- and short-lived notes that show up on the kiosk.
--
-- The kiosk has no auth.uid() — it authenticates by device token, resolved to
-- a household id in application code (src/lib/kiosk.ts). Every kiosk_* RPC
-- below takes that household id plus an explicit "acting as" profile id
-- instead of reading auth.uid(), and validates against the household rather
-- than a session. Because these skip the auth.uid()-based ownership checks
-- the non-kiosk RPCs use, they are locked to service_role only — callable
-- exclusively from server actions that already resolved and validated the
-- kiosk's household, never directly by a signed-in user (who could otherwise
-- pass any housemate's profile id and bypass allow_member_cross_complete
-- entirely).

/* ------------------------------------------------------------- households */

alter table households
  add column if not exists allow_member_cross_complete boolean not null default false,
  add column if not exists location_label text,
  add column if not exists latitude double precision,
  add column if not exists longitude double precision;

create or replace function set_cross_complete(p_enabled boolean)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare hh uuid;
begin
  if not is_household_admin() then
    raise exception 'only an admin can change who can complete whose chores';
  end if;
  select household_id into hh from profiles where id = auth.uid();
  if hh is null then raise exception 'you are not in a household'; end if;

  update households set allow_member_cross_complete = p_enabled where id = hh;
end;
$$;

create or replace function set_household_location(
  p_label text,
  p_lat   double precision,
  p_lon   double precision
)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare hh uuid;
begin
  if not is_household_admin() then
    raise exception 'only an admin can set the household location';
  end if;
  select household_id into hh from profiles where id = auth.uid();
  if hh is null then raise exception 'you are not in a household'; end if;

  update households
     set location_label = nullif(trim(coalesce(p_label, '')), ''),
         latitude        = p_lat,
         longitude       = p_lon
   where id = hh;
end;
$$;

/* ---------------------------------------------------- cross-user completion */

-- Same body as before, plus one gate: completing someone else's turn now
-- requires the household to have turned that on. `me`/`completed_by` are
-- unchanged — still whoever actually tapped the button, never the assignee.
create or replace function complete_turn(p_turn uuid, p_note text default null)
returns chore_turns
language plpgsql
security definer
set search_path = public
as $$
declare
  t           chore_turns%rowtype;
  c           chores%rowtype;
  me          uuid := auth.uid();
  allow_cross boolean;
begin
  select * into t from chore_turns where id = p_turn for update;
  if not found then
    raise exception 'turn not found';
  end if;
  if not is_household_member(t.household_id) then
    raise exception 'not your household';
  end if;
  if t.status = 'done' then
    return t;
  end if;

  if me is distinct from t.assignee_id then
    select allow_member_cross_complete into allow_cross
    from households where id = t.household_id;
    if not coalesce(allow_cross, false) then
      raise exception 'only the assigned member can complete this — an admin can let anyone complete anyone''s chores in Settings';
    end if;
  end if;

  update chore_turns
     set status = 'done', completed_at = now(), completed_by = coalesce(me, t.assignee_id), note = p_note
   where id = p_turn
  returning * into t;

  select * into c from chores where id = t.chore_id;

  if c.cadence = 'on_demand' then
    perform top_up_queue(t.chore_id);
  else
    perform materialize_schedule(t.chore_id);
  end if;

  insert into activity_log (household_id, actor_id, verb, summary, metadata)
  select t.household_id, coalesce(me, t.assignee_id), 'completed_chore',
         p.full_name || ' did ' || c.name,
         jsonb_build_object('chore_id', c.id, 'turn_id', t.id, 'emoji', c.emoji)
  from profiles p where p.id = coalesce(me, t.assignee_id);

  return t;
end;
$$;

/* --------------------------------------------------------------- kiosk RPCs */

create or replace function kiosk_complete_turn(
  p_household uuid,
  p_turn      uuid,
  p_profile   uuid,
  p_note      text default null
)
returns chore_turns
language plpgsql
security definer
set search_path = public
as $$
declare
  t chore_turns%rowtype;
  c chores%rowtype;
begin
  if not exists (select 1 from profiles where id = p_profile and household_id = p_household) then
    raise exception 'not a member of this household';
  end if;

  select * into t from chore_turns where id = p_turn and household_id = p_household for update;
  if not found then raise exception 'turn not found'; end if;
  if t.status = 'done' then return t; end if;

  update chore_turns
     set status = 'done', completed_at = now(), completed_by = p_profile, note = p_note
   where id = p_turn
  returning * into t;

  select * into c from chores where id = t.chore_id;

  if c.cadence = 'on_demand' then
    perform top_up_queue(t.chore_id);
  else
    perform materialize_schedule(t.chore_id);
  end if;

  insert into activity_log (household_id, actor_id, verb, summary, metadata)
  select t.household_id, p_profile, 'completed_chore',
         p.full_name || ' did ' || c.name,
         jsonb_build_object('chore_id', c.id, 'turn_id', t.id, 'emoji', c.emoji)
  from profiles p where p.id = p_profile;

  return t;
end;
$$;

create or replace function kiosk_flag_chore(
  p_household uuid,
  p_chore     uuid,
  p_profile   uuid
)
returns chore_turns
language plpgsql
security definer
set search_path = public
as $$
declare
  t chore_turns%rowtype;
  c chores%rowtype;
begin
  if not exists (select 1 from profiles where id = p_profile and household_id = p_household) then
    raise exception 'not a member of this household';
  end if;

  select * into c from chores where id = p_chore and household_id = p_household;
  if not found then raise exception 'chore not found'; end if;

  perform top_up_queue(p_chore);

  select * into t from chore_turns
   where chore_id = p_chore and status = 'pending'
   order by turn_number limit 1;

  update chore_turns set due_at = now() where id = t.id and due_at is null;

  insert into activity_log (household_id, actor_id, verb, summary, metadata)
  select c.household_id, p_profile, 'flagged_chore',
         c.name || ' needs doing',
         jsonb_build_object('chore_id', c.id, 'turn_id', t.id, 'emoji', c.emoji);

  return t;
end;
$$;

-- Kiosk treats swap approval as an admin action rather than routing it to
-- the specific person the swap was addressed to — the wall display's "acting
-- as" model is coarser than the app's per-recipient swap flow, so it uses the
-- same admin gate as kiosk_set_chore_active instead of checking requested_to.
create or replace function kiosk_respond_swap(
  p_household uuid,
  p_swap      uuid,
  p_profile   uuid,
  p_accept    boolean
)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  s chore_swaps%rowtype;
begin
  if not exists (
    select 1 from profiles
    where id = p_profile and household_id = p_household and is_admin
  ) then
    raise exception 'only an admin can do that';
  end if;

  select s.* into s
  from chore_swaps s
  join chore_turns t on t.id = s.turn_id
  where s.id = p_swap and t.household_id = p_household
  for update of s;
  if not found or s.status <> 'pending' then
    raise exception 'swap not open';
  end if;

  if p_accept then
    update chore_turns set assignee_id = s.requested_to where id = s.turn_id;
    update chore_swaps set status = 'accepted', resolved_at = now() where id = p_swap;
  else
    update chore_swaps set status = 'declined', resolved_at = now() where id = p_swap;
  end if;
end;
$$;

create or replace function kiosk_set_chore_active(
  p_household uuid,
  p_chore     uuid,
  p_profile   uuid,
  p_active    boolean
)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare chore chores%rowtype;
begin
  if not exists (
    select 1 from profiles
    where id = p_profile and household_id = p_household and is_admin
  ) then
    raise exception 'only an admin can do that';
  end if;

  update chores set is_active = p_active
   where id = p_chore and household_id = p_household
  returning * into chore;
  if not found then raise exception 'that chore is not in this household'; end if;

  if p_active then
    if chore.cadence = 'scheduled' then
      perform materialize_schedule(p_chore);
    else
      perform top_up_queue(p_chore);
    end if;
  end if;
end;
$$;

-- Lock the kiosk_* functions to service_role: revoke the default PUBLIC
-- execute grant every function gets, plus the per-role default privilege the
-- app role picks up on creation (see supabase/tests/run.sh), then grant back
-- only to service_role — the role createAdminClient() authenticates as.
do $$
declare r text;
begin
  foreach r in array array['authenticated', 'domestic_app'] loop
    if exists (select 1 from pg_roles where rolname = r) then
      execute format('revoke execute on function kiosk_complete_turn(uuid, uuid, uuid, text) from %I', r);
      execute format('revoke execute on function kiosk_flag_chore(uuid, uuid, uuid) from %I', r);
      execute format('revoke execute on function kiosk_respond_swap(uuid, uuid, uuid, boolean) from %I', r);
      execute format('revoke execute on function kiosk_set_chore_active(uuid, uuid, uuid, boolean) from %I', r);
    end if;
  end loop;

  if exists (select 1 from pg_roles where rolname = 'service_role') then
    grant execute on function kiosk_complete_turn(uuid, uuid, uuid, text) to service_role;
    grant execute on function kiosk_flag_chore(uuid, uuid, uuid) to service_role;
    grant execute on function kiosk_respond_swap(uuid, uuid, uuid, boolean) to service_role;
    grant execute on function kiosk_set_chore_active(uuid, uuid, uuid, boolean) to service_role;
  end if;
end $$;

revoke execute on function kiosk_complete_turn(uuid, uuid, uuid, text) from public;
revoke execute on function kiosk_flag_chore(uuid, uuid, uuid) from public;
revoke execute on function kiosk_respond_swap(uuid, uuid, uuid, boolean) from public;
revoke execute on function kiosk_set_chore_active(uuid, uuid, uuid, boolean) from public;

/* ------------------------------------------------------------- kiosk notes */

create table if not exists kiosk_messages (
  id           uuid primary key default gen_random_uuid(),
  household_id uuid not null references households(id) on delete cascade,
  author_id    uuid references profiles(id) on delete set null,
  body         text not null check (char_length(trim(body)) > 0 and char_length(body) <= 280),
  created_at   timestamptz not null default now(),
  expires_at   timestamptz not null default now() + interval '48 hours'
);

create index if not exists kiosk_messages_household_id_expires_at_idx
  on kiosk_messages (household_id, expires_at);

alter table kiosk_messages enable row level security;

drop policy if exists kiosk_messages_all on kiosk_messages;
create policy kiosk_messages_all on kiosk_messages for all
  using (is_household_member(household_id))
  with check (is_household_member(household_id) and author_id = auth.uid());


/**************************************************************************
 * 0013_split_adjustment.sql
 *************************************************************************/

-- Two new split_kind values, added on their own so nothing in this same
-- migration file can use them yet — Postgres will not let a new enum value
-- be referenced in the same transaction that adds it (each file here runs as
-- one transaction), so 0014 is where 'adjustment' and 'itemized' start being
-- used.
--
-- 'adjustment': start from an equal split, then nudge each person's share up
-- or down by a hand-entered amount — the split-method picker's fifth option,
-- alongside equal/exact/shares/percent.
--
-- 'itemized': expenses.split_kind only, meaning "derive the split from
-- expense_items/expense_item_splits" (see 0014). Never valid on
-- expense_items.split_kind itself, which sticks to the four picker kinds
-- plus 'adjustment' — the enum doesn't enforce that distinction, discipline
-- in the app layer does, same trade-off recurring_expenses already makes by
-- reusing this one shared type instead of a second narrower enum.
alter type split_kind add value if not exists 'adjustment';
alter type split_kind add value if not exists 'itemized';


/**************************************************************************
 * 0014_expense_items.sql
 *************************************************************************/

-- Line-item breakdown for a scanned (or manually itemized) receipt: each
-- item/tax/tip/discount row on the receipt gets its own assignees and its
-- own split method, instead of one split_kind for the whole expense.
--
-- expenses.split_kind = 'itemized' means "read expense_splits as an
-- aggregate of expense_item_splits, not as a directly-entered split" — the
-- expense_splits row shape and its consumers (v_balances, settlements,
-- the ledger UI) are untouched, so nothing downstream needs to know
-- itemization exists.
create table if not exists expense_items (
  id            uuid primary key default gen_random_uuid(),
  expense_id    uuid not null references expenses(id) on delete cascade,
  name          text not null,
  amount_cents  bigint not null,  -- negative allowed: a discount/fee row nets against the total
  kind          text not null default 'item'
                  check (kind in ('item', 'tax', 'tip', 'discount', 'fee')),
  split_kind    split_kind not null default 'equal',  -- never 'itemized' — see create_itemized_expense
  position      smallint not null default 0,
  created_at    timestamptz not null default now()
);

create index if not exists expense_items_expense_id_position_idx on expense_items (expense_id, position);

-- Mirrors expense_splits, but no owed_cents >= 0 check: a discount item's
-- amount_cents is negative, and so are the shares of it each assignee gets.
-- What must never go negative is a person's *aggregate* across all items —
-- enforced in create_itemized_expense when it rolls these up into
-- expense_splits, which keeps its owed_cents >= 0 check.
create table if not exists expense_item_splits (
  expense_item_id  uuid   not null references expense_items(id) on delete cascade,
  profile_id       uuid   not null references profiles(id) on delete cascade,
  owed_cents       bigint not null,
  weight           numeric(10,4),
  primary key (expense_item_id, profile_id)
);

create index if not exists expense_item_splits_profile_id_idx on expense_item_splits (profile_id);

-- RLS: same shape as expenses/expense_splits (0002_logic.sql) — read/write
-- gated by household membership via the parent expense, checked through a
-- join since these tables carry no household_id column of their own.
alter table expense_items enable row level security;
alter table expense_item_splits enable row level security;

drop policy if exists items_all on expense_items;
create policy items_all on expense_items
  using (exists (
    select 1 from expenses e
    where e.id = expense_items.expense_id and is_household_member(e.household_id)
  ))
  with check (exists (
    select 1 from expenses e
    where e.id = expense_items.expense_id and is_household_member(e.household_id)
  ));

drop policy if exists item_splits_all on expense_item_splits;
create policy item_splits_all on expense_item_splits
  using (exists (
    select 1 from expense_items i
    join expenses e on e.id = i.expense_id
    where i.id = expense_item_splits.expense_item_id and is_household_member(e.household_id)
  ))
  with check (exists (
    select 1 from expense_items i
    join expenses e on e.id = i.expense_id
    where i.id = expense_item_splits.expense_item_id and is_household_member(e.household_id)
  ));

/* --------------------------------------------------------------- creation */

-- Atomic: an expense, its line items, each item's per-person splits, and the
-- resulting expense_splits aggregate all land together or not at all — a
-- receipt with items assigned to no one, or a half-written aggregate, would
-- silently skew v_balances the same way a bad addExpense() insert would.
--
-- p_items shape:
--   [{ "name": "...", "amount_cents": bigint, "kind": "item"|"tax"|"tip"|"discount"|"fee",
--      "split_kind": split_kind (not 'itemized'),
--      "splits": [{ "profile_id": uuid, "owed_cents": bigint, "weight": numeric|null }, ...] }, ...]
create or replace function create_itemized_expense(
  p_description  text,
  p_paid_by      uuid,
  p_spent_on     date,
  p_items        jsonb,
  p_category     text default 'general',
  p_receipt_url  text default null,
  p_note         text default null
)
returns expenses
language plpgsql
security definer
set search_path = public
as $$
declare
  hh        uuid;
  row_out   expenses%rowtype;
  item      jsonb;
  item_id   uuid;
  item_total bigint;
  splits_total bigint;
  total     bigint;
  neg_person uuid;
begin
  select household_id into hh from profiles where id = auth.uid();
  if hh is null then raise exception 'you are not in a household'; end if;

  if not exists (select 1 from profiles where id = p_paid_by and household_id = hh) then
    raise exception 'the payer must be in your household';
  end if;
  if jsonb_typeof(p_items) is distinct from 'array' or jsonb_array_length(p_items) = 0 then
    raise exception 'a receipt needs at least one item';
  end if;
  if exists (
    select 1
    from jsonb_array_elements(p_items) as it,
         jsonb_to_recordset(it -> 'splits') as s(profile_id uuid, owed_cents bigint, weight numeric)
    where not exists (select 1 from profiles where id = s.profile_id and household_id = hh)
  ) then
    raise exception 'everyone assigned to an item must be in your household';
  end if;

  select sum((it ->> 'amount_cents')::bigint) into total
  from jsonb_array_elements(p_items) as it;

  insert into expenses (
    household_id, description, amount_cents, category, paid_by, spent_on,
    split_kind, receipt_url, note, created_by
  )
  values (
    hh, trim(p_description), total, coalesce(p_category, 'general'), p_paid_by, p_spent_on,
    'itemized', p_receipt_url, p_note, auth.uid()
  )
  returning * into row_out;

  for item in select * from jsonb_array_elements(p_items)
  loop
    item_total := (item ->> 'amount_cents')::bigint;

    select coalesce(sum((s ->> 'owed_cents')::bigint), 0) into splits_total
    from jsonb_array_elements(item -> 'splits') as s;
    if splits_total is distinct from item_total then
      raise exception 'splits for "%" must add up to its amount', item ->> 'name';
    end if;

    insert into expense_items (expense_id, name, amount_cents, kind, split_kind, position)
    values (
      row_out.id, item ->> 'name', item_total,
      coalesce(item ->> 'kind', 'item'),
      coalesce((item ->> 'split_kind')::split_kind, 'equal'),
      coalesce((item ->> 'position')::smallint, 0)
    )
    returning id into item_id;

    insert into expense_item_splits (expense_item_id, profile_id, owed_cents, weight)
    select item_id, (s ->> 'profile_id')::uuid, (s ->> 'owed_cents')::bigint, (s ->> 'weight')::numeric
    from jsonb_array_elements(item -> 'splits') as s;
  end loop;

  -- Check before inserting: expense_splits.owed_cents has its own
  -- `>= 0` check constraint, which would otherwise fire first with a raw
  -- Postgres error instead of this friendlier one.
  select agg.profile_id into neg_person
  from (
    select profile_id, sum(owed_cents) as total
    from expense_item_splits
    where expense_item_id in (select id from expense_items where expense_id = row_out.id)
    group by profile_id
  ) agg
  where agg.total < 0
  limit 1;
  if neg_person is not null then
    raise exception 'no one can end up owing a negative share — assign the discount alongside a purchased item';
  end if;

  insert into expense_splits (expense_id, profile_id, owed_cents)
  select row_out.id, profile_id, sum(owed_cents)
  from expense_item_splits
  where expense_item_id in (select id from expense_items where expense_id = row_out.id)
  group by profile_id;

  insert into activity_log (household_id, actor_id, verb, summary, metadata)
  values (
    hh, auth.uid(), 'added_expense',
    row_out.description || ' — $' || to_char(total / 100.0, 'FM999999990.00'),
    jsonb_build_object('expense_id', row_out.id, 'amount_cents', total)
  );

  return row_out;
end;
$$;


/**************************************************************************
 * 0015_lock_kiosk_rpcs_from_anon.sql
 *************************************************************************/

-- Fixes a real hole in 0012: the kiosk_* functions take an explicit
-- p_profile instead of reading auth.uid(), so they were meant to be callable
-- only by service_role. 0012's lockdown only revoked EXECUTE from
-- 'authenticated'/'domestic_app' (mirroring 0004's precedent) plus the
-- implicit PUBLIC grant — but Supabase also grants 'anon' its own separate
-- default-privilege EXECUTE grant on new functions, the same way it does for
-- 'authenticated'. That grant was never revoked, so an unauthenticated caller
-- (just the anon/public API key — not a secret) could call
-- kiosk_complete_turn / kiosk_flag_chore / kiosk_respond_swap /
-- kiosk_set_chore_active directly with a guessed household/turn/profile id,
-- completely bypassing auth. Revoke from 'anon' too.

do $$
declare r text;
begin
  foreach r in array array['authenticated', 'domestic_app', 'anon'] loop
    if exists (select 1 from pg_roles where rolname = r) then
      execute format('revoke execute on function kiosk_complete_turn(uuid, uuid, uuid, text) from %I', r);
      execute format('revoke execute on function kiosk_flag_chore(uuid, uuid, uuid) from %I', r);
      execute format('revoke execute on function kiosk_respond_swap(uuid, uuid, uuid, boolean) from %I', r);
      execute format('revoke execute on function kiosk_set_chore_active(uuid, uuid, uuid, boolean) from %I', r);
    end if;
  end loop;
end $$;

revoke execute on function kiosk_complete_turn(uuid, uuid, uuid, text) from public;
revoke execute on function kiosk_flag_chore(uuid, uuid, uuid) from public;
revoke execute on function kiosk_respond_swap(uuid, uuid, uuid, boolean) from public;
revoke execute on function kiosk_set_chore_active(uuid, uuid, uuid, boolean) from public;


/**************************************************************************
 * 0016_kiosk_dismiss_message.sql
 *************************************************************************/

/* ------------------------------------------------- kiosk message dismissal */

-- Lets an admin clear a note straight from the wall display, same admin gate
-- as kiosk_set_chore_active / kiosk_respond_swap, before it naturally expires.
create or replace function kiosk_dismiss_message(
  p_household uuid,
  p_message   uuid,
  p_profile   uuid
)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  if not exists (
    select 1 from profiles
    where id = p_profile and household_id = p_household and is_admin
  ) then
    raise exception 'only an admin can do that';
  end if;

  delete from kiosk_messages
   where id = p_message and household_id = p_household;
  if not found then raise exception 'message not found'; end if;
end;
$$;

-- p_profile is explicit rather than auth.uid(), so this must only ever run as
-- service_role — same lockdown as the other kiosk_* RPCs (see 0012, 0015).
do $$
declare r text;
begin
  foreach r in array array['authenticated', 'domestic_app', 'anon'] loop
    if exists (select 1 from pg_roles where rolname = r) then
      execute format('revoke execute on function kiosk_dismiss_message(uuid, uuid, uuid) from %I', r);
    end if;
  end loop;

  if exists (select 1 from pg_roles where rolname = 'service_role') then
    grant execute on function kiosk_dismiss_message(uuid, uuid, uuid) to service_role;
  end if;
end $$;

revoke execute on function kiosk_dismiss_message(uuid, uuid, uuid) from public;


/**************************************************************************
 * 0017_update_expense.sql
 *************************************************************************/

-- Editing an expense in place: replaces its splits (and, for itemized
-- expenses, its items) atomically, the same way create_itemized_expense
-- writes them atomically on the way in. Mirrors that function's validation
-- so a bad edit comes back as a friendly error instead of a raw Postgres one,
-- and so a half-written split set can never desync v_balances.
--
-- p_items non-null/non-empty -> itemized edit, same shape as
-- create_itemized_expense's p_items. p_items null/empty -> plain edit,
-- p_splits carries the already-computed [{profile_id, owed_cents, weight}]
-- (split math itself stays in TypeScript/money.ts, same as addExpense).
create or replace function update_expense(
  p_expense_id   uuid,
  p_description  text,
  p_paid_by      uuid,
  p_spent_on     date,
  p_category     text default 'general',
  p_receipt_url  text default null,
  p_note         text default null,
  p_items        jsonb default null,
  p_split_kind   split_kind default 'equal',
  p_splits       jsonb default null
)
returns expenses
language plpgsql
security definer
set search_path = public
as $$
declare
  hh           uuid;
  row_out      expenses%rowtype;
  item         jsonb;
  item_id      uuid;
  item_total   bigint;
  splits_total bigint;
  total        bigint;
  neg_person   uuid;
begin
  select household_id into hh from expenses where id = p_expense_id and deleted_at is null;
  if hh is null then raise exception 'expense not found'; end if;
  if not is_household_member(hh) then raise exception 'not your household'; end if;

  if not exists (select 1 from profiles where id = p_paid_by and household_id = hh) then
    raise exception 'the payer must be in your household';
  end if;

  if p_items is not null and jsonb_array_length(p_items) > 0 then
    if exists (
      select 1
      from jsonb_array_elements(p_items) as it,
           jsonb_to_recordset(it -> 'splits') as s(profile_id uuid, owed_cents bigint, weight numeric)
      where not exists (select 1 from profiles where id = s.profile_id and household_id = hh)
    ) then
      raise exception 'everyone assigned to an item must be in your household';
    end if;

    select sum((it ->> 'amount_cents')::bigint) into total
    from jsonb_array_elements(p_items) as it;

    -- Cascades to expense_item_splits; a no-op if the expense wasn't itemized before.
    delete from expense_items where expense_id = p_expense_id;
    delete from expense_splits where expense_id = p_expense_id;

    update expenses set
      description  = trim(p_description),
      amount_cents = total,
      category     = coalesce(p_category, 'general'),
      paid_by      = p_paid_by,
      spent_on     = p_spent_on,
      split_kind   = 'itemized',
      receipt_url  = p_receipt_url,
      note         = p_note,
      updated_at   = now()
    where id = p_expense_id
    returning * into row_out;

    for item in select * from jsonb_array_elements(p_items)
    loop
      item_total := (item ->> 'amount_cents')::bigint;

      select coalesce(sum((s ->> 'owed_cents')::bigint), 0) into splits_total
      from jsonb_array_elements(item -> 'splits') as s;
      if splits_total is distinct from item_total then
        raise exception 'splits for "%" must add up to its amount', item ->> 'name';
      end if;

      insert into expense_items (expense_id, name, amount_cents, kind, split_kind, position)
      values (
        p_expense_id, item ->> 'name', item_total,
        coalesce(item ->> 'kind', 'item'),
        coalesce((item ->> 'split_kind')::split_kind, 'equal'),
        coalesce((item ->> 'position')::smallint, 0)
      )
      returning id into item_id;

      insert into expense_item_splits (expense_item_id, profile_id, owed_cents, weight)
      select item_id, (s ->> 'profile_id')::uuid, (s ->> 'owed_cents')::bigint, (s ->> 'weight')::numeric
      from jsonb_array_elements(item -> 'splits') as s;
    end loop;

    select agg.profile_id into neg_person
    from (
      select profile_id, sum(owed_cents) as total
      from expense_item_splits
      where expense_item_id in (select id from expense_items where expense_id = p_expense_id)
      group by profile_id
    ) agg
    where agg.total < 0
    limit 1;
    if neg_person is not null then
      raise exception 'no one can end up owing a negative share — assign the discount alongside a purchased item';
    end if;

    insert into expense_splits (expense_id, profile_id, owed_cents)
    select p_expense_id, profile_id, sum(owed_cents)
    from expense_item_splits
    where expense_item_id in (select id from expense_items where expense_id = p_expense_id)
    group by profile_id;

  else
    if p_splits is null or jsonb_array_length(p_splits) = 0 then
      raise exception 'split it with someone';
    end if;
    if exists (
      select 1 from jsonb_to_recordset(p_splits) as s(profile_id uuid, owed_cents bigint, weight numeric)
      where not exists (select 1 from profiles where id = s.profile_id and household_id = hh)
    ) then
      raise exception 'everyone in the split must be in your household';
    end if;
    if exists (
      select 1 from jsonb_to_recordset(p_splits) as s(profile_id uuid, owed_cents bigint, weight numeric)
      where s.owed_cents < 0
    ) then
      raise exception 'no one can owe a negative amount';
    end if;

    select sum((s ->> 'owed_cents')::bigint) into total
    from jsonb_array_elements(p_splits) as s;
    if total is null or total <= 0 then
      raise exception 'enter an amount greater than zero';
    end if;

    -- Cascades to expense_item_splits; a no-op if the expense wasn't itemized before.
    delete from expense_items where expense_id = p_expense_id;
    delete from expense_splits where expense_id = p_expense_id;

    update expenses set
      description  = trim(p_description),
      amount_cents = total,
      category     = coalesce(p_category, 'general'),
      paid_by      = p_paid_by,
      spent_on     = p_spent_on,
      split_kind   = p_split_kind,
      receipt_url  = p_receipt_url,
      note         = p_note,
      updated_at   = now()
    where id = p_expense_id
    returning * into row_out;

    insert into expense_splits (expense_id, profile_id, owed_cents, weight)
    select p_expense_id, (s ->> 'profile_id')::uuid, (s ->> 'owed_cents')::bigint, (s ->> 'weight')::numeric
    from jsonb_array_elements(p_splits) as s;
  end if;

  insert into activity_log (household_id, actor_id, verb, summary, metadata)
  values (
    hh, auth.uid(), 'updated_expense',
    row_out.description || ' — $' || to_char(row_out.amount_cents / 100.0, 'FM999999990.00'),
    jsonb_build_object('expense_id', row_out.id, 'amount_cents', row_out.amount_cents)
  );

  return row_out;
end;
$$;


/**************************************************************************
 * 0018_skip_and_undo_turn.sql
 *************************************************************************/

-- Two escape hatches for the rotation: skip a pending turn when the person
-- up is out of town, and undo a turn that was completed or skipped by
-- mistake. Both reuse the rotation engine's own machinery
-- (top_up_queue/materialize_schedule) instead of poking chore_turns by hand,
-- and both honor the same allow_member_cross_complete gate complete_turn
-- already enforces (0012_kiosk_interactivity.sql) so "who can act for whom"
-- stays in one place.

-- Marks a pending turn 'skipped' (the turn_status value has existed since
-- 0001 but nothing set it) and immediately opens the next turn, same as
-- complete_turn. turn_number is untouched, so the rest of the rotation still
-- lands on the right person -- skipping turn N just means nobody did N.
create or replace function skip_turn(p_turn uuid, p_note text default null)
returns chore_turns
language plpgsql
security definer
set search_path = public
as $$
declare
  t           chore_turns%rowtype;
  c           chores%rowtype;
  me          uuid := auth.uid();
  allow_cross boolean;
begin
  select * into t from chore_turns where id = p_turn for update;
  if not found then
    raise exception 'turn not found';
  end if;
  if not is_household_member(t.household_id) then
    raise exception 'not your household';
  end if;
  if t.status <> 'pending' then
    raise exception 'that turn is not pending';
  end if;

  if me is distinct from t.assignee_id then
    select allow_member_cross_complete into allow_cross
    from households where id = t.household_id;
    if not coalesce(allow_cross, false) then
      raise exception 'only the assigned member can skip this — an admin can let anyone act for anyone in Settings';
    end if;
  end if;

  update chore_turns
     set status = 'skipped', completed_at = now(), completed_by = me, note = p_note
   where id = p_turn
  returning * into t;

  select * into c from chores where id = t.chore_id;

  if c.cadence = 'on_demand' then
    perform top_up_queue(t.chore_id);
  else
    perform materialize_schedule(t.chore_id);
  end if;

  insert into activity_log (household_id, actor_id, verb, summary, metadata)
  select t.household_id, me,
         'skipped_chore',
         case when me is distinct from t.assignee_id
              then p.full_name || ' skipped ' || c.name || ' for ' || a.full_name
              else p.full_name || ' skipped ' || c.name
         end,
         jsonb_build_object('chore_id', c.id, 'turn_id', t.id, 'emoji', c.emoji)
  from profiles p
  join profiles a on a.id = t.assignee_id
  where p.id = coalesce(me, t.assignee_id);

  return t;
end;
$$;

-- Reverts a 'done' or 'skipped' turn back to 'pending', clearing the fields
-- complete_turn/skip_turn set. Safe on any turn regardless of what has
-- happened since: turn_number is immutable and never reused, so reopening
-- turn N cannot desync anyone else's position in the cycle. Whatever
-- top_up_queue/materialize_schedule already created downstream is left
-- alone -- an on-demand chore just runs one turn over its queue_depth until
-- the next completion naturally lets it settle back down.
create or replace function undo_turn(p_turn uuid)
returns chore_turns
language plpgsql
security definer
set search_path = public
as $$
declare
  t           chore_turns%rowtype;
  c           chores%rowtype;
  me          uuid := auth.uid();
  allow_cross boolean;
  verb_word   text;
begin
  select * into t from chore_turns where id = p_turn for update;
  if not found then
    raise exception 'turn not found';
  end if;
  if not is_household_member(t.household_id) then
    raise exception 'not your household';
  end if;
  if t.status not in ('done', 'skipped') then
    raise exception 'that turn is not done or skipped';
  end if;

  if me is distinct from t.assignee_id then
    select allow_member_cross_complete into allow_cross
    from households where id = t.household_id;
    if not coalesce(allow_cross, false) then
      raise exception 'only the assigned member can undo this — an admin can let anyone act for anyone in Settings';
    end if;
  end if;

  verb_word := case when t.status = 'skipped' then 'skip' else 'done' end;

  update chore_turns
     set status = 'pending', completed_at = null, completed_by = null, note = null
   where id = p_turn
  returning * into t;

  select * into c from chores where id = t.chore_id;

  insert into activity_log (household_id, actor_id, verb, summary, metadata)
  select t.household_id, me, 'undid_chore',
         p.full_name || ' undid ' || verb_word || ' on ' || c.name,
         jsonb_build_object('chore_id', c.id, 'turn_id', t.id, 'emoji', c.emoji)
  from profiles p where p.id = coalesce(me, t.assignee_id);

  return t;
end;
$$;


/**************************************************************************
 * 0019_kiosk_undo_turn.sql
 *************************************************************************/

/* ------------------------------------------------------- kiosk undo turn */

-- Undo, but for the kiosk's device-token + "acting as" model instead of
-- auth.uid() -- same household+profile validation as the other kiosk_* RPCs
-- (0012) and the same rotation-safety guarantee as undo_turn (0018):
-- turn_number is immutable, so reopening a turn can't desync anyone's
-- position in the cycle. Unlike undo_turn, there is no assignee/cross-complete
-- gate here -- the kiosk's "acting as" model is already coarser than the
-- app's, same reasoning as kiosk_complete_turn.
create or replace function kiosk_undo_turn(
  p_household uuid,
  p_turn      uuid,
  p_profile   uuid
)
returns chore_turns
language plpgsql
security definer
set search_path = public
as $$
declare
  t         chore_turns%rowtype;
  c         chores%rowtype;
  verb_word text;
begin
  if not exists (select 1 from profiles where id = p_profile and household_id = p_household) then
    raise exception 'not a member of this household';
  end if;

  select * into t from chore_turns where id = p_turn and household_id = p_household for update;
  if not found then raise exception 'turn not found'; end if;
  if t.status not in ('done', 'skipped') then
    raise exception 'that turn is not done or skipped';
  end if;

  verb_word := case when t.status = 'skipped' then 'skip' else 'done' end;

  update chore_turns
     set status = 'pending', completed_at = null, completed_by = null, note = null
   where id = p_turn
  returning * into t;

  select * into c from chores where id = t.chore_id;

  insert into activity_log (household_id, actor_id, verb, summary, metadata)
  select t.household_id, p_profile, 'undid_chore',
         p.full_name || ' undid ' || verb_word || ' on ' || c.name,
         jsonb_build_object('chore_id', c.id, 'turn_id', t.id, 'emoji', c.emoji)
  from profiles p where p.id = p_profile;

  return t;
end;
$$;

-- p_profile is explicit rather than auth.uid(), so lock to service_role --
-- same pattern as the other kiosk_* RPCs (0012, 0015, 0016).
do $$
declare r text;
begin
  foreach r in array array['authenticated', 'domestic_app', 'anon'] loop
    if exists (select 1 from pg_roles where rolname = r) then
      execute format('revoke execute on function kiosk_undo_turn(uuid, uuid, uuid) from %I', r);
    end if;
  end loop;

  if exists (select 1 from pg_roles where rolname = 'service_role') then
    grant execute on function kiosk_undo_turn(uuid, uuid, uuid) to service_role;
  end if;
end $$;

revoke execute on function kiosk_undo_turn(uuid, uuid, uuid) from public;


/**************************************************************************
 * 0020_away_and_pass_turn.sql
 *************************************************************************/

-- Away status + "pass to next person" as an alternative to "skip the task
-- altogether".
--
-- `skip_turn` (0018) only ever meant "cancel this occurrence". This adds:
--   - member_away: an events table (not columns on profiles) recording who
--     was away when. Kept as history, never overwritten, because
--     resync_pending_turns/materialize_schedule judge a turn against its own
--     due_at, not "right now" -- a later trip must not corrupt the recorded
--     bounds of an earlier one while turns from that earlier window are
--     still pending.
--   - rotation_assignee gains a p_at parameter and skips away members,
--     returning null (pause, no naive fallback) when everyone in the
--     rotation is away at that instant.
--   - pass_turn: reassign the current turn to the next available person,
--     same due date, same turn_number -- distinct from skip_turn.

/* -------------------------------------------------------------- schema */

create table if not exists member_away (
  id           uuid primary key default gen_random_uuid(),
  profile_id   uuid not null references profiles(id) on delete cascade,
  household_id uuid not null references households(id) on delete cascade,
  starts_at    timestamptz not null default now(),
  ends_at      timestamptz,              -- null = indefinite, until cleared
  created_at   timestamptz not null default now()
);

create index if not exists member_away_profile_id_idx on member_away (profile_id, starts_at, ends_at);
create index if not exists member_away_household_id_idx on member_away (household_id);

alter table member_away enable row level security;

drop policy if exists member_away_read on member_away;
create policy member_away_read on member_away for select
  using (is_household_member(household_id));

/* ------------------------------------------------------------- helpers */

create or replace function is_away_at(p_profile uuid, p_at timestamptz default now())
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1 from member_away
    where profile_id = p_profile
      and starts_at <= p_at
      and (ends_at is null or p_at < ends_at)
  );
$$;

/* ------------------------------------------------------------ rotation */

-- Cannot `create or replace` a new parameter onto an existing signature --
-- it creates an ambiguous overload. Drop the old one first.
drop function if exists rotation_assignee(uuid, integer);

create or replace function rotation_assignee(p_chore uuid, p_turn integer, p_at timestamptz default now())
returns uuid
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  n    int;
  base int;
  cand uuid;
begin
  select count(*) into n from chore_rotation where chore_rotation.chore_id = p_chore;
  if n = 0 then
    return null;
  end if;

  base := p_turn % n;
  for i in 0..n - 1 loop
    select profile_id into cand
    from chore_rotation
    where chore_rotation.chore_id = p_chore
      and chore_rotation.position = (base + i) % n;
    if not is_away_at(cand, p_at) then
      return cand;
    end if;
  end loop;

  -- Everyone in the rotation is away at p_at: pause, don't assign anyone.
  return null;
end;
$$;

-- Pass the turn's own due date through, so append_turn judges away-ness
-- against the day the turn actually falls on, not the moment it's created.
create or replace function append_turn(p_chore uuid, p_due timestamptz default null)
returns chore_turns
language plpgsql
security definer
set search_path = public
as $$
declare
  next_no  int;
  who      uuid;
  hh       uuid;
  new_turn chore_turns;
begin
  select household_id into hh from chores where id = p_chore;
  select coalesce(max(turn_number), -1) + 1 into next_no
    from chore_turns where chore_id = p_chore;

  who := rotation_assignee(p_chore, next_no, coalesce(p_due, now()));
  if who is null then
    return null;
  end if;

  insert into chore_turns (chore_id, household_id, turn_number, assignee_id, due_at)
  values (p_chore, hh, next_no, who, p_due)
  returning * into new_turn;

  return new_turn;
end;
$$;

-- append_turn already returns null (and inserts nothing) when nobody's
-- available, but the old loop kept counting `made` regardless -- fix the
-- miscount so a fully-away rotation reports (and does) zero top-up.
create or replace function top_up_queue(p_chore uuid)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  want     int;
  have     int;
  made     int := 0;
  new_turn chore_turns;
begin
  select queue_depth into want from chores where id = p_chore and cadence = 'on_demand';
  if want is null then
    return 0;
  end if;

  select count(*) into have
    from chore_turns where chore_id = p_chore and status = 'pending';

  while have + made < want loop
    new_turn := append_turn(p_chore, null);
    -- Row composites are only NULL when *every* field is null, and a real
    -- turn has non-null fields alongside null ones (completed_at, etc), so
    -- check a definitely-non-null scalar field rather than the whole row.
    exit when new_turn.id is null;
    made := made + 1;
  end loop;

  return made;
end;
$$;

-- Same latent miscount as top_up_queue above: `made` was incremented for
-- every day that matched cadence, whether or not append_turn actually
-- inserted anything. A fully-away day must both create nothing AND not be
-- counted as created -- otherwise a fully-away rotation looks like it
-- materialized turns it didn't.
create or replace function materialize_schedule(p_chore uuid)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  c        chores%rowtype;
  tz       text;
  cursor_d date;
  last_d   date;
  horizon  date;
  made     int := 0;
  wk_off   int;
  anchor_w date;
  new_turn chore_turns;
begin
  select * into c from chores where id = p_chore and cadence = 'scheduled' and is_active;
  if not found or array_length(c.days_of_week, 1) is null then
    return 0;
  end if;

  select timezone into tz from households where id = c.household_id;
  horizon  := (now() at time zone tz)::date + c.lookahead_days;
  anchor_w := date_trunc('week', c.anchor_date)::date;   -- Monday-based

  -- resume after the furthest turn we already created
  select max((due_at at time zone tz)::date) into last_d
    from chore_turns where chore_id = p_chore;

  cursor_d := greatest(
    coalesce(last_d + 1, c.anchor_date),
    (now() at time zone tz)::date
  );

  while cursor_d <= horizon loop
    wk_off := ((date_trunc('week', cursor_d)::date - anchor_w) / 7)::int;
    if (extract(dow from cursor_d)::smallint = any (c.days_of_week))
       and (wk_off % greatest(c.interval_weeks, 1) = 0) then
      new_turn := append_turn(
        p_chore,
        ((cursor_d + make_interval(hours => c.due_hour)) at time zone tz)
      );
      -- Same row-composite gotcha as top_up_queue above: IS NOT NULL on a
      -- row requires *every* field to be non-null, which a real (partially
      -- null) turn never satisfies. Check a definitely-non-null field.
      if new_turn.id is not null then
        made := made + 1;
      end if;
    end if;
    cursor_d := cursor_d + 1;
  end loop;

  return made;
end;
$$;

-- Due-date aware, and handles the "nobody available" case: assignee_id is
-- not null, so a turn nobody can be assigned to gets auto-skipped (logged)
-- instead of reassigned to null.
create or replace function resync_pending_turns(p_chore uuid)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  touched int := 0;
  t       record;
  next_id uuid;
  c       chores%rowtype;
begin
  select * into c from chores where id = p_chore;

  for t in
    select * from chore_turns where chore_id = p_chore and status = 'pending' for update
  loop
    next_id := rotation_assignee(t.chore_id, t.turn_number, coalesce(t.due_at, now()));

    if next_id is null then
      update chore_turns
         set status = 'skipped', completed_at = now(),
             note = coalesce(note, 'everyone was away')
       where id = t.id;

      insert into activity_log (household_id, actor_id, verb, summary, metadata)
      values (t.household_id, null, 'skipped_chore',
              c.name || ' skipped — everyone was away',
              jsonb_build_object('chore_id', c.id, 'turn_id', t.id, 'emoji', c.emoji));

      touched := touched + 1;
    elsif next_id is distinct from t.assignee_id then
      update chore_turns set assignee_id = next_id where id = t.id;
      touched := touched + 1;
    end if;
  end loop;

  return touched;
end;
$$;

/* ------------------------------------------------------------ away RPCs */

create or replace function set_away(p_until timestamptz default null)
returns member_away
language plpgsql
security definer
set search_path = public
as $$
declare
  me   uuid := auth.uid();
  hh   uuid;
  name text;
  row  member_away%rowtype;
  c    record;
begin
  select household_id, full_name into hh, name from profiles where id = me;
  if hh is null then raise exception 'you are not in a household'; end if;

  update member_away
     set ends_at = now()
   where profile_id = me
     and starts_at <= now()
     and (ends_at is null or now() < ends_at);

  insert into member_away (profile_id, household_id, ends_at)
  values (me, hh, p_until)
  returning * into row;

  for c in select id, cadence from chores where household_id = hh and is_active loop
    perform resync_pending_turns(c.id);
    if c.cadence = 'on_demand' then
      perform top_up_queue(c.id);
    end if;
  end loop;

  insert into activity_log (household_id, actor_id, verb, summary, metadata)
  values (hh, me, 'set_away',
          name || ' is away' || case when p_until is not null
            then ' until ' || to_char(p_until, 'Mon DD') else '' end,
          jsonb_build_object('until', p_until));

  return row;
end;
$$;

create or replace function clear_away()
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  me   uuid := auth.uid();
  hh   uuid;
  name text;
  c    record;
begin
  select household_id, full_name into hh, name from profiles where id = me;
  if hh is null then raise exception 'you are not in a household'; end if;

  update member_away
     set ends_at = now()
   where profile_id = me
     and starts_at <= now()
     and (ends_at is null or now() < ends_at);

  for c in select id, cadence from chores where household_id = hh and is_active loop
    perform resync_pending_turns(c.id);
    if c.cadence = 'on_demand' then
      perform top_up_queue(c.id);
    end if;
  end loop;

  insert into activity_log (household_id, actor_id, verb, summary, metadata)
  values (hh, me, 'cleared_away', name || ' is back', '{}'::jsonb);
end;
$$;

/* --------------------------------------------------------------- pass */

-- "Pass to the next person" -- distinct from skip_turn: keeps the same
-- turn_number/due_at/status, just moves the baton to whoever's next in the
-- rotation (skipping anyone away). Raises rather than falling back to skip
-- when nobody else is available, so the caller explicitly chooses skip_turn
-- instead in that case.
create or replace function pass_turn(p_turn uuid, p_note text default null)
returns chore_turns
language plpgsql
security definer
set search_path = public
as $$
declare
  t          chore_turns%rowtype;
  c          chores%rowtype;
  me         uuid := auth.uid();
  allow_cross boolean;
  n          int;
  cur_pos    int;
  at         timestamptz;
  next_id    uuid;
  cand       uuid;
begin
  select * into t from chore_turns where id = p_turn for update;
  if not found then raise exception 'turn not found'; end if;
  if not is_household_member(t.household_id) then raise exception 'not your household'; end if;
  if t.status <> 'pending' then raise exception 'that turn is not pending'; end if;

  if me is distinct from t.assignee_id then
    select allow_member_cross_complete into allow_cross from households where id = t.household_id;
    if not coalesce(allow_cross, false) then
      raise exception 'only the assigned member can pass this — an admin can let anyone act for anyone in Settings';
    end if;
  end if;

  select count(*) into n from chore_rotation where chore_id = t.chore_id;
  if n <= 1 then
    raise exception 'no one else in the rotation to pass to';
  end if;

  select position into cur_pos from chore_rotation
   where chore_id = t.chore_id and profile_id = t.assignee_id;
  at := coalesce(t.due_at, now());

  if cur_pos is not null then
    for i in 1..n - 1 loop
      select profile_id into cand
      from chore_rotation
      where chore_id = t.chore_id and position = (cur_pos + i) % n;
      if not is_away_at(cand, at) then
        next_id := cand;
        exit;
      end if;
    end loop;
  end if;

  if next_id is null then
    raise exception 'everyone else is away — skip the task instead';
  end if;

  update chore_turns
     set assignee_id = next_id, note = coalesce(p_note, note)
   where id = p_turn
   returning * into t;

  select * into c from chores where id = t.chore_id;

  insert into activity_log (household_id, actor_id, verb, summary, metadata)
  select t.household_id, me, 'passed_chore',
         p.full_name || ' passed ' || c.name || ' to ' || nx.full_name,
         jsonb_build_object('chore_id', c.id, 'turn_id', t.id, 'emoji', c.emoji)
  from profiles p, profiles nx
  where p.id = coalesce(me, t.assignee_id) and nx.id = next_id;

  return t;
end;
$$;


/**************************************************************************
 * 0021_standing_chores.sql
 *************************************************************************/

-- A third cadence: `standing`. Some chores aren't naturally "on a schedule"
-- or "a queue you flag when it's full" — they're just always somebody's job
-- until they hand it off (take out recycling, restock TP). A standing chore
-- has exactly one pending turn at a time, no due date, and is always visible
-- in the to-do list without needing a flag. Completing it is an instant
-- baton-pass: the next person's turn opens immediately.
--
-- This is implemented as on_demand's queue model with queue_depth pinned to
-- 1 — no new turn-creation machinery, just top_up_queue generalized to know
-- about it.
--
-- `alter type ... add value` must not run in the same transaction as its
-- first use. This file has no explicit BEGIN, so each top-level statement
-- here autocommits on its own (same as 0001's original enum creation), which
-- is why the enum is extended first and used starting with the next
-- statement.

alter type chore_cadence add value if not exists 'standing';

/* ---------------------------------------------------------- top_up_queue */

-- on_demand keeps `queue_depth` turns pending; standing always wants exactly
-- one (the "current" turn) and ignores queue_depth entirely; scheduled chores
-- go through materialize_schedule instead, same as before.
create or replace function top_up_queue(p_chore uuid)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  cad      chore_cadence;
  want     int;
  have     int;
  made     int := 0;
  new_turn chore_turns;
begin
  select cadence into cad from chores where id = p_chore;

  if cad = 'on_demand' then
    select queue_depth into want from chores where id = p_chore;
  elsif cad = 'standing' then
    want := 1;
  else
    return 0;
  end if;

  select count(*) into have
    from chore_turns where chore_id = p_chore and status = 'pending';

  while have + made < want loop
    new_turn := append_turn(p_chore, null);
    exit when new_turn.id is null;
    made := made + 1;
  end loop;

  return made;
end;
$$;

/* ------------------------------------------------ cadence-branch fix-ups */

-- complete_turn / kiosk_complete_turn / skip_turn all branched
-- `if cadence = 'on_demand' then top_up_queue else materialize_schedule` —
-- a standing chore fell into the `else` and hit materialize_schedule, which
-- silently no-ops on anything but `scheduled` (its own guard). Net effect
-- without this fix: a standing chore's queue would never refill past the
-- first completion. Flip the branch so scheduled is the special case.

create or replace function complete_turn(p_turn uuid, p_note text default null)
returns chore_turns
language plpgsql
security definer
set search_path = public
as $$
declare
  t           chore_turns%rowtype;
  c           chores%rowtype;
  me          uuid := auth.uid();
  allow_cross boolean;
begin
  select * into t from chore_turns where id = p_turn for update;
  if not found then
    raise exception 'turn not found';
  end if;
  if not is_household_member(t.household_id) then
    raise exception 'not your household';
  end if;
  if t.status = 'done' then
    return t;
  end if;

  if me is distinct from t.assignee_id then
    select allow_member_cross_complete into allow_cross
    from households where id = t.household_id;
    if not coalesce(allow_cross, false) then
      raise exception 'only the assigned member can complete this — an admin can let anyone complete anyone''s chores in Settings';
    end if;
  end if;

  update chore_turns
     set status = 'done', completed_at = now(), completed_by = coalesce(me, t.assignee_id), note = p_note
   where id = p_turn
  returning * into t;

  select * into c from chores where id = t.chore_id;

  if c.cadence = 'scheduled' then
    perform materialize_schedule(t.chore_id);
  else
    perform top_up_queue(t.chore_id);
  end if;

  insert into activity_log (household_id, actor_id, verb, summary, metadata)
  select t.household_id, coalesce(me, t.assignee_id), 'completed_chore',
         p.full_name || ' did ' || c.name,
         jsonb_build_object('chore_id', c.id, 'turn_id', t.id, 'emoji', c.emoji)
  from profiles p where p.id = coalesce(me, t.assignee_id);

  return t;
end;
$$;

create or replace function kiosk_complete_turn(
  p_household uuid,
  p_turn      uuid,
  p_profile   uuid,
  p_note      text default null
)
returns chore_turns
language plpgsql
security definer
set search_path = public
as $$
declare
  t chore_turns%rowtype;
  c chores%rowtype;
begin
  if not exists (select 1 from profiles where id = p_profile and household_id = p_household) then
    raise exception 'not a member of this household';
  end if;

  select * into t from chore_turns where id = p_turn and household_id = p_household for update;
  if not found then raise exception 'turn not found'; end if;
  if t.status = 'done' then return t; end if;

  update chore_turns
     set status = 'done', completed_at = now(), completed_by = p_profile, note = p_note
   where id = p_turn
  returning * into t;

  select * into c from chores where id = t.chore_id;

  if c.cadence = 'scheduled' then
    perform materialize_schedule(t.chore_id);
  else
    perform top_up_queue(t.chore_id);
  end if;

  insert into activity_log (household_id, actor_id, verb, summary, metadata)
  select t.household_id, p_profile, 'completed_chore',
         p.full_name || ' did ' || c.name,
         jsonb_build_object('chore_id', c.id, 'turn_id', t.id, 'emoji', c.emoji)
  from profiles p where p.id = p_profile;

  return t;
end;
$$;

create or replace function skip_turn(p_turn uuid, p_note text default null)
returns chore_turns
language plpgsql
security definer
set search_path = public
as $$
declare
  t           chore_turns%rowtype;
  c           chores%rowtype;
  me          uuid := auth.uid();
  allow_cross boolean;
begin
  select * into t from chore_turns where id = p_turn for update;
  if not found then
    raise exception 'turn not found';
  end if;
  if not is_household_member(t.household_id) then
    raise exception 'not your household';
  end if;
  if t.status <> 'pending' then
    raise exception 'that turn is not pending';
  end if;

  if me is distinct from t.assignee_id then
    select allow_member_cross_complete into allow_cross
    from households where id = t.household_id;
    if not coalesce(allow_cross, false) then
      raise exception 'only the assigned member can skip this — an admin can let anyone act for anyone in Settings';
    end if;
  end if;

  update chore_turns
     set status = 'skipped', completed_at = now(), completed_by = me, note = p_note
   where id = p_turn
  returning * into t;

  select * into c from chores where id = t.chore_id;

  if c.cadence = 'scheduled' then
    perform materialize_schedule(t.chore_id);
  else
    perform top_up_queue(t.chore_id);
  end if;

  insert into activity_log (household_id, actor_id, verb, summary, metadata)
  select t.household_id, me,
         'skipped_chore',
         case when me is distinct from t.assignee_id
              then p.full_name || ' skipped ' || c.name || ' for ' || a.full_name
              else p.full_name || ' skipped ' || c.name
         end,
         jsonb_build_object('chore_id', c.id, 'turn_id', t.id, 'emoji', c.emoji)
  from profiles p
  join profiles a on a.id = t.assignee_id
  where p.id = coalesce(me, t.assignee_id);

  return t;
end;
$$;

-- set_away/clear_away only topped up on_demand chores after resyncing —
-- standing chores need the same top-up (they are, in effect, a queue of
-- depth 1) or a standing chore could sit with zero pending turns after
-- everyone's away status changes.
create or replace function set_away(p_until timestamptz default null)
returns member_away
language plpgsql
security definer
set search_path = public
as $$
declare
  me   uuid := auth.uid();
  hh   uuid;
  name text;
  row  member_away%rowtype;
  c    record;
begin
  select household_id, full_name into hh, name from profiles where id = me;
  if hh is null then raise exception 'you are not in a household'; end if;

  update member_away
     set ends_at = now()
   where profile_id = me
     and starts_at <= now()
     and (ends_at is null or now() < ends_at);

  insert into member_away (profile_id, household_id, ends_at)
  values (me, hh, p_until)
  returning * into row;

  for c in select id, cadence from chores where household_id = hh and is_active loop
    perform resync_pending_turns(c.id);
    if c.cadence <> 'scheduled' then
      perform top_up_queue(c.id);
    end if;
  end loop;

  insert into activity_log (household_id, actor_id, verb, summary, metadata)
  values (hh, me, 'set_away',
          name || ' is away' || case when p_until is not null
            then ' until ' || to_char(p_until, 'Mon DD') else '' end,
          jsonb_build_object('until', p_until));

  return row;
end;
$$;

create or replace function clear_away()
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  me   uuid := auth.uid();
  hh   uuid;
  name text;
  c    record;
begin
  select household_id, full_name into hh, name from profiles where id = me;
  if hh is null then raise exception 'you are not in a household'; end if;

  update member_away
     set ends_at = now()
   where profile_id = me
     and starts_at <= now()
     and (ends_at is null or now() < ends_at);

  for c in select id, cadence from chores where household_id = hh and is_active loop
    perform resync_pending_turns(c.id);
    if c.cadence <> 'scheduled' then
      perform top_up_queue(c.id);
    end if;
  end loop;

  insert into activity_log (household_id, actor_id, verb, summary, metadata)
  values (hh, me, 'cleared_away', name || ' is back', '{}'::jsonb);
end;
$$;

/* ---------------------------------------------------------------- undo */

-- Reopening a done/skipped STANDING turn must not leave two pending turns
-- alive at once — top_up_queue already created the next one the moment this
-- turn resolved. That next turn is not real history (it was never done or
-- skipped), so deleting it before reopening the original is safe and keeps
-- "exactly one pending turn" true for standing chores.
create or replace function undo_turn(p_turn uuid)
returns chore_turns
language plpgsql
security definer
set search_path = public
as $$
declare
  t           chore_turns%rowtype;
  c           chores%rowtype;
  me          uuid := auth.uid();
  allow_cross boolean;
  verb_word   text;
begin
  select * into t from chore_turns where id = p_turn for update;
  if not found then
    raise exception 'turn not found';
  end if;
  if not is_household_member(t.household_id) then
    raise exception 'not your household';
  end if;
  if t.status not in ('done', 'skipped') then
    raise exception 'that turn is not done or skipped';
  end if;

  if me is distinct from t.assignee_id then
    select allow_member_cross_complete into allow_cross
    from households where id = t.household_id;
    if not coalesce(allow_cross, false) then
      raise exception 'only the assigned member can undo this — an admin can let anyone act for anyone in Settings';
    end if;
  end if;

  verb_word := case when t.status = 'skipped' then 'skip' else 'done' end;

  select * into c from chores where id = t.chore_id;
  if c.cadence = 'standing' then
    delete from chore_turns
     where chore_id = t.chore_id and status = 'pending' and turn_number > t.turn_number;
  end if;

  update chore_turns
     set status = 'pending', completed_at = null, completed_by = null, note = null
   where id = p_turn
  returning * into t;

  insert into activity_log (household_id, actor_id, verb, summary, metadata)
  select t.household_id, me, 'undid_chore',
         p.full_name || ' undid ' || verb_word || ' on ' || c.name,
         jsonb_build_object('chore_id', c.id, 'turn_id', t.id, 'emoji', c.emoji)
  from profiles p where p.id = coalesce(me, t.assignee_id);

  return t;
end;
$$;


/**************************************************************************
 * 0022_turn_flags.sql
 *************************************************************************/

-- A per-person nudge, distinct from flag_on_demand (0002/0012): that one is
-- chore-wide ("the dishwasher is full") and only exists for on_demand chores.
-- This one points at a specific housemate on any pending turn ("hey, this
-- needs you") without changing who the rotation says is actually up — a
-- visible reminder, not a reassignment. Columns rather than a table: a flag
-- is a single overwritable nudge, not history worth keeping once resolved.

alter table chore_turns
  add column if not exists flagged_for uuid references profiles(id) on delete set null,
  add column if not exists flagged_by  uuid references profiles(id) on delete set null,
  add column if not exists flagged_at  timestamptz,
  add column if not exists flag_note   text
    check (flag_note is null or char_length(flag_note) <= 140);

/* --------------------------------------------------------------- flag/clear */

create or replace function flag_turn(p_turn uuid, p_target uuid, p_message text default null)
returns chore_turns
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  t  chore_turns%rowtype;
  c  chores%rowtype;
begin
  select * into t from chore_turns where id = p_turn for update;
  if not found then raise exception 'turn not found'; end if;
  if not is_household_member(t.household_id) then raise exception 'not your household'; end if;
  if t.status <> 'pending' then raise exception 'that turn is not pending'; end if;
  if not exists (select 1 from profiles where id = p_target and household_id = t.household_id) then
    raise exception 'that person is not in your household';
  end if;

  update chore_turns
     set flagged_for = p_target, flagged_by = coalesce(me, t.assignee_id),
         flagged_at = now(), flag_note = nullif(trim(coalesce(p_message, '')), '')
   where id = p_turn
  returning * into t;

  select * into c from chores where id = t.chore_id;
  insert into activity_log (household_id, actor_id, verb, summary, metadata)
  select t.household_id, me,
         'flagged_for',
         p.full_name || ' flagged ' || c.name || ' for ' || tgt.full_name,
         jsonb_build_object('chore_id', c.id, 'turn_id', t.id, 'emoji', c.emoji)
  from profiles p, profiles tgt
  where p.id = coalesce(me, t.assignee_id) and tgt.id = p_target;

  return t;
end;
$$;

-- Restricted to the people the flag actually concerns — the flagger, the
-- flagged person, or whoever the turn is assigned to — rather than any
-- household member, so a flag can't be dismissed by someone uninvolved.
create or replace function clear_flag(p_turn uuid)
returns chore_turns
language plpgsql
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  t  chore_turns%rowtype;
begin
  select * into t from chore_turns where id = p_turn for update;
  if not found then raise exception 'turn not found'; end if;
  if not is_household_member(t.household_id) then raise exception 'not your household'; end if;
  if me is distinct from t.flagged_by and me is distinct from t.flagged_for and me is distinct from t.assignee_id then
    raise exception 'only the flagger, the flagged person, or the assignee can clear this';
  end if;

  update chore_turns
     set flagged_for = null, flagged_by = null, flagged_at = null, flag_note = null
   where id = p_turn
  returning * into t;

  return t;
end;
$$;

/* -------------------------------------------- clear the flag on resolution */

-- A flag is a nudge about a turn that still needs doing; once it's resolved
-- (done or skipped) the nudge is moot. Not cleared by pass_turn (the flag
-- still applies to whoever it now lands on) or undo_turn (already null by
-- the time undo runs, since complete/skip just cleared it).

create or replace function complete_turn(p_turn uuid, p_note text default null)
returns chore_turns
language plpgsql
security definer
set search_path = public
as $$
declare
  t           chore_turns%rowtype;
  c           chores%rowtype;
  me          uuid := auth.uid();
  allow_cross boolean;
begin
  select * into t from chore_turns where id = p_turn for update;
  if not found then
    raise exception 'turn not found';
  end if;
  if not is_household_member(t.household_id) then
    raise exception 'not your household';
  end if;
  if t.status = 'done' then
    return t;
  end if;

  if me is distinct from t.assignee_id then
    select allow_member_cross_complete into allow_cross
    from households where id = t.household_id;
    if not coalesce(allow_cross, false) then
      raise exception 'only the assigned member can complete this — an admin can let anyone complete anyone''s chores in Settings';
    end if;
  end if;

  update chore_turns
     set status = 'done', completed_at = now(), completed_by = coalesce(me, t.assignee_id), note = p_note,
         flagged_for = null, flagged_by = null, flagged_at = null, flag_note = null
   where id = p_turn
  returning * into t;

  select * into c from chores where id = t.chore_id;

  if c.cadence = 'scheduled' then
    perform materialize_schedule(t.chore_id);
  else
    perform top_up_queue(t.chore_id);
  end if;

  insert into activity_log (household_id, actor_id, verb, summary, metadata)
  select t.household_id, coalesce(me, t.assignee_id), 'completed_chore',
         p.full_name || ' did ' || c.name,
         jsonb_build_object('chore_id', c.id, 'turn_id', t.id, 'emoji', c.emoji)
  from profiles p where p.id = coalesce(me, t.assignee_id);

  return t;
end;
$$;

create or replace function kiosk_complete_turn(
  p_household uuid,
  p_turn      uuid,
  p_profile   uuid,
  p_note      text default null
)
returns chore_turns
language plpgsql
security definer
set search_path = public
as $$
declare
  t chore_turns%rowtype;
  c chores%rowtype;
begin
  if not exists (select 1 from profiles where id = p_profile and household_id = p_household) then
    raise exception 'not a member of this household';
  end if;

  select * into t from chore_turns where id = p_turn and household_id = p_household for update;
  if not found then raise exception 'turn not found'; end if;
  if t.status = 'done' then return t; end if;

  update chore_turns
     set status = 'done', completed_at = now(), completed_by = p_profile, note = p_note,
         flagged_for = null, flagged_by = null, flagged_at = null, flag_note = null
   where id = p_turn
  returning * into t;

  select * into c from chores where id = t.chore_id;

  if c.cadence = 'scheduled' then
    perform materialize_schedule(t.chore_id);
  else
    perform top_up_queue(t.chore_id);
  end if;

  insert into activity_log (household_id, actor_id, verb, summary, metadata)
  select t.household_id, p_profile, 'completed_chore',
         p.full_name || ' did ' || c.name,
         jsonb_build_object('chore_id', c.id, 'turn_id', t.id, 'emoji', c.emoji)
  from profiles p where p.id = p_profile;

  return t;
end;
$$;

create or replace function skip_turn(p_turn uuid, p_note text default null)
returns chore_turns
language plpgsql
security definer
set search_path = public
as $$
declare
  t           chore_turns%rowtype;
  c           chores%rowtype;
  me          uuid := auth.uid();
  allow_cross boolean;
begin
  select * into t from chore_turns where id = p_turn for update;
  if not found then
    raise exception 'turn not found';
  end if;
  if not is_household_member(t.household_id) then
    raise exception 'not your household';
  end if;
  if t.status <> 'pending' then
    raise exception 'that turn is not pending';
  end if;

  if me is distinct from t.assignee_id then
    select allow_member_cross_complete into allow_cross
    from households where id = t.household_id;
    if not coalesce(allow_cross, false) then
      raise exception 'only the assigned member can skip this — an admin can let anyone act for anyone in Settings';
    end if;
  end if;

  update chore_turns
     set status = 'skipped', completed_at = now(), completed_by = me, note = p_note,
         flagged_for = null, flagged_by = null, flagged_at = null, flag_note = null
   where id = p_turn
  returning * into t;

  select * into c from chores where id = t.chore_id;

  if c.cadence = 'scheduled' then
    perform materialize_schedule(t.chore_id);
  else
    perform top_up_queue(t.chore_id);
  end if;

  insert into activity_log (household_id, actor_id, verb, summary, metadata)
  select t.household_id, me,
         'skipped_chore',
         case when me is distinct from t.assignee_id
              then p.full_name || ' skipped ' || c.name || ' for ' || a.full_name
              else p.full_name || ' skipped ' || c.name
         end,
         jsonb_build_object('chore_id', c.id, 'turn_id', t.id, 'emoji', c.emoji)
  from profiles p
  join profiles a on a.id = t.assignee_id
  where p.id = coalesce(me, t.assignee_id);

  return t;
end;
$$;


/**************************************************************************
 * 0023_get_ahead_and_defer.sql
 *************************************************************************/

-- Get ahead / defer: two personal, self-only escape hatches for someone who
-- knows they'll be busy. Neither one reassigns or reorders anyone else's
-- turn — get_ahead completes your own next turn early; defer pushes your own
-- turn's due date later. Both are rate-limited (default: 2 "ahead"/deferred
-- at a time, 1 use per rolling 30 days) to keep them from being used to
-- dodge the rotation outright, admin-configurable, on by default, and
-- admin-disableable.
--
-- Config lives in household_modules.settings under a new module key
-- 'get_ahead' — deliberately not added to src/lib/modules.ts's page-having
-- registry, since household_modules/set_module are already generic by
-- design (CLAUDE.md calls the unused `settings` jsonb column exactly the
-- right home for this). "No row for this household" means enabled — safe
-- because 'get_ahead' is not in default_modules(), so create_household()
-- never inserts a `false` row for it.

create table if not exists chore_advance_log (
  id         uuid primary key default gen_random_uuid(),
  chore_id   uuid not null references chores(id) on delete cascade,
  profile_id uuid not null references profiles(id) on delete cascade,
  kind       text not null check (kind in ('get_ahead', 'defer')),
  turn_id    uuid not null references chore_turns(id) on delete cascade,
  created_at timestamptz not null default now()
);

create index if not exists chore_advance_log_chore_profile_kind_idx
  on chore_advance_log (chore_id, profile_id, kind, created_at desc);
create index if not exists chore_advance_log_turn_id_idx on chore_advance_log (turn_id);

alter table chore_advance_log enable row level security;

drop policy if exists advance_log_read on chore_advance_log;
create policy advance_log_read on chore_advance_log for select
  using (exists (select 1 from chores c where c.id = chore_id and is_household_member(c.household_id)));
-- No insert/update/delete policy: writes only through get_ahead()/defer_turn() below.

/* -------------------------------------------------------------- helpers */

-- Mirrors materialize_schedule's own day/interval matching rule, kept as a
-- standalone function rather than reusing materialize_schedule itself, so
-- this feature can't risk regressing that function's tested loop.
create or replace function next_scheduled_date(p_chore uuid, p_after date)
returns date
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  c        chores%rowtype;
  cursor_d date;
  anchor_w date;
  wk_off   int;
begin
  select * into c from chores where id = p_chore and cadence = 'scheduled';
  if not found or array_length(c.days_of_week, 1) is null then
    return null;
  end if;

  anchor_w := date_trunc('week', c.anchor_date)::date;
  cursor_d := p_after + 1;

  loop
    wk_off := ((date_trunc('week', cursor_d)::date - anchor_w) / 7)::int;
    if (extract(dow from cursor_d)::smallint = any (c.days_of_week))
       and (wk_off % greatest(c.interval_weeks, 1) = 0) then
      return cursor_d;
    end if;
    cursor_d := cursor_d + 1;
  end loop;
end;
$$;

/* ------------------------------------------------------------- get_ahead */

-- Standing chores are excluded: get-ahead's only possible implementation
-- would require more than one simultaneously-pending turn on a chore whose
-- entire model is "exactly one pending turn at a time" — pass_turn is
-- already the right release valve there.
create or replace function get_ahead(p_chore uuid)
returns chore_turns
language plpgsql
security definer
set search_path = public
as $$
declare
  me          uuid := auth.uid();
  c           chores%rowtype;
  n           int;
  mod_enabled boolean;
  mod_settings jsonb;
  max_ahead   int;
  max_per_30d int;
  cursor_no   int;
  ahead_count int;
  uses_30d    int;
  target      chore_turns%rowtype;
  tz          text;
  next_due    date;
  last_due    date;
  iterations  int := 0;
  cap         constant int := 500;
begin
  select * into c from chores where id = p_chore;
  if not found then raise exception 'chore not found'; end if;
  if not is_household_member(c.household_id) then raise exception 'not your household'; end if;
  if c.cadence = 'standing' then
    raise exception 'get-ahead does not apply to standing chores — pass it on if you cannot get to it';
  end if;
  if not exists (select 1 from chore_rotation where chore_id = p_chore and profile_id = me) then
    raise exception 'you are not in this chore''s rotation';
  end if;

  select enabled, settings into mod_enabled, mod_settings
    from household_modules where household_id = c.household_id and module = 'get_ahead';
  if not coalesce(mod_enabled, true) then raise exception 'get-ahead is turned off for this house'; end if;
  mod_settings := coalesce(mod_settings, '{}'::jsonb);
  max_ahead   := coalesce((mod_settings #>> '{get_ahead,max_ahead}')::int, 2);
  max_per_30d := coalesce((mod_settings #>> '{get_ahead,max_per_30d}')::int, 1);

  select count(*) into uses_30d from chore_advance_log
   where chore_id = p_chore and profile_id = me and kind = 'get_ahead'
     and created_at > now() - interval '30 days';
  if uses_30d >= max_per_30d then
    raise exception 'You have used get-ahead % time(s) in the last 30 days — the house limit is %.', uses_30d, max_per_30d;
  end if;

  -- "Already N ahead" = N of your get_ahead completions still sit beyond the
  -- chore's current pending frontier. This self-resolves as the rotation
  -- naturally catches up to and past those turns — no reset job needed.
  select case when min(turn_number) is null
           then (select coalesce(max(turn_number), -1) from chore_turns where chore_id = p_chore)
           else min(turn_number) - 1 end
    into cursor_no
  from chore_turns where chore_id = p_chore and status = 'pending';

  select count(*) into ahead_count
  from chore_advance_log l join chore_turns t on t.id = l.turn_id
  where l.chore_id = p_chore and l.profile_id = me and l.kind = 'get_ahead' and t.turn_number > cursor_no;
  if ahead_count >= max_ahead then
    raise exception 'You are already % turn(s) ahead on this chore — let the rotation catch up first.', max_ahead;
  end if;

  -- Common case: you already have a pending turn of your own materialized.
  select * into target from chore_turns
   where chore_id = p_chore and status = 'pending' and assignee_id = me
   order by turn_number limit 1;

  if not found then
    -- Rare case: walk forward, materializing turns as we go, until we reach
    -- one that lands on you. Bounded so an unreachable rotation (nobody
    -- assignable) can't loop forever.
    select count(*) into n from chore_rotation where chore_id = p_chore;
    if n = 0 then raise exception 'this chore has no rotation'; end if;

    if c.cadence = 'scheduled' then
      select timezone into tz from households where id = c.household_id;
      select coalesce(max((due_at at time zone tz)::date), c.anchor_date - 1) into last_due
        from chore_turns where chore_id = p_chore;
      loop
        iterations := iterations + 1;
        exit when iterations > cap;
        next_due := next_scheduled_date(p_chore, last_due);
        exit when next_due is null;
        target := append_turn(p_chore, (next_due + make_interval(hours => c.due_hour)) at time zone tz);
        last_due := next_due;
        exit when target.id is not null and target.assignee_id = me;
      end loop;
    else
      loop
        iterations := iterations + 1;
        exit when iterations > cap;
        target := append_turn(p_chore, null);
        exit when target.id is null;
        exit when target.assignee_id = me;
      end loop;
    end if;

    if target.id is null or target.assignee_id is distinct from me then
      raise exception 'could not find an upcoming turn of yours to get ahead on';
    end if;
  end if;

  update chore_turns
     set status = 'done', completed_at = now(), completed_by = me,
         note = coalesce(note, 'Done ahead of schedule')
   where id = target.id
  returning * into target;

  -- Same post-completion top-up complete_turn does — without it, an
  -- on_demand queue would run one turn short of queue_depth after a get-ahead.
  if c.cadence = 'scheduled' then
    perform materialize_schedule(p_chore);
  else
    perform top_up_queue(p_chore);
  end if;

  insert into chore_advance_log (chore_id, profile_id, kind, turn_id)
  values (p_chore, me, 'get_ahead', target.id);

  insert into activity_log (household_id, actor_id, verb, summary, metadata)
  select c.household_id, me, 'got_ahead', p.full_name || ' got ahead on ' || c.name,
         jsonb_build_object('chore_id', c.id, 'turn_id', target.id, 'emoji', c.emoji)
  from profiles p where p.id = me;

  return target;
end;
$$;

/* --------------------------------------------------------------- defer */

create or replace function defer_turn(p_turn uuid)
returns chore_turns
language plpgsql
security definer
set search_path = public
as $$
declare
  me          uuid := auth.uid();
  t           chore_turns%rowtype;
  c           chores%rowtype;
  mod_enabled boolean;
  mod_settings jsonb;
  max_defers  int;
  max_per_30d int;
  defer_count int;
  uses_30d    int;
  tz          text;
  next_due    date;
begin
  select * into t from chore_turns where id = p_turn for update;
  if not found then raise exception 'turn not found'; end if;
  if not is_household_member(t.household_id) then raise exception 'not your household'; end if;
  if t.status <> 'pending' then raise exception 'that turn is not pending'; end if;
  if me is distinct from t.assignee_id then raise exception 'you can only defer your own turn'; end if;
  if t.due_at is null then raise exception 'this turn has no due date to push back'; end if;

  select * into c from chores where id = t.chore_id;
  -- Standing turns never carry a due_at, so the check above already excludes
  -- them; pass_turn is the equivalent tool there.

  select enabled, settings into mod_enabled, mod_settings
    from household_modules where household_id = c.household_id and module = 'get_ahead';
  if not coalesce(mod_enabled, true) then raise exception 'get-ahead/defer is turned off for this house'; end if;
  mod_settings := coalesce(mod_settings, '{}'::jsonb);
  max_defers  := coalesce((mod_settings #>> '{defer,max_ahead}')::int, 2);
  max_per_30d := coalesce((mod_settings #>> '{defer,max_per_30d}')::int, 1);

  select count(*) into defer_count from chore_advance_log where turn_id = p_turn and kind = 'defer';
  if defer_count >= max_defers then
    raise exception 'This turn has already been deferred % time(s) — go ahead and do it, skip it, or pass it.', max_defers;
  end if;

  select count(*) into uses_30d from chore_advance_log
   where chore_id = t.chore_id and profile_id = me and kind = 'defer'
     and created_at > now() - interval '30 days';
  if uses_30d >= max_per_30d then
    raise exception 'You have deferred % time(s) in the last 30 days — the house limit is %.', uses_30d, max_per_30d;
  end if;

  if c.cadence = 'scheduled' then
    select timezone into tz from households where id = c.household_id;
    next_due := next_scheduled_date(t.chore_id, (t.due_at at time zone tz)::date);
    if next_due is null then raise exception 'could not find a later date for this chore''s schedule'; end if;
    update chore_turns set due_at = (next_due + make_interval(hours => c.due_hour)) at time zone tz
     where id = p_turn
    returning * into t;
  else
    update chore_turns set due_at = null where id = p_turn returning * into t;
  end if;

  insert into chore_advance_log (chore_id, profile_id, kind, turn_id)
  values (t.chore_id, me, 'defer', p_turn);

  insert into activity_log (household_id, actor_id, verb, summary, metadata)
  select t.household_id, me, 'deferred_chore', p.full_name || ' pushed back ' || c.name,
         jsonb_build_object('chore_id', c.id, 'turn_id', t.id, 'emoji', c.emoji)
  from profiles p where p.id = me;

  return t;
end;
$$;


/**************************************************************************
 * 0024_geofence.sql
 *************************************************************************/

-- Optional, admin-configurable, off by default: require a member-device
-- completion to happen within a radius of the house. Kiosk completions are
-- exempt — the kiosk is physically fixed at the household's location, so a
-- distance check there is meaningless, and kiosk_complete_turn is a fully
-- separate RPC (locked to service_role since 0015) that this migration does
-- not touch. Only complete_turn is gated: skip/pass/undo aren't a presence
-- claim about doing the chore right now, so they're untouched too.
--
-- Privacy: raw lat/lon are transient RPC arguments only, never persisted —
-- chore_turns stores just a rounded distance and a boolean. This app is
-- newly open-source; precise per-completion location history would be a new,
-- unjustified PII category for what is only ever a yes/no distance check.

alter table households
  add column if not exists geofence_enabled boolean not null default false,
  add column if not exists geofence_radius_meters integer not null default 150
    check (geofence_radius_meters between 20 and 2000);

alter table chore_turns
  add column if not exists completion_distance_m integer,
  add column if not exists completion_within_geofence boolean;

/* --------------------------------------------------------------- helpers */

create or replace function haversine_meters(
  lat1 double precision, lon1 double precision,
  lat2 double precision, lon2 double precision
)
returns double precision
language sql
immutable
as $$
  select 6371000 * 2 * asin(least(1, sqrt(
    sin(radians(lat2 - lat1) / 2) ^ 2
    + cos(radians(lat1)) * cos(radians(lat2)) * sin(radians(lon2 - lon1) / 2) ^ 2
  )));
$$;

-- Refuses to enable until the household has a location set — enabling with
-- nothing to measure from would otherwise either always pass or always fail.
create or replace function set_geofence(p_enabled boolean, p_radius_meters integer default null)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  hh  uuid;
  lat double precision;
  lon double precision;
begin
  if not is_household_admin() then
    raise exception 'only an admin can change this';
  end if;
  select household_id into hh from profiles where id = auth.uid();
  if hh is null then raise exception 'you are not in a household'; end if;

  if p_enabled then
    select latitude, longitude into lat, lon from households where id = hh;
    if lat is null or lon is null then
      raise exception 'set a household location first — Settings → Household → Location';
    end if;
  end if;

  update households
     set geofence_enabled = p_enabled,
         geofence_radius_meters = coalesce(p_radius_meters, geofence_radius_meters)
   where id = hh;
end;
$$;

/* ---------------------------------------------------- complete_turn (again) */

-- Adds optional p_lat/p_lon. Cannot `create or replace` a new parameter onto
-- an existing signature — drop the prior one first.
drop function if exists complete_turn(uuid, text);

create or replace function complete_turn(
  p_turn uuid,
  p_note text default null,
  p_lat  double precision default null,
  p_lon  double precision default null
)
returns chore_turns
language plpgsql
security definer
set search_path = public
as $$
declare
  t           chore_turns%rowtype;
  c           chores%rowtype;
  hh          households%rowtype;
  me          uuid := auth.uid();
  dist        double precision;
  within_geo  boolean;
begin
  select * into t from chore_turns where id = p_turn for update;
  if not found then
    raise exception 'turn not found';
  end if;
  if not is_household_member(t.household_id) then
    raise exception 'not your household';
  end if;
  if t.status = 'done' then
    return t;
  end if;

  select * into hh from households where id = t.household_id;

  if me is distinct from t.assignee_id then
    if not coalesce(hh.allow_member_cross_complete, false) then
      raise exception 'only the assigned member can complete this — an admin can let anyone complete anyone''s chores in Settings';
    end if;
  end if;

  -- Fails closed: enabled + missing coordinates is treated the same as
  -- enabled + out of range, rather than silently skipping the check.
  if hh.geofence_enabled then
    if p_lat is null or p_lon is null then
      raise exception 'turn on location to complete chores for this house';
    end if;
    dist := haversine_meters(p_lat, p_lon, hh.latitude, hh.longitude);
    within_geo := dist <= hh.geofence_radius_meters;
    if not within_geo then
      raise exception 'you''re about % m from the house — get within % m to mark this done',
        round(dist)::int, hh.geofence_radius_meters;
    end if;
  end if;

  update chore_turns
     set status = 'done', completed_at = now(), completed_by = coalesce(me, t.assignee_id), note = p_note,
         flagged_for = null, flagged_by = null, flagged_at = null, flag_note = null,
         completion_distance_m = case when hh.geofence_enabled then round(dist)::int else null end,
         completion_within_geofence = case when hh.geofence_enabled then within_geo else null end
   where id = p_turn
  returning * into t;

  select * into c from chores where id = t.chore_id;

  if c.cadence = 'scheduled' then
    perform materialize_schedule(t.chore_id);
  else
    perform top_up_queue(t.chore_id);
  end if;

  insert into activity_log (household_id, actor_id, verb, summary, metadata)
  select t.household_id, coalesce(me, t.assignee_id), 'completed_chore',
         p.full_name || ' did ' || c.name,
         jsonb_build_object('chore_id', c.id, 'turn_id', t.id, 'emoji', c.emoji)
  from profiles p where p.id = coalesce(me, t.assignee_id);

  return t;
end;
$$;


/**************************************************************************
 * 0025_platform_admin_identity.sql
 *************************************************************************/

-- Platform-admin identity: scaffolding for the operator (Tejas) to see
-- cross-household aggregates once other households actually use this
-- open-sourced app — today there is exactly one real household.
--
-- Two independent locks, not a `platform_admins` table:
--   * a Postgres GUC (app.platform_admin_emails), set once per deployment
--     via `alter database ... set ...` — this is the real authorization
--     boundary, since a security-definer RPC bypasses RLS entirely once
--     inside it, so it needs its own check independent of anything Next.js
--     does. See src/lib/platform-admin.ts for the matching Next.js-side gate
--     (route visibility only, not authorization) and .env.local.example for
--     the paired PLATFORM_ADMIN_EMAILS env var.
-- A DB table was considered and rejected: it's new writable schema (RLS,
-- seeding) for a problem an env var + GUC solves with zero schema footprint.
-- Passing an allowlist as an RPC argument was also rejected: it's spoofable
-- — nothing stops a caller passing their own email as "the allowlist".
--
-- If the GUC is never set (a fresh self-hosted deployment), this returns
-- false for everyone — safe by default, nothing to misconfigure into an
-- accidental opening.

create or replace function is_platform_admin()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select coalesce(
    (select lower(email) from profiles where id = auth.uid())
      = any (string_to_array(lower(coalesce(current_setting('app.platform_admin_emails', true), '')), ',')),
    false
  );
$$;

/* ------------------------------------------------------------ signup source */

-- Honest, minimal "join source": captured only when a household is created
-- (its origin), not when someone redeems an invite to join an existing one —
-- that's always "invited by a housemate," a fixed bucket needing no column.
-- No IP capture, no IP geolocation, no user-agent logging anywhere in this
-- app — the highest-regret PII categories to ship by default in code other
-- people now self-host for their own families.

alter table households add column if not exists signup_source text
  check (signup_source is null or signup_source ~ '^[a-z0-9_-]{1,40}$');

-- Cannot `create or replace` a new parameter onto an existing signature —
-- drop the 0005 six-argument version first.
drop function if exists create_household(text, text, text, text, text, text[]);

create or replace function create_household(
  p_name          text,
  p_address       text default null,
  p_timezone      text default 'America/Detroit',
  p_full_name     text default null,
  p_initials      text default null,
  p_modules       text[] default null,
  p_signup_source text default null
)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  me       uuid := auth.uid();
  new_id   uuid;
  chore_id uuid;
  existing uuid;
  wanted   text[] := coalesce(p_modules, default_modules());
begin
  if me is null then
    raise exception 'not signed in';
  end if;

  select household_id into existing from profiles where id = me;
  if existing is not null then
    raise exception 'you are already in a household';
  end if;

  insert into households (name, address, timezone, signup_source)
  values (
    trim(p_name), nullif(trim(coalesce(p_address, '')), ''), p_timezone,
    nullif(trim(coalesce(p_signup_source, '')), '')
  )
  returning id into new_id;

  update profiles
     set household_id = new_id,
         is_admin     = true,
         full_name    = coalesce(nullif(trim(coalesce(p_full_name, '')), ''), full_name),
         initials     = coalesce(nullif(upper(trim(coalesce(p_initials, ''))), ''), initials)
   where id = me;

  insert into household_modules (household_id, module, enabled, updated_by)
  select new_id, d, d = any (wanted), me
  from unnest(default_modules()) d;

  insert into household_modules (household_id, module, enabled, updated_by)
  select new_id, w, true, me
  from unnest(wanted) w
  where not (w = any (default_modules()))
  on conflict do nothing;

  if 'chores' = any (wanted) then
    for chore_id in
      insert into chores (household_id, name, emoji, description, cadence,
                          days_of_week, interval_weeks, due_hour, queue_depth, sort_order)
      values
        (new_id, 'Floors', '🧹', 'Sweep and mop the common areas', 'scheduled', '{0,5}', 1, 20, 4, 1),
        (new_id, 'Microwave', '🍲', 'Wipe out the microwave', 'scheduled', '{6}', 2, 20, 4, 2),
        (new_id, 'Trash to curb', '🗑️', 'Bins out the night before pickup', 'scheduled', '{0}', 1, 19, 4, 3),
        (new_id, 'Dishes', '🍽️', 'Run and unload a load', 'on_demand', '{}', 1, 20, 4, 4),
        (new_id, 'Trash when full', '🚮', 'Swap the kitchen bag', 'on_demand', '{}', 1, 20, 4, 5)
      returning id
    loop
      insert into chore_rotation (chore_id, profile_id, position) values (chore_id, me, 0);
    end loop;

    for chore_id in select id from chores where household_id = new_id loop
      if (select cadence from chores where id = chore_id) = 'scheduled' then
        perform materialize_schedule(chore_id);
      else
        perform top_up_queue(chore_id);
      end if;
    end loop;
  end if;

  insert into activity_log (household_id, actor_id, verb, summary)
  values (new_id, me, 'created_household',
          (select full_name from profiles where id = me) || ' started the house');

  return new_id;
end;
$$;


/**************************************************************************
 * 0026_feedback.sql
 *************************************************************************/

-- A lightweight in-app way to report a bug or request a feature. No RLS
-- policy at all — same pattern as household_ai_config (0011): every access
-- goes through a security-definer function (submit_feedback here to write,
-- platform_feedback in 0027 to read), so nobody, including a household's own
-- admin, can query this table directly.

create table if not exists feedback_submissions (
  id           uuid primary key default gen_random_uuid(),
  household_id uuid references households(id) on delete set null,
  profile_id   uuid references profiles(id) on delete set null,
  kind         text not null check (kind in ('bug', 'feature')),
  body         text not null check (char_length(trim(body)) between 1 and 4000),
  metadata     jsonb not null default '{}',
  created_at   timestamptz not null default now()
);

alter table feedback_submissions enable row level security;

-- household_id/profile_id are stamped from auth.uid() server-side, never
-- trusted from the client, so nobody can spoof a submission as coming from
-- another household. household_id is nullable so someone hitting a bug
-- before finishing onboarding can still report it.
create or replace function submit_feedback(p_kind text, p_body text, p_metadata jsonb default '{}')
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  me     uuid := auth.uid();
  hh     uuid;
  new_id uuid;
begin
  if me is null then raise exception 'not signed in'; end if;
  if p_kind not in ('bug', 'feature') then raise exception 'unknown feedback kind'; end if;
  if coalesce(trim(p_body), '') = '' then raise exception 'say a little about what happened'; end if;

  select household_id into hh from profiles where id = me;

  insert into feedback_submissions (household_id, profile_id, kind, body, metadata)
  values (hh, me, p_kind, trim(p_body), coalesce(p_metadata, '{}'::jsonb))
  returning id into new_id;

  return new_id;
end;
$$;


/**************************************************************************
 * 0027_platform_stats.sql
 *************************************************************************/

-- Read-only, aggregate-only cross-household stats for the platform-admin
-- page (src/app/platform-admin) — derived from data that already exists
-- rather than a new telemetry pipeline. No raw per-user rows anywhere here
-- except platform_feedback, which is a deliberate, narrow exception: replying
-- to a bug report requires knowing who filed it.
--
-- Every function opens with an is_platform_admin() check — this is the real
-- authorization boundary (see 0025), not the Next.js route gate.

create or replace function platform_stats()
returns table (
  households_total            integer,
  households_last_30d         integer,
  members_total                integer,
  members_last_30d            integer,
  admins_total                 integer,
  module_enabled_counts        jsonb,
  turns_completed_last_7d      integer,
  turns_completed_last_30d     integer,
  turns_skipped_last_30d       integer,
  cross_complete_enabled_count integer,
  geofence_enabled_count       integer,
  signup_source_counts         jsonb,
  feedback_total                integer,
  feedback_last_30d            integer
)
language plpgsql
stable
security definer
set search_path = public
as $$
begin
  if not is_platform_admin() then raise exception 'not authorized'; end if;

  return query select
    (select count(*)::int from households),
    (select count(*)::int from households where created_at > now() - interval '30 days'),
    (select count(*)::int from profiles where household_id is not null),
    (select count(*)::int from profiles where household_id is not null and created_at > now() - interval '30 days'),
    (select count(*)::int from profiles where is_admin),
    (select coalesce(jsonb_object_agg(module, cnt), '{}'::jsonb)
       from (select module, count(*) cnt from household_modules where enabled group by module) s),
    (select count(*)::int from chore_turns where status = 'done' and completed_at > now() - interval '7 days'),
    (select count(*)::int from chore_turns where status = 'done' and completed_at > now() - interval '30 days'),
    (select count(*)::int from chore_turns where status = 'skipped' and completed_at > now() - interval '30 days'),
    (select count(*)::int from households where allow_member_cross_complete),
    (select count(*)::int from households where geofence_enabled),
    (select coalesce(jsonb_object_agg(coalesce(signup_source, '(direct)'), cnt), '{}'::jsonb)
       from (select signup_source, count(*) cnt from households group by signup_source) s),
    (select count(*)::int from feedback_submissions),
    (select count(*)::int from feedback_submissions where created_at > now() - interval '30 days');
end;
$$;

-- Deliberately excludes name/address/location/timezone — no product reason
-- for a platform operator to see per-resident identifying details in
-- aggregate, only the shape of how each household is configured.
create or replace function platform_households_summary(p_limit integer default 200)
returns table (
  id                           uuid,
  created_at                   timestamptz,
  member_count                 integer,
  modules_enabled              text[],
  allow_member_cross_complete  boolean,
  geofence_enabled             boolean,
  signup_source                text
)
language plpgsql
stable
security definer
set search_path = public
as $$
begin
  if not is_platform_admin() then raise exception 'not authorized'; end if;

  return query
    select h.id, h.created_at,
           (select count(*)::int from profiles p where p.household_id = h.id),
           enabled_modules(h.id), h.allow_member_cross_complete, h.geofence_enabled, h.signup_source
    from households h
    order by h.created_at desc
    limit greatest(1, least(p_limit, 1000));
end;
$$;

create or replace function platform_feedback(p_limit integer default 100)
returns table (
  id             uuid,
  household_name text,
  submitter_name text,
  kind           text,
  body           text,
  metadata       jsonb,
  created_at     timestamptz
)
language plpgsql
stable
security definer
set search_path = public
as $$
begin
  if not is_platform_admin() then raise exception 'not authorized'; end if;

  return query
    select f.id, h.name, p.full_name, f.kind, f.body, f.metadata, f.created_at
    from feedback_submissions f
    left join households h on h.id = f.household_id
    left join profiles p on p.id = f.profile_id
    order by f.created_at desc
    limit greatest(1, least(p_limit, 500));
end;
$$;


/**************************************************************************
 * 0028_standing_chore_flag.sql
 *************************************************************************/

-- Course correction on 0022_turn_flags.sql: that migration built a whole
-- parallel per-person "nudge" system (flagged_for/flagged_by/flag_note,
-- flag_turn/clear_flag) for standing chores. The actual ask was simpler —
-- reuse the existing chore-wide flag mechanism (flag_on_demand /
-- kiosk_flag_chore, the "dishwasher's full" button) for standing chores too,
-- not build a second one. A standing chore always has exactly one pending
-- turn already visible, so flagging it has nothing to "reveal" the way
-- stamping due_at does for on_demand — it should instead just mark the
-- turn as flagged (for a shared, whole-house visible badge) and let the
-- caller notify/emphasize from there. flagged_at survives from 0022 for
-- exactly this; the per-person columns and RPCs it also added do not.

drop function if exists flag_turn(uuid, uuid, text);
drop function if exists clear_flag(uuid);

alter table chore_turns
  drop column if exists flagged_for,
  drop column if exists flagged_by,
  drop column if exists flag_note;

/* --------------------------------------------------- flag_on_demand (again) */

-- on_demand keeps stamping due_at=now() (unchanged, exact original
-- behavior/quirk: returns the turn as fetched before the update, same as
-- 0002/0012 — nothing downstream reads due_at off this return value).
-- standing has no due_at to stamp — flagged_at is the equivalent signal, and
-- unlike due_at it is never cleared on completion, since a standing chore's
-- resolution always creates a fresh turn (flagged_at null) rather than
-- reusing the flagged one.
create or replace function flag_on_demand(p_chore uuid)
returns chore_turns
language plpgsql
security definer
set search_path = public
as $$
declare
  t chore_turns%rowtype;
  c chores%rowtype;
begin
  select * into c from chores where id = p_chore;
  if not is_household_member(c.household_id) then
    raise exception 'not your household';
  end if;
  if c.cadence not in ('on_demand', 'standing') then
    raise exception 'this chore cannot be flagged';
  end if;

  perform top_up_queue(p_chore);

  select * into t from chore_turns
   where chore_id = p_chore and status = 'pending'
   order by turn_number limit 1;

  if c.cadence = 'on_demand' then
    update chore_turns set due_at = now() where id = t.id and due_at is null;
  else
    update chore_turns set flagged_at = now() where id = t.id and flagged_at is null;
  end if;

  insert into activity_log (household_id, actor_id, verb, summary, metadata)
  select c.household_id, auth.uid(), 'flagged_chore',
         c.name || ' needs doing',
         jsonb_build_object('chore_id', c.id, 'turn_id', t.id, 'emoji', c.emoji);

  return t;
end;
$$;

create or replace function kiosk_flag_chore(
  p_household uuid,
  p_chore     uuid,
  p_profile   uuid
)
returns chore_turns
language plpgsql
security definer
set search_path = public
as $$
declare
  t chore_turns%rowtype;
  c chores%rowtype;
begin
  if not exists (select 1 from profiles where id = p_profile and household_id = p_household) then
    raise exception 'not a member of this household';
  end if;

  select * into c from chores where id = p_chore and household_id = p_household;
  if not found then raise exception 'chore not found'; end if;
  if c.cadence not in ('on_demand', 'standing') then
    raise exception 'this chore cannot be flagged';
  end if;

  perform top_up_queue(p_chore);

  select * into t from chore_turns
   where chore_id = p_chore and status = 'pending'
   order by turn_number limit 1;

  if c.cadence = 'on_demand' then
    update chore_turns set due_at = now() where id = t.id and due_at is null;
  else
    update chore_turns set flagged_at = now() where id = t.id and flagged_at is null;
  end if;

  insert into activity_log (household_id, actor_id, verb, summary, metadata)
  select c.household_id, p_profile, 'flagged_chore',
         c.name || ' needs doing',
         jsonb_build_object('chore_id', c.id, 'turn_id', t.id, 'emoji', c.emoji);

  return t;
end;
$$;

/* -------------------------------------------- drop the removed columns' refs */

-- Same bodies as 0024 (complete_turn) / 0022 (skip_turn, kiosk_complete_turn),
-- minus the flagged_for/flagged_by/flag_note clearing — those columns are
-- gone. flagged_at is deliberately left alone on completion/skip: the row
-- becomes history either way, and the next turn a top-up creates starts
-- fresh with flagged_at null, so nothing needs to null it out here.

create or replace function complete_turn(
  p_turn uuid,
  p_note text default null,
  p_lat  double precision default null,
  p_lon  double precision default null
)
returns chore_turns
language plpgsql
security definer
set search_path = public
as $$
declare
  t           chore_turns%rowtype;
  c           chores%rowtype;
  hh          households%rowtype;
  me          uuid := auth.uid();
  dist        double precision;
  within_geo  boolean;
begin
  select * into t from chore_turns where id = p_turn for update;
  if not found then
    raise exception 'turn not found';
  end if;
  if not is_household_member(t.household_id) then
    raise exception 'not your household';
  end if;
  if t.status = 'done' then
    return t;
  end if;

  select * into hh from households where id = t.household_id;

  if me is distinct from t.assignee_id then
    if not coalesce(hh.allow_member_cross_complete, false) then
      raise exception 'only the assigned member can complete this — an admin can let anyone complete anyone''s chores in Settings';
    end if;
  end if;

  if hh.geofence_enabled then
    if p_lat is null or p_lon is null then
      raise exception 'turn on location to complete chores for this house';
    end if;
    dist := haversine_meters(p_lat, p_lon, hh.latitude, hh.longitude);
    within_geo := dist <= hh.geofence_radius_meters;
    if not within_geo then
      raise exception 'you''re about % m from the house — get within % m to mark this done',
        round(dist)::int, hh.geofence_radius_meters;
    end if;
  end if;

  update chore_turns
     set status = 'done', completed_at = now(), completed_by = coalesce(me, t.assignee_id), note = p_note,
         completion_distance_m = case when hh.geofence_enabled then round(dist)::int else null end,
         completion_within_geofence = case when hh.geofence_enabled then within_geo else null end
   where id = p_turn
  returning * into t;

  select * into c from chores where id = t.chore_id;

  if c.cadence = 'scheduled' then
    perform materialize_schedule(t.chore_id);
  else
    perform top_up_queue(t.chore_id);
  end if;

  insert into activity_log (household_id, actor_id, verb, summary, metadata)
  select t.household_id, coalesce(me, t.assignee_id), 'completed_chore',
         p.full_name || ' did ' || c.name,
         jsonb_build_object('chore_id', c.id, 'turn_id', t.id, 'emoji', c.emoji)
  from profiles p where p.id = coalesce(me, t.assignee_id);

  return t;
end;
$$;

create or replace function kiosk_complete_turn(
  p_household uuid,
  p_turn      uuid,
  p_profile   uuid,
  p_note      text default null
)
returns chore_turns
language plpgsql
security definer
set search_path = public
as $$
declare
  t chore_turns%rowtype;
  c chores%rowtype;
begin
  if not exists (select 1 from profiles where id = p_profile and household_id = p_household) then
    raise exception 'not a member of this household';
  end if;

  select * into t from chore_turns where id = p_turn and household_id = p_household for update;
  if not found then raise exception 'turn not found'; end if;
  if t.status = 'done' then return t; end if;

  update chore_turns
     set status = 'done', completed_at = now(), completed_by = p_profile, note = p_note
   where id = p_turn
  returning * into t;

  select * into c from chores where id = t.chore_id;

  if c.cadence = 'scheduled' then
    perform materialize_schedule(t.chore_id);
  else
    perform top_up_queue(t.chore_id);
  end if;

  insert into activity_log (household_id, actor_id, verb, summary, metadata)
  select t.household_id, p_profile, 'completed_chore',
         p.full_name || ' did ' || c.name,
         jsonb_build_object('chore_id', c.id, 'turn_id', t.id, 'emoji', c.emoji)
  from profiles p where p.id = p_profile;

  return t;
end;
$$;

create or replace function skip_turn(p_turn uuid, p_note text default null)
returns chore_turns
language plpgsql
security definer
set search_path = public
as $$
declare
  t           chore_turns%rowtype;
  c           chores%rowtype;
  me          uuid := auth.uid();
  allow_cross boolean;
begin
  select * into t from chore_turns where id = p_turn for update;
  if not found then
    raise exception 'turn not found';
  end if;
  if not is_household_member(t.household_id) then
    raise exception 'not your household';
  end if;
  if t.status <> 'pending' then
    raise exception 'that turn is not pending';
  end if;

  if me is distinct from t.assignee_id then
    select allow_member_cross_complete into allow_cross
    from households where id = t.household_id;
    if not coalesce(allow_cross, false) then
      raise exception 'only the assigned member can skip this — an admin can let anyone act for anyone in Settings';
    end if;
  end if;

  update chore_turns
     set status = 'skipped', completed_at = now(), completed_by = me, note = p_note
   where id = p_turn
  returning * into t;

  select * into c from chores where id = t.chore_id;

  if c.cadence = 'scheduled' then
    perform materialize_schedule(t.chore_id);
  else
    perform top_up_queue(t.chore_id);
  end if;

  insert into activity_log (household_id, actor_id, verb, summary, metadata)
  select t.household_id, me,
         'skipped_chore',
         case when me is distinct from t.assignee_id
              then p.full_name || ' skipped ' || c.name || ' for ' || a.full_name
              else p.full_name || ' skipped ' || c.name
         end,
         jsonb_build_object('chore_id', c.id, 'turn_id', t.id, 'emoji', c.emoji)
  from profiles p
  join profiles a on a.id = t.assignee_id
  where p.id = coalesce(me, t.assignee_id);

  return t;
end;
$$;


/**************************************************************************
 * 0029_swap_get_ahead_defer.sql
 *************************************************************************/

-- Second course-correction: get_ahead/defer_turn (0023) completed a turn
-- early / pushed a due date. The actual ask is a queue-position swap that
-- never completes anything: get_ahead trades your own upcoming turn for
-- whoever currently holds the chore (you take their current turn, they take
-- your future one); defer is the mirror — you hand your current turn to the
-- next person in line and take their future one instead. Neither one is
-- reachable twice in a row on the same chore without something else
-- happening in between: once you hold the current turn, get_ahead's own
-- "it's already your turn" guard blocks a repeat, which is what makes the
-- old "how many turns ahead" cap unnecessary — a plain rolling-30-day use
-- count per direction is enough.
--
-- Same signatures as 0023 (get_ahead(uuid), defer_turn(uuid)), so this is a
-- plain create-or-replace, no drop needed.

/* -------------------------------------------------------------- helpers */

-- Finds profile p_profile's next turn on this chore beyond p_after_turn_number
-- — an already-pending one if it exists, otherwise walks forward
-- (materializing as it goes, same mechanism append_turn/materialize_schedule
-- already use) until it reaches one. Shared by both directions below: for
-- get_ahead the "someone else" is whoever currently holds the chore; for
-- defer it's the next person in the rotation.
create or replace function find_or_create_next_turn_for(
  p_chore uuid, p_profile uuid, p_after_turn_number integer
)
returns chore_turns
language plpgsql
security definer
set search_path = public
as $$
declare
  c          chores%rowtype;
  target     chore_turns%rowtype;
  tz         text;
  next_due   date;
  last_due   date;
  iterations int := 0;
  cap        constant int := 500;
begin
  select * into c from chores where id = p_chore;

  select * into target from chore_turns
   where chore_id = p_chore and status = 'pending' and assignee_id = p_profile
     and turn_number > p_after_turn_number
   order by turn_number limit 1;
  if found then
    return target;
  end if;

  if c.cadence = 'scheduled' then
    select timezone into tz from households where id = c.household_id;
    select coalesce(max((due_at at time zone tz)::date), c.anchor_date - 1) into last_due
      from chore_turns where chore_id = p_chore;
    loop
      iterations := iterations + 1;
      exit when iterations > cap;
      next_due := next_scheduled_date(p_chore, last_due);
      exit when next_due is null;
      target := append_turn(p_chore, (next_due + make_interval(hours => c.due_hour)) at time zone tz);
      last_due := next_due;
      exit when target.id is not null and target.assignee_id = p_profile;
    end loop;
  else
    loop
      iterations := iterations + 1;
      exit when iterations > cap;
      target := append_turn(p_chore, null);
      exit when target.id is null;
      exit when target.assignee_id = p_profile;
    end loop;
  end if;

  if target.id is null or target.assignee_id is distinct from p_profile then
    raise exception 'could not find an upcoming turn for that person';
  end if;

  return target;
end;
$$;

/* ------------------------------------------------------------- get_ahead */

create or replace function get_ahead(p_chore uuid)
returns chore_turns
language plpgsql
security definer
set search_path = public
as $$
declare
  me             uuid := auth.uid();
  c              chores%rowtype;
  current_turn   chore_turns%rowtype;
  my_turn        chore_turns%rowtype;
  current_holder uuid;
  mod_enabled    boolean;
  mod_settings   jsonb;
  max_per_30d    int;
  uses_30d       int;
begin
  select * into c from chores where id = p_chore;
  if not found then raise exception 'chore not found'; end if;
  if not is_household_member(c.household_id) then raise exception 'not your household'; end if;
  if c.cadence = 'standing' then
    raise exception 'get-ahead does not apply to standing chores — pass it on if you cannot get to it';
  end if;
  if not exists (select 1 from chore_rotation where chore_id = p_chore and profile_id = me) then
    raise exception 'you are not in this chore''s rotation';
  end if;

  select enabled, settings into mod_enabled, mod_settings
    from household_modules where household_id = c.household_id and module = 'get_ahead';
  if not coalesce(mod_enabled, true) then raise exception 'get-ahead is turned off for this house'; end if;
  max_per_30d := coalesce((coalesce(mod_settings, '{}'::jsonb) #>> '{get_ahead,max_per_30d}')::int, 1);

  select * into current_turn from chore_turns
   where chore_id = p_chore and status = 'pending'
   order by turn_number limit 1;
  if not found then raise exception 'nothing pending on this chore'; end if;

  current_holder := current_turn.assignee_id;
  if current_holder = me then
    raise exception 'it is already your turn';
  end if;

  select count(*) into uses_30d from chore_advance_log
   where chore_id = p_chore and profile_id = me and kind = 'get_ahead'
     and created_at > now() - interval '30 days';
  if uses_30d >= max_per_30d then
    raise exception 'You have used get-ahead % time(s) in the last 30 days — the house limit is %.', uses_30d, max_per_30d;
  end if;

  my_turn := find_or_create_next_turn_for(p_chore, me, current_turn.turn_number);

  update chore_turns set assignee_id = me where id = current_turn.id;
  update chore_turns set assignee_id = current_holder where id = my_turn.id;

  insert into chore_advance_log (chore_id, profile_id, kind, turn_id)
  values (p_chore, me, 'get_ahead', current_turn.id);

  insert into activity_log (household_id, actor_id, verb, summary, metadata)
  select c.household_id, me, 'got_ahead', p.full_name || ' got ahead on ' || c.name,
         jsonb_build_object('chore_id', c.id, 'turn_id', current_turn.id, 'emoji', c.emoji)
  from profiles p where p.id = me;

  select * into current_turn from chore_turns where id = current_turn.id;
  return current_turn;
end;
$$;

/* --------------------------------------------------------------- defer */

create or replace function defer_turn(p_turn uuid)
returns chore_turns
language plpgsql
security definer
set search_path = public
as $$
declare
  me          uuid := auth.uid();
  t           chore_turns%rowtype;
  c           chores%rowtype;
  next_person uuid;
  other_turn  chore_turns%rowtype;
  n           int;
  cur_pos     int;
  cand        uuid;
  mod_enabled boolean;
  mod_settings jsonb;
  max_per_30d int;
  uses_30d    int;
begin
  select * into t from chore_turns where id = p_turn for update;
  if not found then raise exception 'turn not found'; end if;
  if not is_household_member(t.household_id) then raise exception 'not your household'; end if;
  if t.status <> 'pending' then raise exception 'that turn is not pending'; end if;
  if me is distinct from t.assignee_id then raise exception 'you can only defer your own turn'; end if;

  select * into c from chores where id = t.chore_id;
  if c.cadence = 'standing' then
    raise exception 'defer does not apply to standing chores — pass it to the next person instead';
  end if;

  select enabled, settings into mod_enabled, mod_settings
    from household_modules where household_id = c.household_id and module = 'get_ahead';
  if not coalesce(mod_enabled, true) then raise exception 'get-ahead/defer is turned off for this house'; end if;
  max_per_30d := coalesce((coalesce(mod_settings, '{}'::jsonb) #>> '{defer,max_per_30d}')::int, 1);

  select count(*) into uses_30d from chore_advance_log
   where chore_id = t.chore_id and profile_id = me and kind = 'defer'
     and created_at > now() - interval '30 days';
  if uses_30d >= max_per_30d then
    raise exception 'You have deferred % time(s) in the last 30 days — the house limit is %.', uses_30d, max_per_30d;
  end if;

  select count(*) into n from chore_rotation where chore_id = t.chore_id;
  if n <= 1 then raise exception 'no one else in the rotation to defer to'; end if;

  select position into cur_pos from chore_rotation where chore_id = t.chore_id and profile_id = me;
  if cur_pos is null then raise exception 'you are not in this chore''s rotation'; end if;

  next_person := null;
  for i in 1..n - 1 loop
    select profile_id into cand from chore_rotation
     where chore_id = t.chore_id and position = (cur_pos + i) % n;
    if not is_away_at(cand, coalesce(t.due_at, now())) then
      next_person := cand;
      exit;
    end if;
  end loop;

  if next_person is null then
    raise exception 'everyone else is away — pass or skip instead';
  end if;

  other_turn := find_or_create_next_turn_for(t.chore_id, next_person, t.turn_number);

  update chore_turns set assignee_id = next_person where id = t.id;
  update chore_turns set assignee_id = me where id = other_turn.id;

  insert into chore_advance_log (chore_id, profile_id, kind, turn_id)
  values (t.chore_id, me, 'defer', t.id);

  insert into activity_log (household_id, actor_id, verb, summary, metadata)
  select t.household_id, me, 'deferred_chore', p.full_name || ' pushed back ' || c.name,
         jsonb_build_object('chore_id', c.id, 'turn_id', t.id, 'emoji', c.emoji)
  from profiles p where p.id = me;

  select * into t from chore_turns where id = t.id;
  return t;
end;
$$;


/**************************************************************************
 * 0030_platform_admin_table.sql
 *************************************************************************/

-- Fourth course-correction: 0025's is_platform_admin() relied on a Postgres
-- GUC set via `alter database ... set app.platform_admin_emails = '...'`.
-- Confirmed against the real project: Supabase's managed Postgres refuses
-- that statement outright ("permission denied to set parameter") for every
-- role available to a project owner, including the SQL Editor's — not a
-- permissions oversight on our end, a platform-wide restriction. The GUC
-- design cannot work here at all, on this project or anyone else's.
--
-- Replacement: a one-row, zero-RLS-policy table (same locked-down pattern as
-- household_ai_config/feedback_submissions), writable only by a
-- service-role-only RPC — bootstrapped by running a small local script with
-- the service role key every deployment already has
-- (scripts/set-platform-admin.mjs), the same way this repo already asks you
-- to run `npm run gen:secrets`/`npm run gen:vapid` once per deployment.

create table if not exists platform_config (
  id           boolean primary key default true check (id),
  admin_emails text[]  not null default '{}'
);

insert into platform_config (id) values (true) on conflict do nothing;

alter table platform_config enable row level security;
-- No policies at all — every read goes through is_platform_admin() below,
-- every write through set_platform_admin_emails(), never a direct query.

create or replace function is_platform_admin()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select coalesce(
    (select lower(email) from profiles where id = auth.uid())
      = any (select lower(e) from platform_config, unnest(admin_emails) as e where id = true),
    false
  );
$$;

-- service_role only — the same lockdown shape 0015 uses for the kiosk RPCs.
-- Never callable by a signed-in member: this is exactly the allowlist that
-- decides who can act as a platform operator, so it must not be settable by
-- anyone the RPC itself would call a platform admin.
create or replace function set_platform_admin_emails(p_emails text[])
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  update platform_config
     set admin_emails = (select coalesce(array_agg(lower(trim(e))), '{}') from unnest(p_emails) e where trim(e) <> '')
   where id = true;
end;
$$;

do $$
declare r text;
begin
  foreach r in array array['authenticated', 'anon', 'domestic_app'] loop
    if exists (select 1 from pg_roles where rolname = r) then
      execute format('revoke execute on function set_platform_admin_emails(text[]) from %I', r);
    end if;
  end loop;

  if exists (select 1 from pg_roles where rolname = 'service_role') then
    grant execute on function set_platform_admin_emails(text[]) to service_role;
  end if;
end $$;

revoke execute on function set_platform_admin_emails(text[]) from public;


/**************************************************************************
 * 0031_geofence_house_address.sql
 *************************************************************************/

-- The "require members to be nearby" geofence was centered on
-- households.latitude/longitude — the kiosk's optional wall-display weather
-- override — so an admin had to configure that override just to turn the
-- geofence on, even for a house that already has an address on file. Give
-- the geofence its own coordinates, geocoded from households.address, so it
-- no longer depends on the kiosk override being set.
--
-- Postgres can't call the geocoder itself, so the app layer resolves
-- address -> lat/lon (via the same Open-Meteo geocoder the kiosk weather
-- fallback already uses, see src/lib/weather.ts geocodeHouseAddress) and
-- passes it through set_geofence, which persists it here.

alter table households
  add column if not exists house_latitude double precision,
  add column if not exists house_longitude double precision;

-- Households that already had geofencing on were relying on the kiosk
-- override as their center — carry that over so this migration doesn't
-- silently turn a working geofence into one that always fails.
update households
   set house_latitude = latitude,
       house_longitude = longitude
 where geofence_enabled and house_latitude is null;

/* --------------------------------------------------------------- set_geofence */

-- Adds optional p_lat/p_lon so the app can supply freshly-geocoded house
-- coordinates in the same call that turns geofencing on.
drop function if exists set_geofence(boolean, integer);

create or replace function set_geofence(
  p_enabled       boolean,
  p_radius_meters integer default null,
  p_lat           double precision default null,
  p_lon           double precision default null
)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  hh  uuid;
  lat double precision;
  lon double precision;
begin
  if not is_household_admin() then
    raise exception 'only an admin can change this';
  end if;
  select household_id into hh from profiles where id = auth.uid();
  if hh is null then raise exception 'you are not in a household'; end if;

  select house_latitude, house_longitude into lat, lon from households where id = hh;

  if p_enabled and (coalesce(p_lat, lat) is null or coalesce(p_lon, lon) is null) then
    raise exception 'set a house address first — Settings → Household';
  end if;

  update households
     set geofence_enabled = p_enabled,
         geofence_radius_meters = coalesce(p_radius_meters, geofence_radius_meters),
         house_latitude = coalesce(p_lat, house_latitude),
         house_longitude = coalesce(p_lon, house_longitude)
   where id = hh;
end;
$$;

/* ---------------------------------------------------- complete_turn (again) */

-- Same body as 0028's complete_turn, just measuring against house_latitude/
-- house_longitude instead of the kiosk override's latitude/longitude.
drop function if exists complete_turn(uuid, text, double precision, double precision);

create or replace function complete_turn(
  p_turn uuid,
  p_note text default null,
  p_lat  double precision default null,
  p_lon  double precision default null
)
returns chore_turns
language plpgsql
security definer
set search_path = public
as $$
declare
  t           chore_turns%rowtype;
  c           chores%rowtype;
  hh          households%rowtype;
  me          uuid := auth.uid();
  dist        double precision;
  within_geo  boolean;
begin
  select * into t from chore_turns where id = p_turn for update;
  if not found then
    raise exception 'turn not found';
  end if;
  if not is_household_member(t.household_id) then
    raise exception 'not your household';
  end if;
  if t.status = 'done' then
    return t;
  end if;

  select * into hh from households where id = t.household_id;

  if me is distinct from t.assignee_id then
    if not coalesce(hh.allow_member_cross_complete, false) then
      raise exception 'only the assigned member can complete this — an admin can let anyone complete anyone''s chores in Settings';
    end if;
  end if;

  if hh.geofence_enabled then
    if p_lat is null or p_lon is null then
      raise exception 'turn on location to complete chores for this house';
    end if;
    dist := haversine_meters(p_lat, p_lon, hh.house_latitude, hh.house_longitude);
    within_geo := dist <= hh.geofence_radius_meters;
    if not within_geo then
      raise exception 'you''re about % m from the house — get within % m to mark this done',
        round(dist)::int, hh.geofence_radius_meters;
    end if;
  end if;

  update chore_turns
     set status = 'done', completed_at = now(), completed_by = coalesce(me, t.assignee_id), note = p_note,
         completion_distance_m = case when hh.geofence_enabled then round(dist)::int else null end,
         completion_within_geofence = case when hh.geofence_enabled then within_geo else null end
   where id = p_turn
  returning * into t;

  select * into c from chores where id = t.chore_id;

  if c.cadence = 'scheduled' then
    perform materialize_schedule(t.chore_id);
  else
    perform top_up_queue(t.chore_id);
  end if;

  insert into activity_log (household_id, actor_id, verb, summary, metadata)
  select t.household_id, coalesce(me, t.assignee_id), 'completed_chore',
         p.full_name || ' did ' || c.name,
         jsonb_build_object('chore_id', c.id, 'turn_id', t.id, 'emoji', c.emoji)
  from profiles p where p.id = coalesce(me, t.assignee_id);

  return t;
end;
$$;


/**************************************************************************
 * 0032_credit_assignee_in_activity_log.sql
 *************************************************************************/

-- complete_turn/kiosk_complete_turn logged the *actor* as having done the
-- chore ("X did Y"), even when completing on someone else's behalf via
-- allow_member_cross_complete (or the kiosk, which has always let anyone
-- complete anyone's turn — it never checked that setting). The activity
-- feed should credit whoever the turn actually belonged to, not whoever
-- happened to tap the button. `completed_by` (the real audit column) is
-- untouched — it keeps recording the true actor either way; only the
-- feed's actor_id/summary changes.
--
-- Built on top of 0031's complete_turn (house_latitude/house_longitude,
-- not the old kiosk-override latitude/longitude) — same signature, so
-- plain create-or-replace, no drop needed.

create or replace function complete_turn(
  p_turn uuid,
  p_note text default null,
  p_lat  double precision default null,
  p_lon  double precision default null
)
returns chore_turns
language plpgsql
security definer
set search_path = public
as $$
declare
  t           chore_turns%rowtype;
  c           chores%rowtype;
  hh          households%rowtype;
  me          uuid := auth.uid();
  dist        double precision;
  within_geo  boolean;
begin
  select * into t from chore_turns where id = p_turn for update;
  if not found then
    raise exception 'turn not found';
  end if;
  if not is_household_member(t.household_id) then
    raise exception 'not your household';
  end if;
  if t.status = 'done' then
    return t;
  end if;

  select * into hh from households where id = t.household_id;

  if me is distinct from t.assignee_id then
    if not coalesce(hh.allow_member_cross_complete, false) then
      raise exception 'only the assigned member can complete this — an admin can let anyone complete anyone''s chores in Settings';
    end if;
  end if;

  if hh.geofence_enabled then
    if p_lat is null or p_lon is null then
      raise exception 'turn on location to complete chores for this house';
    end if;
    dist := haversine_meters(p_lat, p_lon, hh.house_latitude, hh.house_longitude);
    within_geo := dist <= hh.geofence_radius_meters;
    if not within_geo then
      raise exception 'you''re about % m from the house — get within % m to mark this done',
        round(dist)::int, hh.geofence_radius_meters;
    end if;
  end if;

  update chore_turns
     set status = 'done', completed_at = now(), completed_by = coalesce(me, t.assignee_id), note = p_note,
         completion_distance_m = case when hh.geofence_enabled then round(dist)::int else null end,
         completion_within_geofence = case when hh.geofence_enabled then within_geo else null end
   where id = p_turn
  returning * into t;

  select * into c from chores where id = t.chore_id;

  if c.cadence = 'scheduled' then
    perform materialize_schedule(t.chore_id);
  else
    perform top_up_queue(t.chore_id);
  end if;

  insert into activity_log (household_id, actor_id, verb, summary, metadata)
  select t.household_id, t.assignee_id, 'completed_chore',
         p.full_name || ' did ' || c.name,
         jsonb_build_object('chore_id', c.id, 'turn_id', t.id, 'emoji', c.emoji)
  from profiles p where p.id = t.assignee_id;

  return t;
end;
$$;

create or replace function kiosk_complete_turn(
  p_household uuid,
  p_turn      uuid,
  p_profile   uuid,
  p_note      text default null
)
returns chore_turns
language plpgsql
security definer
set search_path = public
as $$
declare
  t chore_turns%rowtype;
  c chores%rowtype;
begin
  if not exists (select 1 from profiles where id = p_profile and household_id = p_household) then
    raise exception 'not a member of this household';
  end if;

  select * into t from chore_turns where id = p_turn and household_id = p_household for update;
  if not found then raise exception 'turn not found'; end if;
  if t.status = 'done' then return t; end if;

  update chore_turns
     set status = 'done', completed_at = now(), completed_by = p_profile, note = p_note
   where id = p_turn
  returning * into t;

  select * into c from chores where id = t.chore_id;

  if c.cadence = 'scheduled' then
    perform materialize_schedule(t.chore_id);
  else
    perform top_up_queue(t.chore_id);
  end if;

  insert into activity_log (household_id, actor_id, verb, summary, metadata)
  select t.household_id, t.assignee_id, 'completed_chore',
         p.full_name || ' did ' || c.name,
         jsonb_build_object('chore_id', c.id, 'turn_id', t.id, 'emoji', c.emoji)
  from profiles p where p.id = t.assignee_id;

  return t;
end;
$$;


/**************************************************************************
 * 0033_per_chore_advance_and_admin_pass_skip.sql
 *************************************************************************/

-- Three related tightenings to the rotation-management tools:
--
-- 1. Get-ahead/defer become per-chore, not just household-wide. An admin may
--    want e.g. "Trash to curb" (a hard deadline every driveway pickup)
--    excluded from deferring, while "Dishes" stays flexible. Both default to
--    true, matching the feature's own "on by default" household toggle.
--
-- 2. Standing chores no longer excluded from get-ahead/defer. Structurally
--    they only ever have one pending turn, so there's no separate "future
--    turn" already sitting there the way there is for scheduled/on_demand —
--    but find_or_create_next_turn_for's walk-forward branch already
--    materializes one on demand (a standing chore's next occurrence is
--    always immediately assigned to whoever's next in the fixed rotation,
--    same call already used for on_demand). The result is the same swap as
--    every other cadence: briefly two turns are pending for this chore at
--    once (the swapped-in one and the swapped-out one), which resolves back
--    to standing's usual single pending turn as each one is completed —
--    exactly "reshuffling the queue," the same as the other two cadences.
--
-- 3. pass_turn/skip_turn on someone else's turn now requires the actor to
--    be a household admin, not just allow_member_cross_complete — passing
--    or skipping affects someone else's rotation credit/fairness in a way
--    completing a chore for them doesn't, so it gets a stricter gate.
--    Acting on your *own* turn is unaffected either way.

alter table chores
  add column if not exists allow_get_ahead boolean not null default true,
  add column if not exists allow_defer     boolean not null default true;

/* ------------------------------------------------------------ chore admin */

drop function if exists create_chore(text, chore_cadence, text, text, smallint[], smallint, smallint, smallint, smallint, uuid[]);

create or replace function create_chore(
  p_name            text,
  p_cadence         chore_cadence,
  p_emoji           text default '🧹',
  p_description     text default null,
  p_days_of_week    smallint[] default '{}',
  p_interval_weeks  smallint default 1,
  p_due_hour        smallint default 20,
  p_queue_depth     smallint default 4,
  p_lookahead_days  smallint default 21,
  p_profile_ids     uuid[] default '{}',
  p_allow_get_ahead boolean default true,
  p_allow_defer     boolean default true
)
returns chores
language plpgsql
security definer
set search_path = public
as $$
declare
  hh        uuid;
  next_sort smallint;
  new_chore chores%rowtype;
begin
  if not is_household_admin() then raise exception 'only an admin can add a chore'; end if;
  select household_id into hh from profiles where id = auth.uid();
  if hh is null then raise exception 'you are not in a household'; end if;
  if coalesce(trim(p_name), '') = '' then raise exception 'give it a name'; end if;

  select coalesce(max(sort_order), 0) + 1 into next_sort from chores where household_id = hh;

  insert into chores (
    household_id, name, emoji, description, cadence,
    days_of_week, interval_weeks, due_hour, queue_depth, lookahead_days, sort_order,
    allow_get_ahead, allow_defer
  )
  values (
    hh, trim(p_name), coalesce(nullif(trim(p_emoji), ''), '🧹'),
    nullif(trim(coalesce(p_description, '')), ''), p_cadence,
    coalesce(p_days_of_week, '{}'), greatest(coalesce(p_interval_weeks, 1), 1),
    coalesce(p_due_hour, 20), greatest(coalesce(p_queue_depth, 4), 1),
    greatest(coalesce(p_lookahead_days, 21), 1), next_sort,
    coalesce(p_allow_get_ahead, true), coalesce(p_allow_defer, true)
  )
  returning * into new_chore;

  if p_profile_ids is not null and array_length(p_profile_ids, 1) is not null then
    insert into chore_rotation (chore_id, profile_id, position)
    select new_chore.id, t.pid, t.ord - 1
    from unnest(p_profile_ids) with ordinality as t(pid, ord)
    where exists (select 1 from profiles where id = t.pid and household_id = hh);
  end if;

  if new_chore.cadence = 'scheduled' then
    perform materialize_schedule(new_chore.id);
  else
    perform top_up_queue(new_chore.id);
  end if;

  insert into activity_log (household_id, actor_id, verb, summary, metadata)
  values (hh, auth.uid(), 'created_chore', new_chore.name || ' was added to the board',
          jsonb_build_object('chore_id', new_chore.id, 'emoji', new_chore.emoji));

  return new_chore;
end;
$$;

drop function if exists update_chore(uuid, text, text, text, chore_cadence, smallint[], smallint, smallint, smallint, smallint, smallint);

create or replace function update_chore(
  p_chore           uuid,
  p_name            text default null,
  p_emoji           text default null,
  p_description     text default null,
  p_cadence         chore_cadence default null,
  p_days_of_week    smallint[] default null,
  p_interval_weeks  smallint default null,
  p_due_hour        smallint default null,
  p_queue_depth     smallint default null,
  p_lookahead_days  smallint default null,
  p_sort_order      smallint default null,
  p_allow_get_ahead boolean default null,
  p_allow_defer     boolean default null
)
returns chores
language plpgsql
security definer
set search_path = public
as $$
declare
  hh              uuid;
  before          chores%rowtype;
  after           chores%rowtype;
  cadence_changed boolean;
begin
  if not is_household_admin() then raise exception 'only an admin can edit a chore'; end if;
  select household_id into hh from profiles where id = auth.uid();

  select * into before from chores where id = p_chore and household_id = hh;
  if not found then raise exception 'that chore is not in your household'; end if;

  update chores set
    name             = coalesce(nullif(trim(p_name), ''), name),
    emoji            = coalesce(nullif(trim(p_emoji), ''), emoji),
    description      = case when p_description is not null
                            then nullif(trim(p_description), '') else description end,
    cadence          = coalesce(p_cadence, cadence),
    days_of_week     = coalesce(p_days_of_week, days_of_week),
    interval_weeks   = coalesce(p_interval_weeks, interval_weeks),
    due_hour         = coalesce(p_due_hour, due_hour),
    queue_depth      = coalesce(p_queue_depth, queue_depth),
    lookahead_days   = coalesce(p_lookahead_days, lookahead_days),
    sort_order       = coalesce(p_sort_order, sort_order),
    allow_get_ahead  = coalesce(p_allow_get_ahead, allow_get_ahead),
    allow_defer      = coalesce(p_allow_defer, allow_defer)
  where id = p_chore
  returning * into after;

  cadence_changed :=
    after.cadence        is distinct from before.cadence or
    after.days_of_week   is distinct from before.days_of_week or
    after.interval_weeks is distinct from before.interval_weeks or
    after.due_hour       is distinct from before.due_hour or
    after.queue_depth    is distinct from before.queue_depth;

  if cadence_changed then
    delete from chore_turns where chore_id = p_chore and status = 'pending';
    if after.cadence = 'scheduled' then
      perform materialize_schedule(p_chore);
    else
      perform top_up_queue(p_chore);
    end if;
  end if;

  return after;
end;
$$;

/* ---------------------------------------------------------- get_ahead/defer */

create or replace function get_ahead(p_chore uuid)
returns chore_turns
language plpgsql
security definer
set search_path = public
as $$
declare
  me             uuid := auth.uid();
  c              chores%rowtype;
  current_turn   chore_turns%rowtype;
  my_turn        chore_turns%rowtype;
  current_holder uuid;
  mod_enabled    boolean;
  mod_settings   jsonb;
  max_per_30d    int;
  uses_30d       int;
begin
  select * into c from chores where id = p_chore;
  if not found then raise exception 'chore not found'; end if;
  if not is_household_member(c.household_id) then raise exception 'not your household'; end if;
  if not c.allow_get_ahead then
    raise exception 'get-ahead is turned off for this chore';
  end if;
  if not exists (select 1 from chore_rotation where chore_id = p_chore and profile_id = me) then
    raise exception 'you are not in this chore''s rotation';
  end if;

  select enabled, settings into mod_enabled, mod_settings
    from household_modules where household_id = c.household_id and module = 'get_ahead';
  if not coalesce(mod_enabled, true) then raise exception 'get-ahead is turned off for this house'; end if;
  max_per_30d := coalesce((coalesce(mod_settings, '{}'::jsonb) #>> '{get_ahead,max_per_30d}')::int, 1);

  select * into current_turn from chore_turns
   where chore_id = p_chore and status = 'pending'
   order by turn_number limit 1;
  if not found then raise exception 'nothing pending on this chore'; end if;

  current_holder := current_turn.assignee_id;
  if current_holder = me then
    raise exception 'it is already your turn';
  end if;

  select count(*) into uses_30d from chore_advance_log
   where chore_id = p_chore and profile_id = me and kind = 'get_ahead'
     and created_at > now() - interval '30 days';
  if uses_30d >= max_per_30d then
    raise exception 'You have used get-ahead % time(s) in the last 30 days — the house limit is %.', uses_30d, max_per_30d;
  end if;

  my_turn := find_or_create_next_turn_for(p_chore, me, current_turn.turn_number);

  update chore_turns set assignee_id = me where id = current_turn.id;
  update chore_turns set assignee_id = current_holder where id = my_turn.id;

  insert into chore_advance_log (chore_id, profile_id, kind, turn_id)
  values (p_chore, me, 'get_ahead', current_turn.id);

  insert into activity_log (household_id, actor_id, verb, summary, metadata)
  select c.household_id, me, 'got_ahead', p.full_name || ' got ahead on ' || c.name,
         jsonb_build_object('chore_id', c.id, 'turn_id', current_turn.id, 'emoji', c.emoji)
  from profiles p where p.id = me;

  select * into current_turn from chore_turns where id = current_turn.id;
  return current_turn;
end;
$$;

create or replace function defer_turn(p_turn uuid)
returns chore_turns
language plpgsql
security definer
set search_path = public
as $$
declare
  me           uuid := auth.uid();
  t            chore_turns%rowtype;
  c            chores%rowtype;
  next_person  uuid;
  other_turn   chore_turns%rowtype;
  n            int;
  cur_pos      int;
  cand         uuid;
  mod_enabled  boolean;
  mod_settings jsonb;
  max_per_30d  int;
  uses_30d     int;
begin
  select * into t from chore_turns where id = p_turn for update;
  if not found then raise exception 'turn not found'; end if;
  if not is_household_member(t.household_id) then raise exception 'not your household'; end if;
  if t.status <> 'pending' then raise exception 'that turn is not pending'; end if;
  if me is distinct from t.assignee_id then raise exception 'you can only defer your own turn'; end if;

  select * into c from chores where id = t.chore_id;
  if not c.allow_defer then
    raise exception 'defer is turned off for this chore';
  end if;

  select enabled, settings into mod_enabled, mod_settings
    from household_modules where household_id = c.household_id and module = 'get_ahead';
  if not coalesce(mod_enabled, true) then raise exception 'get-ahead/defer is turned off for this house'; end if;
  max_per_30d := coalesce((coalesce(mod_settings, '{}'::jsonb) #>> '{defer,max_per_30d}')::int, 1);

  select count(*) into uses_30d from chore_advance_log
   where chore_id = t.chore_id and profile_id = me and kind = 'defer'
     and created_at > now() - interval '30 days';
  if uses_30d >= max_per_30d then
    raise exception 'You have deferred % time(s) in the last 30 days — the house limit is %.', uses_30d, max_per_30d;
  end if;

  select count(*) into n from chore_rotation where chore_id = t.chore_id;
  if n <= 1 then raise exception 'no one else in the rotation to defer to'; end if;

  select position into cur_pos from chore_rotation where chore_id = t.chore_id and profile_id = me;
  if cur_pos is null then raise exception 'you are not in this chore''s rotation'; end if;

  next_person := null;
  for i in 1..n - 1 loop
    select profile_id into cand from chore_rotation
     where chore_id = t.chore_id and position = (cur_pos + i) % n;
    if not is_away_at(cand, coalesce(t.due_at, now())) then
      next_person := cand;
      exit;
    end if;
  end loop;

  if next_person is null then
    raise exception 'everyone else is away — pass or skip instead';
  end if;

  other_turn := find_or_create_next_turn_for(t.chore_id, next_person, t.turn_number);

  update chore_turns set assignee_id = next_person where id = t.id;
  update chore_turns set assignee_id = me where id = other_turn.id;

  insert into chore_advance_log (chore_id, profile_id, kind, turn_id)
  values (t.chore_id, me, 'defer', p_turn);

  insert into activity_log (household_id, actor_id, verb, summary, metadata)
  select t.household_id, me, 'deferred_chore', p.full_name || ' pushed back ' || c.name,
         jsonb_build_object('chore_id', c.id, 'turn_id', t.id, 'emoji', c.emoji)
  from profiles p where p.id = me;

  select * into t from chore_turns where id = t.id;
  return t;
end;
$$;

/* ----------------------------------------------------- admin-only pass/skip */

-- Acting on your own turn is unaffected. Acting on someone else's now
-- requires being a household admin, replacing the allow_member_cross_complete
-- check that used to gate this the same as complete_turn — passing or
-- skipping affects someone else's rotation fairness, unlike completing a
-- chore for them.
create or replace function skip_turn(p_turn uuid, p_note text default null)
returns chore_turns
language plpgsql
security definer
set search_path = public
as $$
declare
  t chore_turns%rowtype;
  c chores%rowtype;
  me uuid := auth.uid();
begin
  select * into t from chore_turns where id = p_turn for update;
  if not found then
    raise exception 'turn not found';
  end if;
  if not is_household_member(t.household_id) then
    raise exception 'not your household';
  end if;
  if t.status <> 'pending' then
    raise exception 'that turn is not pending';
  end if;

  if me is distinct from t.assignee_id then
    if not is_household_admin() then
      raise exception 'only an admin can skip this for someone else';
    end if;
  end if;

  update chore_turns
     set status = 'skipped', completed_at = now(), completed_by = me, note = p_note
   where id = p_turn
  returning * into t;

  select * into c from chores where id = t.chore_id;

  if c.cadence = 'scheduled' then
    perform materialize_schedule(t.chore_id);
  else
    perform top_up_queue(t.chore_id);
  end if;

  insert into activity_log (household_id, actor_id, verb, summary, metadata)
  select t.household_id, me,
         'skipped_chore',
         case when me is distinct from t.assignee_id
              then p.full_name || ' skipped ' || c.name || ' for ' || a.full_name
              else p.full_name || ' skipped ' || c.name
         end,
         jsonb_build_object('chore_id', c.id, 'turn_id', t.id, 'emoji', c.emoji)
  from profiles p
  join profiles a on a.id = t.assignee_id
  where p.id = coalesce(me, t.assignee_id);

  return t;
end;
$$;

create or replace function pass_turn(p_turn uuid, p_note text default null)
returns chore_turns
language plpgsql
security definer
set search_path = public
as $$
declare
  t          chore_turns%rowtype;
  c          chores%rowtype;
  me         uuid := auth.uid();
  n          int;
  cur_pos    int;
  at         timestamptz;
  next_id    uuid;
  cand       uuid;
begin
  select * into t from chore_turns where id = p_turn for update;
  if not found then raise exception 'turn not found'; end if;
  if not is_household_member(t.household_id) then raise exception 'not your household'; end if;
  if t.status <> 'pending' then raise exception 'that turn is not pending'; end if;

  if me is distinct from t.assignee_id then
    if not is_household_admin() then
      raise exception 'only an admin can pass this for someone else';
    end if;
  end if;

  select count(*) into n from chore_rotation where chore_id = t.chore_id;
  if n <= 1 then
    raise exception 'no one else in the rotation to pass to';
  end if;

  select position into cur_pos from chore_rotation
   where chore_id = t.chore_id and profile_id = t.assignee_id;
  at := coalesce(t.due_at, now());

  if cur_pos is not null then
    for i in 1..n - 1 loop
      select profile_id into cand
      from chore_rotation
      where chore_id = t.chore_id and position = (cur_pos + i) % n;
      if not is_away_at(cand, at) then
        next_id := cand;
        exit;
      end if;
    end loop;
  end if;

  if next_id is null then
    raise exception 'everyone else is away — skip the task instead';
  end if;

  update chore_turns
     set assignee_id = next_id, note = coalesce(p_note, note)
   where id = p_turn
   returning * into t;

  select * into c from chores where id = t.chore_id;

  insert into activity_log (household_id, actor_id, verb, summary, metadata)
  select t.household_id, me, 'passed_chore',
         p.full_name || ' passed ' || c.name || ' to ' || nx.full_name,
         jsonb_build_object('chore_id', c.id, 'turn_id', t.id, 'emoji', c.emoji)
  from profiles p, profiles nx
  where p.id = coalesce(me, t.assignee_id) and nx.id = next_id;

  return t;
end;
$$;
